const lessons = [
{num:1,time:"00:00:00,000 --> 00:00:03,120",arabic:"كَوْكَبُنَا كَصُنْدُوقِ كُنُوزٍ عَظِيمٍ",segs:[{ar:"كَوْكَبُنَا",uz:"sayyoramiz"},{ar:"كَمَا",uz:"xuddi"},{ar:"صُنْدُوقِ كُنُوزٍ عَظِيمٍ",uz:"ulkan xazina sandig‘idek"}],full_uz:"Sayyoramiz ulkan xazina sandig‘iga o‘xshaydi.",note:null},
{num:2,time:"00:00:03,120 --> 00:00:09,019",arabic:"أَوْدَعَ اللَّهُ فِيهِ مِنْ عَجَائِبِ صُنْعِهِ مَا يُدْهِشُ الْقُلُوبَ قَبْلَ الْأَبْصَارِ",segs:[{ar:"أَوْدَعَ اللَّهُ فِيهِ",uz:"Alloh unda joyladi"},{ar:"مِنْ عَجَائِبِ صُنْعِهِ",uz:"O‘z yaratishining ajoyibotlaridan"},{ar:"مَا يُدْهِشُ الْقُلُوبَ",uz:"qalblarni hayratga soladigan narsalarni"},{ar:"قَبْلَ الْأَبْصَارِ",uz:"ko‘zlarni hayratga solishidan oldin"}],full_uz:"Alloh unda O‘z yaratishining qalblarni ko‘zlardan ham avval hayratga soladigan ajoyibotlarini joylagan.",note:"أَوْدَعَ — joylashtirmoq, omonat qilmoq."},
{num:3,time:"00:00:09,019 --> 00:00:19,980",arabic:"مِنْ أَطْلَالِ حَضَارَاتٍ خَبَتْ أَضْوَاؤُهَا",segs:[{ar:"مِنْ أَطْلَالِ حَضَارَاتٍ",uz:"sivilizatsiyalar xarobalaridan"},{ar:"خَبَتْ أَضْوَاؤُهَا",uz:"chiroqlari so‘ngan"}],full_uz:"Chiroqlari so‘ngan qadimiy sivilizatsiyalar xarobalaridan.",note:"أَطْلَالٌ — xarobalar, qadimiy qoldiqlar."},
{num:4,time:"00:00:19,980 --> 00:00:26,120",arabic:"إِلَى مَنَاظِرَ خَيَالِيَّةٍ رَسَمَتْهَا يَدُ الْخَالِقِ بِحِكْمَةٍ وَإِتْقَانٍ",segs:[{ar:"إِلَى مَنَاظِرَ خَيَالِيَّةٍ",uz:"hayoliy manzaralargacha"},{ar:"رَسَمَتْهَا يَدُ الْخَالِقِ",uz:"ularni Yaratuvchining qo‘li chizgan"},{ar:"بِحِكْمَةٍ وَإِتْقَانٍ",uz:"hikmat va mukammallik bilan"}],full_uz:"Yaratuvchining qo‘li hikmat va mukammallik bilan chizgan hayoliy manzaralargacha.",note:"إِتْقَانٌ — mukammal bajarish, puxtalik."},
{num:5,time:"00:00:26,120 --> 00:00:28,900",arabic:"فِي كُلِّ زَاوِيَةٍ مِنَ الْأَرْضِ",segs:null,full_uz:"Yerning har bir burchagida.",note:null},
{num:6,time:"00:00:28,899 --> 00:00:33,759",arabic:"قِصَّةٌ تَرْوِي آيَةً مِنْ آيَاتِ الْجَمَالِ",segs:[{ar:"قِصَّةٌ",uz:"bir hikoya"},{ar:"تَرْوِي",uz:"hikoya qiladi"},{ar:"آيَةً مِنْ آيَاتِ الْجَمَالِ",uz:"go‘zallik oyatlaridan bir oyatni"}],full_uz:"Har birida go‘zallik oyatlaridan birini hikoya qiluvchi bir voqea bor.",note:"تَرْوِي — hikoya qilmoq, bayon qilmoq."},
{num:7,time:"00:00:33,759 --> 00:00:45,519",arabic:"لَيْسَتْ هَذِهِ الْأَمَاكِنُ مُجَرَّدَ وَجَهَاتٍ تُزَارُ",segs:[{ar:"لَيْسَتْ هَذِهِ الْأَمَاكِنُ",uz:"bu joylar emas"},{ar:"مُجَرَّدَ وَجَهَاتٍ",uz:"shunchaki manzillar"},{ar:"تُزَارُ",uz:"ziyorat qilinadigan"}],full_uz:"Bu joylar shunchaki borib ko‘riladigan manzillar emas.",note:null},
{num:8,time:"00:00:45,519 --> 00:00:47,700",arabic:"بَلْ ذَاكِرَةٌ حَيَّةٌ",segs:null,full_uz:"Balki tirik xotiradir.",note:null},
{num:9,time:"00:00:47,700 --> 00:00:50,619",arabic:"تَنْبِضُ بِتَارِيخِ الْإِنْسَانِ",segs:null,full_uz:"U insoniyat tarixi bilan urib turadi.",note:"تَنْبِضُ — urib turmoq, jo‘sh urmoq."},
{num:10,time:"00:00:50,619 --> 00:00:55,820",arabic:"وَتَشْهَدُ لِعَظَمَةِ الْإِلَهِ الَّذِي جَمَعَ بَيْنَ الْجَمَالِ وَالْبَقَاءِ",segs:[{ar:"وَتَشْهَدُ لِعَظَمَةِ الْإِلَهِ",uz:"va Ilohning buyukligiga guvohlik beradi"},{ar:"الَّذِي جَمَعَ بَيْنَ الْجَمَالِ وَالْبَقَاءِ",uz:"U go‘zallik bilan abadiylikni jamlagan"}],full_uz:"Va go‘zallik bilan abadiylikni jamlagan Ilohning buyukligiga guvohlik beradi.",note:null},
{num:11,time:"00:00:55,820 --> 00:01:09,579",arabic:"رِحْلَتُنَا الْيَوْمَ إِلَى أَرْبَعِينَ مَوْقِعًا مِنْ رَوَائِعِ التُّرَاثِ الْعَالَمِيِّ لِلْيُونِسْكُو",segs:[{ar:"رِحْلَتُنَا الْيَوْمَ",uz:"bugungi sayohatimiz"},{ar:"إِلَى أَرْبَعِينَ مَوْقِعًا",uz:"qirqta joyga"},{ar:"مِنْ رَوَائِعِ التُّرَاثِ الْعَالَمِيِّ",uz:"jahon merosining ajoyib durdonalaridan"},{ar:"لِلْيُونِسْكُو",uz:"YUNESKOga tegishli"}],full_uz:"Bugungi sayohatimiz YUNESKOning jahon merosi ajoyibotlaridan qirqta joyga.",note:"رَوَائِعُ — ajoyib durdonalar."},
{num:12,time:"00:01:09,579 --> 00:01:14,439",arabic:"مَحَطَّاتٌ خَالِدَةٌ تَهْمِسُ بِأَنَّ الْجَمَالَ لَيْسَ صُدْفَةً",segs:[{ar:"مَحَطَّاتٌ خَالِدَةٌ",uz:"abadiy manzillar"},{ar:"تَهْمِسُ بِأَنَّ",uz:"shivirlaydi-ki"},{ar:"الْجَمَالَ لَيْسَ صُدْفَةً",uz:"go‘zallik tasodif emas"}],full_uz:"Abadiy manzillar go‘zallik tasodif emasligini shivirlaydi.",note:"مَحَطَّةٌ — manzil, bekat."},
{num:13,time:"00:01:14,439 --> 00:01:18,260",arabic:"بَلْ صَنْعَةٌ مِنْ صَانِعٍ لَا يُشْبِهُهُ أَحَدٌ",segs:[{ar:"بَلْ صَنْعَةٌ",uz:"balki bir san’at asari"},{ar:"مِنْ صَانِعٍ",uz:"bir Yaratuvchining"},{ar:"لَا يُشْبِهُهُ أَحَدٌ",uz:"unga hech kim o‘xshamaydi"}],full_uz:"Balki hech kim o‘xshamaydigan Yaratganning san’atidir.",note:"صَنْعَةٌ — mahorat bilan yaratilgan narsa."},
{num:14,time:"00:01:18,260 --> 00:01:26,060",arabic:"فَاحْمِلْ جَوَازَ سَفَرِكَ الْخَيَالِيَّ",segs:[{ar:"فَاحْمِلْ",uz:"shuning uchun olib ol"},{ar:"جَوَازَ سَفَرِكَ الْخَيَالِيَّ",uz:"xayoliy pasportingni"}],full_uz:"Shunday ekan, xayoliy pasportingni ol.",note:"جَوَازُ سَفَرٍ — pasport."},
{num:15,time:"00:01:26,060 --> 00:01:30,680",arabic:"وَشُدَّ الرِّحَالَ مَعَنَا فِي رِحْلَةٍ عَبْرَ الزَّمَانِ وَالْمَكَانِ",segs:[{ar:"وَشُدَّ الرِّحَالَ مَعَنَا",uz:"biz bilan yo‘lga chiq"},{ar:"فِي رِحْلَةٍ",uz:"sayohatda"},{ar:"عَبْرَ الزَّمَانِ وَالْمَكَانِ",uz:"zamon va makon bo‘ylab"}],full_uz:"Biz bilan zamon va makon bo‘ylab sayohatga chiq.",note:"شَدَّ الرِّحَالَ — safarga otlanmoq."},
{num:16,time:"00:01:30,680 --> 00:01:35,480",arabic:"نُصْغِي فِيهَا لِنِدَاءِ الْأَرْضِ وَهِيَ تُسَبِّحُ بِاسْمِ رَبِّهَا",segs:[{ar:"نُصْغِي فِيهَا",uz:"unda quloq tutamiz"},{ar:"لِنِدَاءِ الْأَرْضِ",uz:"yerning nidosiga"},{ar:"وَهِيَ تُسَبِّحُ بِاسْمِ رَبِّهَا",uz:"u Robbisining nomi bilan tasbeh aytayotganida"}],full_uz:"Unda Robbisining nomi bilan tasbeh aytayotgan yerning nidosiga quloq tutamiz.",note:"نُصْغِي — diqqat bilan quloq tutmoq."},
{num:17,time:"00:01:41,560 --> 00:01:43,640",arabic:"وَبِنِهَايَةِ هَذِهِ الرِّحْلَةِ",segs:null,full_uz:"Bu sayohatning oxirida.",note:null},
{num:18,time:"00:01:43,640 --> 00:01:48,240",arabic:"قَدْ تَجِدُ قَلْبَكَ يَحِنُّ لِزِيَارَةِ كُلِّ مَوْضِعٍ مِنْهَا",segs:[{ar:"قَدْ تَجِدُ قَلْبَكَ",uz:"qalbingni topishing mumkin"},{ar:"يَحِنُّ",uz:"sog‘inishini"},{ar:"لِزِيَارَةِ كُلِّ مَوْضِعٍ مِنْهَا",uz:"ularning har bir joyiga borishni"}],full_uz:"Sayohat oxirida qalbingiz ularning har birini ziyorat qilishni sog‘inishi mumkin.",note:"حَنَّ إِلَى — sog‘inmoq, intilmoq."},
{num:19,time:"00:01:48,239 --> 00:01:51,420",arabic:"لَا بَاحِثًا عَنِ الْجَمَالِ فَحَسْبُ",segs:null,full_uz:"Faqat go‘zallikni izlab emas.",note:null},
{num:20,time:"00:01:51,420 --> 00:01:56,640",arabic:"بَلْ عَنْ أَثَرٍ مِنْ آثَارِ الْخَالِقِ فِي كُلِّ حَجَرٍ وَشَجَرٍ",segs:[{ar:"بَلْ عَنْ أَثَرٍ",uz:"balki bir asarni"},{ar:"مِنْ آثَارِ الْخَالِقِ",uz:"Yaratuvchining asarlaridan"},{ar:"فِي كُلِّ حَجَرٍ وَشَجَرٍ",uz:"har bir tosh va daraxtda"}],full_uz:"Balki har bir tosh va daraxtdagi Yaratuvchining asarlaridan bir izni izlab.",note:"أَثَرٌ — iz, asar, belgi."},
{num:21,time:"00:01:56,640 --> 00:02:01,979",arabic:"نَرْحَلُ إِلَى قَلْبِ إِفْرِيقِيَا",segs:[{ar:"نَرْحَلُ",uz:"yo‘l olamiz"},{ar:"إِلَى قَلْبِ إِفْرِيقِيَا",uz:"Afrikaning yuragiga"}],full_uz:"Afrikaning yuragiga yo‘l olamiz.",note:null},
{num:22,time:"00:02:01,979 --> 00:02:06,879",arabic:"حَيْثُ تَمْتَدُّ الْحَيَاةُ عَلَى أَوْسَعِ مَشْهَدٍ عَرَفَتْهُ الْعَيْنُ",segs:[{ar:"حَيْثُ تَمْتَدُّ الْحَيَاةُ",uz:"u yerda hayot yoyiladi"},{ar:"عَلَى أَوْسَعِ مَشْهَدٍ",uz:"eng keng manzarada"},{ar:"عَرَفَتْهُ الْعَيْنُ",uz:"ko‘z ko‘rgan"}],full_uz:"U yerda hayot ko‘z ko‘rgan eng keng manzarada yoyilgan.",note:null},
{num:23,time:"00:02:06,879 --> 00:02:10,519",arabic:"حَدِيقَةُ سِيرِنْغِيتِي الْوَطَنِيَّةُ",segs:null,full_uz:"Serengeti milliy bog‘i.",note:null},
{num:24,time:"00:02:10,519 --> 00:02:14,479",arabic:"سِيرِنْغِيتِي نَاشِنَالْ بَارْكْ فِي تَنْزَانِيَا",segs:null,full_uz:"Tanzaniyadagi Serengeti National Park.",note:null},
{num:25,time:"00:02:18,240 --> 00:02:23,900",arabic:"أَرْضٌ لَا تَنْتَهِي",segs:null,full_uz:"Tugamaydigan yer.",note:null},
{num:26,time:"00:02:23,900 --> 00:02:28,080",arabic:"تَتَمَوَّجُ فِيهَا الْأَعْشَابُ الذَّهَبِيَّةُ تَحْتَ شَمْسٍ لَا تَغِيبُ",segs:[{ar:"تَتَمَوَّجُ فِيهَا الْأَعْشَابُ الذَّهَبِيَّةُ",uz:"unda oltin rangli o‘tlar to‘lqinlanadi"},{ar:"تَحْتَ شَمْسٍ لَا تَغِيبُ",uz:"botmaydigan quyosh ostida"}],full_uz:"U yerda oltin rangli o‘tlar botmaydigan quyosh ostida to‘lqinlanadi.",note:"تَمَوَّجَ — to‘lqinlanmoq."},
{num:27,time:"00:02:28,080 --> 00:02:32,600",arabic:"وَفِيهَا تَتَجَلَّى قُدْرَةُ اللَّهِ فِي أَدَقِّ صُوَرِهَا",segs:[{ar:"وَفِيهَا",uz:"va unda"},{ar:"تَتَجَلَّى قُدْرَةُ اللَّهِ",uz:"Allohning qudrati namoyon bo‘ladi"},{ar:"فِي أَدَقِّ صُوَرِهَا",uz:"eng nozik ko‘rinishlarida"}],full_uz:"Unda Allohning qudrati eng nozik ko‘rinishlarida namoyon bo‘ladi.",note:"تَجَلَّى — namoyon bo‘lmoq."},
{num:28,time:"00:02:32,600 --> 00:02:39,020",arabic:"حِينَ تَتَحَرَّكُ مَلَايِينُ الْمَخْلُوقَاتِ فِي تَوَازُنٍ بَدِيعٍ لَا يُخْطِئُ مِيزَانَهُ",segs:[{ar:"حِينَ تَتَحَرَّكُ مَلَايِينُ الْمَخْلُوقَاتِ",uz:"millionlab mavjudotlar harakatlanganda"},{ar:"فِي تَوَازُنٍ بَدِيعٍ",uz:"ajoyib muvozanatda"},{ar:"لَا يُخْطِئُ مِيزَانَهُ",uz:"uning mezoni xato qilmaydi"}],full_uz:"Millionlab mavjudotlar mezoni xato qilmaydigan ajoyib muvozanatda harakatlanganda.",note:"تَوَازُنٌ — muvozanat."},
{num:29,time:"00:02:39,020 --> 00:02:47,520",arabic:"إِنَّهَا الْهِجْرَةُ الْعُظْمَى",segs:null,full_uz:"Bu buyuk ko‘chishdir.",note:"الْهِجْرَةُ الْعُظْمَى — buyuk migratsiya."},
{num:30,time:"00:02:47,520 --> 00:02:51,120",arabic:"حِينَ تَعْبُرُ أَكْثَرُ مِنْ مِلْيُونَيْ غَنَمَةٍ بَرِّيَّةٍ",segs:[{ar:"حِينَ تَعْبُرُ",uz:"o‘tganida"},{ar:"أَكْثَرُ مِنْ مِلْيُونَيْ",uz:"ikki milliondan ortiq"},{ar:"غَنَمَةٍ بَرِّيَّةٍ",uz:"yovvoyi kiyiklar"}],full_uz:"Ikki milliondan ortiq yovvoyi kiyik o‘tganida.",note:null},
{num:31,time:"00:02:51,120 --> 00:02:53,219",arabic:"وَحِمَارٌ وَحْشِيٌّ وَغَزَالٌ",segs:null,full_uz:"Zebralar va kiyiklar ham.",note:null},
{num:32,time:"00:02:53,219 --> 00:02:55,820",arabic:"بَاحِثَةً عَنِ الْمَاءِ وَالْمَرْعَى",segs:null,full_uz:"Suv va yaylov izlab.",note:"مَرْعًى — yaylov."},
{num:33,time:"00:02:55,820 --> 00:02:58,840",arabic:"تَتْبَعُهَا الْأُسُودُ وَالْفُهُودُ وَالتَّمَاسِيحُ",segs:[{ar:"تَتْبَعُهَا الْأُسُودُ",uz:"uning ortidan sherlar boradi"},{ar:"وَالْفُهُودُ",uz:"qoplonlar"},{ar:"وَالتَّمَاسِيحُ",uz:"va timsohlar"}],full_uz:"Ularning ortidan sherlar, qoplonlar va timsohlar ergashadi.",note:null},
{num:34,time:"00:02:58,840 --> 00:03:01,660",arabic:"فِي مَشْهَدٍ يَخْتَصِرُ مَعْنَى الْحَيَاةِ",segs:[{ar:"فِي مَشْهَدٍ",uz:"bir manzarada"},{ar:"يَخْتَصِرُ مَعْنَى الْحَيَاةِ",uz:"hayot ma’nosini mujassamlashtiradigan"}],full_uz:"Hayot ma’nosini mujassamlashtiradigan bir manzarada.",note:"يَخْتَصِرُ — qisqacha ifodalamoq, mujassamlashtirmoq."},
{num:35,time:"00:03:01,660 --> 00:03:03,420",arabic:"صِرَاعٌ وَبَقَاءٌ",segs:null,full_uz:"Kurash va yashab qolish.",note:null},
{num:36,time:"00:03:03,420 --> 00:03:05,280",arabic:"لَكِنَّهُ فِي الْحَقِيقَةِ",segs:null,full_uz:"Ammo aslida bu.",note:null},
{num:37,time:"00:03:05,280 --> 00:03:09,340",arabic:"نِظَامٌ كَتَبَهُ اللَّهُ بِحِكْمَةٍ لَا يَعْرِفُهَا إِلَّا هُوَ",segs:[{ar:"نِظَامٌ",uz:"bir tizim"},{ar:"كَتَبَهُ اللَّهُ",uz:"uni Alloh belgilagan"},{ar:"بِحِكْمَةٍ",uz:"hikmat bilan"},{ar:"لَا يَعْرِفُهَا إِلَّا هُوَ",uz:"uni faqat U biladi"}],full_uz:"Ammo aslida bu Alloh hikmat bilan belgilagan va uni faqat O‘zi biladigan bir tizimdir.",note:null},
{num:38,time:"00:03:09,340 --> 00:03:24,480",arabic:"فِي سِيرِنْجِيتِي كُلُّ نَفَسٍ وَكُلُّ خُطْوَةٍ تُذَكِّرُكَ أَنَّ هَذَا الْكَوْنَ قَائِمٌ عَلَى مِيزَانٍ دَقِيقٍ",segs:[{ar:"فِي سِيرِنْجِيتِي",uz:"Serengetida"},{ar:"كُلُّ نَفَسٍ وَكُلُّ خُطْوَةٍ",uz:"har bir nafas va har bir qadam"},{ar:"تُذَكِّرُكَ",uz:"sizga eslatadi"},{ar:"أَنَّ هَذَا الْكَوْنَ قَائِمٌ عَلَى مِيزَانٍ دَقِيقٍ",uz:"bu koinot nozik bir muvozanatga qurilganini"}],full_uz:"Serengetida har bir nafas va har bir qadam bu koinot nozik bir muvozanatga qurilganini eslatadi.",note:"قَائِمٌ عَلَى — asoslangan, qurilgan."},
{num:39,time:"00:03:24,480 --> 00:03:32,140",arabic:"وَأَنَّ وَرَاءَ كُلِّ حَرَكَةٍ فِي الْبَرَارِي إِرَادَةً إِلَهِيَّةً تَحْفَظُ الْحَيَاةَ بِمِقْدَارٍ",segs:[{ar:"وَأَنَّ وَرَاءَ كُلِّ حَرَكَةٍ فِي الْبَرَارِي",uz:"va dashtlardagi har bir harakat ortida"},{ar:"إِرَادَةً إِلَهِيَّةً",uz:"ilohiy iroda borligini"},{ar:"تَحْفَظُ الْحَيَاةَ بِمِقْدَارٍ",uz:"hayotni o‘lchov bilan asraydigan"}],full_uz:"Va dashtlardagi har bir harakat ortida hayotni o‘lchov bilan asraydigan ilohiy iroda borligini.",note:"بِمِقْدَارٍ — o‘lchov bilan, me’yorida."},
{num:40,time:"00:03:32,139 --> 00:03:38,779",arabic:"لَكِنْ مَا وَرَاءَ مَشْهَدِ الْقُوَّةِ فِي سِيرِينْجِيتِي",segs:[{ar:"لَكِنْ",uz:"ammo"},{ar:"مَا وَرَاءَ مَشْهَدِ الْقُوَّةِ",uz:"kuch manzarasi ortida"},{ar:"فِي سِيرِينْجِيتِي",uz:"Serengetida"}],full_uz:"Ammo Serengetidagi kuch manzarasi ortida.",note:null},
{num:41,time:"00:03:38,779 --> 00:03:41,879",arabic:"تَنْبِضُ لَحَظَاتٌ مِنْ سُكُونٍ نَادِرٍ",segs:[{ar:"تَنْبِضُ لَحَظَاتٌ",uz:"lahzalar yashaydi"},{ar:"مِنْ سُكُونٍ نَادِرٍ",uz:"noyob sokinlikdan"}],full_uz:"Noyob sokinlik lahzalari ham yashaydi.",note:"سُكُونٌ — sokinlik, sukunat."},
{num:42,time:"00:03:41,879 --> 00:03:46,339",arabic:"حِينَ يُشْرِقُ الصَّبَاحُ عَلَى السَّافَانَا بِنُورِهِ الذَّهَبِيِّ",segs:[{ar:"حِينَ يُشْرِقُ الصَّبَاحُ",uz:"tong otganda"},{ar:"عَلَى السَّافَانَا",uz:"savannada"},{ar:"بِنُورِهِ الذَّهَبِيِّ",uz:"o‘zining oltin nuri bilan"}],full_uz:"Tong savannaga o‘zining oltin nuri bilan otganda.",note:null},
{num:43,time:"00:03:46,339 --> 00:03:49,839",arabic:"وَيَتَعَالَى دَوِيُّ الرَّعْدِ الْبَعِيدِ فَوْقَ السُّهُولِ",segs:[{ar:"وَيَتَعَالَى دَوِيُّ الرَّعْدِ الْبَعِيدِ",uz:"uzoqdagi momaqaldiroq gumburlaydi"},{ar:"فَوْقَ السُّهُولِ",uz:"tekisliklar ustida"}],full_uz:"Uzoqdagi momaqaldiroq tekisliklar uzra gumburlaganda.",note:"دَوِيٌّ — gumburlash, kuchli tovush."},
{num:44,time:"00:03:49,839 --> 00:03:55,459",arabic:"وَتَمْضِي الْأَفْيَالُ بِخُطُوَاتٍ وَاثِقَةٍ بَيْنَ الْأَعْشَابِ الطَّوِيلَةِ",segs:[{ar:"وَتَمْضِي الْأَفْيَالُ",uz:"fillar yuradi"},{ar:"بِخُطُوَاتٍ وَاثِقَةٍ",uz:"ishonchli qadamlar bilan"},{ar:"بَيْنَ الْأَعْشَابِ الطَّوِيلَةِ",uz:"baland o‘tlar orasidan"}],full_uz:"Fillar baland o‘tlar orasidan ishonchli qadamlar bilan yuradi.",note:"خُطُوَاتٌ وَاثِقَةٌ — dadil, ishonchli qadamlar."},
{num:45,time:"00:03:55,459 --> 00:03:58,959",arabic:"كَأَنَّهَا صَلَاةٌ صَامِتَةٌ فِي مِحْرَابِ الطَّبِيعَةِ",segs:[{ar:"كَأَنَّهَا صَلَاةٌ صَامِتَةٌ",uz:"go‘yo jimjit ibodat"},{ar:"فِي مِحْرَابِ الطَّبِيعَةِ",uz:"tabiat mehrobida"}],full_uz:"Go‘yo tabiat mehrobidagi jimjit ibodatdek.",note:"مِحْرَابٌ — mehrob."},
{num:46,time:"00:03:58,960 --> 00:04:10,480",arabic:"عَلَى امْتِدَادِ أَكْثَرَ مِنْ أَلْفَيْ كِيلُومِتْرٍ",segs:null,full_uz:"Ikki ming kilometrdan ortiq masofaga cho‘zilgan.",note:null},
{num:47,time:"00:04:10,480 --> 00:04:13,780",arabic:"عَلَى سَوَاحِلِ كْوِينْزْلَانْدَ فِي أُسْتْرَالِيَا",segs:[{ar:"عَلَى سَوَاحِلِ كْوِينْزْلَانْدَ",uz:"Kvinslend qirg‘oqlarida"},{ar:"فِي أُسْتْرَالِيَا",uz:"Avstraliyada"}],full_uz:"Avstraliyaning Kvinslend qirg‘oqlarida.",note:null},
{num:48,time:"00:04:13,780 --> 00:04:17,639",arabic:"يَمْتَدُّ أَضْخَمُ كَائِنٍ حَيٍّ عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"يَمْتَدُّ",uz:"cho‘zilib yotadi"},{ar:"أَضْخَمُ كَائِنٍ حَيٍّ",uz:"eng ulkan tirik mavjudot"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzidagi"}],full_uz:"Yer yuzidagi eng ulkan tirik mavjudot cho‘zilib yotadi.",note:null},
{num:49,time:"00:04:17,639 --> 00:04:20,980",arabic:"لَوْحَةٌ مِنْ حَيَاةٍ لَا تَنْتَهِي",segs:null,full_uz:"Tugamaydigan hayot manzarasi.",note:null},
{num:50,time:"00:04:20,980 --> 00:04:23,879",arabic:"إِنَّهُ الْحَاجِزُ الْمَرْجَانِيُّ الْعَظِيمُ",segs:null,full_uz:"Bu Buyuk To‘siq Rifi.",note:"الْحَاجِزُ الْمَرْجَانِيُّ الْعَظِيمُ — Great Barrier Reef."},
{num:51,time:"00:04:23,879 --> 00:04:26,319",arabic:"ذَا جْرَيْتْ بَارْيَرْ رِيفْ",segs:null,full_uz:"The Great Barrier Reef.",note:null},
{num:52,time:"00:04:26,319 --> 00:04:34,439",arabic:"مِنَ الْفَضَاءِ يُمْكِنُ رُؤْيَتُهُ كَوِشَاحٍ أَزْرَقَ يُطَوِّقُ الْقَارَّةَ",segs:[{ar:"مِنَ الْفَضَاءِ",uz:"kosmosdan"},{ar:"يُمْكِنُ رُؤْيَتُهُ",uz:"uni ko‘rish mumkin"},{ar:"كَوِشَاحٍ أَزْرَقَ",uz:"ko‘k sharf kabi"},{ar:"يُطَوِّقُ الْقَارَّةَ",uz:"qit’ani o‘rab turadigan"}],full_uz:"Kosmosdan uni qit’ani o‘rab turgan ko‘k sharf kabi ko‘rish mumkin.",note:"وِشَاحٌ — sharf, ro‘mol."},
{num:53,time:"00:04:34,439 --> 00:04:40,060",arabic:"لَكِنْ حِينَ تَغُوصُ تَحْتَهُ تَكْتَشِفُ عَالَمًا يَفُوقُ الْخَيَالَ",segs:[{ar:"لَكِنْ حِينَ تَغُوصُ تَحْتَهُ",uz:"ammo uning ostiga sho‘ng‘isangiz"},{ar:"تَكْتَشِفُ عَالَمًا",uz:"bir olamni kashf qilasiz"},{ar:"يَفُوقُ الْخَيَالَ",uz:"tasavvurdan ham oshib ketadigan"}],full_uz:"Ammo uning ostiga sho‘ng‘isangiz, tasavvurdan ham oshib ketadigan bir olamni kashf qilasiz.",note:"يَفُوقُ — oshib ketmoq, ustun kelmoq."},
{num:54,time:"00:04:40,060 --> 00:04:50,060",arabic:"غَابَاتٌ مِنَ الْمَرْجَانِ تَتَلَأْلَأُ بِأَلْوَانٍ لَا تُوجَدُ فِي لَوْحَاتِ الْبَشَرِ",segs:[{ar:"غَابَاتٌ مِنَ الْمَرْجَانِ",uz:"marjon o‘rmonlari"},{ar:"تَتَلَأْلَأُ بِأَلْوَانٍ",uz:"ranglarda yaltiraydi"},{ar:"لَا تُوجَدُ فِي لَوْحَاتِ الْبَشَرِ",uz:"insonlar suratlarida topilmaydigan"}],full_uz:"Marjon o‘rmonlari insonlar suratlarida uchramaydigan ranglarda yaltiraydi.",note:"تَتَلَأْلَأُ — yaltiramoq, jilvalanmoq."},
{num:55,time:"00:04:50,060 --> 00:04:55,719",arabic:"أَسْمَاكٌ نِيُونِيَّةٌ صَغِيرَةٌ تَسْبَحُ فِي انْسِجَامٍ مُذْهِلٍ",segs:[{ar:"أَسْمَاكٌ نِيُونِيَّةٌ صَغِيرَةٌ",uz:"kichik neon baliqlar"},{ar:"تَسْبَحُ فِي انْسِجَامٍ مُذْهِلٍ",uz:"hayratlanarli uyg‘unlikda suzadi"}],full_uz:"Kichik neon baliqlar hayratlanarli uyg‘unlikda suzadi.",note:"انْسِجَامٌ — uyg‘unlik."},
{num:56,time:"00:04:55,720 --> 00:05:00,220",arabic:"سُلَحْفَاةٌ بَحْرِيَّةٌ تَرْفْرِفُ كَأَنَّهَا تُحَلِّقُ",segs:[{ar:"سُلَحْفَاةٌ بَحْرِيَّةٌ",uz:"dengiz toshbaqalari"},{ar:"تَرْفْرِفُ",uz:"qanot qoqadi"},{ar:"كَأَنَّهَا تُحَلِّقُ",uz:"go‘yo uchayotgandek"}],full_uz:"Dengiz toshbaqalari go‘yo uchayotgandek suzadi.",note:"رَفْرَفَ — qanot qoqmoq, hilpiramoq."},
{num:57,time:"00:05:00,220 --> 00:05:05,840",arabic:"وَدَلَافِينُ تَمُرُّ بِجِوَارِكَ فِي رَقْصٍ صَامِتٍ يَمْلَؤُهُ الْفَرَحُ",segs:[{ar:"وَدَلَافِينُ تَمُرُّ بِجِوَارِكَ",uz:"delfinlar yoningizdan o‘tadi"},{ar:"فِي رَقْصٍ صَامِتٍ",uz:"jimjit raqsda"},{ar:"يَمْلَؤُهُ الْفَرَحُ",uz:"quvonchga to‘la"}],full_uz:"Delfinlar quvonchga to‘la jimjit raqsda yoningizdan o‘tadi.",note:null},
{num:58,time:"00:05:05,840 --> 00:05:15,140",arabic:"كُلُّ لَوْنٍ، كُلُّ وَمْضَةِ ضَوْءٍ، كُلُّ كَائِنٍ هُنَا",segs:[{ar:"كُلُّ لَوْنٍ",uz:"har bir rang"},{ar:"كُلُّ وَمْضَةِ ضَوْءٍ",uz:"har bir nur chaqnashi"},{ar:"كُلُّ كَائِنٍ هُنَا",uz:"bu yerdagi har bir mavjudot"}],full_uz:"Har bir rang, har bir nur chaqnashi, bu yerdagi har bir mavjudot.",note:"وَمْضَةٌ — chaqnash, yiltillash."},
{num:59,time:"00:05:15,140 --> 00:05:19,400",arabic:"يَرْوِي حِكَايَةً عَنْ دِقَّةِ الْخَلْقِ وَعَظَمَةِ الْمِيزَانِ",segs:[{ar:"يَرْوِي حِكَايَةً",uz:"bir hikoya so‘zlaydi"},{ar:"عَنْ دِقَّةِ الْخَلْقِ",uz:"yaratilishdagi aniqlik haqida"},{ar:"وَعَظَمَةِ الْمِيزَانِ",uz:"va muvozanatning buyukligi haqida"}],full_uz:"Yaratilishdagi aniqlik va muvozanatning buyukligi haqida hikoya so‘zlaydi.",note:null},
{num:60,time:"00:05:19,400 --> 00:05:24,760",arabic:"إِنَّهُ تَذْكِيرٌ بِأَنَّ الْأَرْضَ لَيْسَتْ مُجَرَّدَ مَوْطِنٍ لَنَا",segs:[{ar:"إِنَّهُ تَذْكِيرٌ",uz:"bu bir eslatmadir"},{ar:"بِأَنَّ الْأَرْضَ",uz:"Yer"},{ar:"لَيْسَتْ مُجَرَّدَ مَوْطِنٍ لَنَا",uz:"shunchaki bizning makonimiz emas"}],full_uz:"Bu Yer shunchaki biz yashaydigan makon emasligini eslatadi.",note:"مَوْطِنٌ — vatan, makon."},
{num:61,time:"00:05:24,759 --> 00:05:28,219",arabic:"بَلْ أَمَانَةٌ مُنِحَتْ لَنَا مِنَ اللَّهِ",segs:[{ar:"بَلْ أَمَانَةٌ",uz:"balki bir omonatdir"},{ar:"مُنِحَتْ لَنَا",uz:"bizga berilgan"},{ar:"مِنَ اللَّهِ",uz:"Alloh tomonidan"}],full_uz:"Balki Alloh tomonidan bizga berilgan omonatdir.",note:"أَمَانَةٌ — omonat."},
{num:62,time:"00:05:28,219 --> 00:05:32,860",arabic:"لِنُحَافِظَ عَلَيْهَا كَمَا نُحَافِظُ عَلَى الْحَيَاةِ نَفْسِهَا",segs:[{ar:"لِنُحَافِظَ عَلَيْهَا",uz:"uni asrashimiz uchun"},{ar:"كَمَا نُحَافِظُ عَلَى الْحَيَاةِ نَفْسِهَا",uz:"hayotning o‘zini asraganimizdek"}],full_uz:"Uni hayotning o‘zini asraganimizdek asrashimiz uchun.",note:null},
{num:63,time:"00:05:32,860 --> 00:05:39,319",arabic:"وَأَنْتَ وَاقِفٌ عَلَى سَطْحِ الْقَارِبِ",segs:null,full_uz:"Siz qayiq ustida turibsiz.",note:null},
{num:64,time:"00:05:39,319 --> 00:05:43,939",arabic:"تَنْظُرُ إِلَى الْأُفُقِ الْفِيرُوزِيِّ الْمُمْتَدِّ بِلَا نِهَايَةٍ",segs:[{ar:"تَنْظُرُ إِلَى الْأُفُقِ الْفِيرُوزِيِّ",uz:"feruza rangli ufqqa qaraysiz"},{ar:"الْمُمْتَدِّ بِلَا نِهَايَةٍ",uz:"cheksiz cho‘zilgan"}],full_uz:"Cheksiz cho‘zilgan feruza rangli ufqqa qaraysiz.",note:"فَيْرُوزِيٌّ — feruza rangli."},
{num:65,time:"00:05:43,939 --> 00:05:46,839",arabic:"تَشْعُرُ بِالدَّهْشَةِ وَالِامْتِنَانِ مَعًا",segs:[{ar:"تَشْعُرُ بِالدَّهْشَةِ",uz:"hayratni his qilasiz"},{ar:"وَالِامْتِنَانِ مَعًا",uz:"va minnatdorlikni birga"}],full_uz:"Bir vaqtning o‘zida hayrat va minnatdorlikni his qilasiz.",note:"الِامْتِنَانُ — minnatdorlik."},
{num:66,time:"00:05:46,839 --> 00:05:50,599",arabic:"فَهَذَا الْمَكَانُ لَيْسَ مُجَرَّدَ بَحْرٍ",segs:[{ar:"فَهَذَا الْمَكَانُ",uz:"zero bu joy"},{ar:"لَيْسَ مُجَرَّدَ بَحْرٍ",uz:"shunchaki dengiz emas"}],full_uz:"Chunki bu joy shunchaki dengiz emas.",note:null},
{num:67,time:"00:05:50,599 --> 00:05:54,039",arabic:"بَلْ آيَةٌ حَيَّةٌ مِنْ آيَاتِ الْخَالِقِ",segs:[{ar:"بَلْ آيَةٌ حَيَّةٌ",uz:"balki tirik bir oyat"},{ar:"مِنْ آيَاتِ الْخَالِقِ",uz:"Yaratuvchining oyatlaridan"}],full_uz:"Balki Yaratuvchining tirik oyatlaridan biridir.",note:null},
{num:68,time:"00:05:54,040 --> 00:05:58,020",arabic:"لَوْحَةٌ تَتَنَفَّسُ تَسْبِيحًا وَجَمَالًا",segs:[{ar:"لَوْحَةٌ تَتَنَفَّسُ",uz:"nafas olayotgan manzara"},{ar:"تَسْبِيحًا وَجَمَالًا",uz:"tasbeh va go‘zallik bilan"}],full_uz:"Tasbeh va go‘zallik bilan nafas olayotgan manzara.",note:"تَسْبِيحٌ — tasbeh aytish, Allohni poklash."},
{num:69,time:"00:05:58,020 --> 00:06:03,860",arabic:"نَنْتَقِلُ إِلَى قَلْبِ كَنَدَا",segs:[{ar:"نَنْتَقِلُ",uz:"ko‘chamiz"},{ar:"إِلَى قَلْبِ كَنَدَا",uz:"Kanadaning yuragiga"}],full_uz:"Kanadaning yuragiga ko‘chamiz.",note:null},
{num:70,time:"00:06:03,860 --> 00:06:07,160",arabic:"نَصِلُ إِلَى لَوْحَةٍ مِنْ صُنْعِ الرَّحْمَنِ",segs:[{ar:"نَصِلُ",uz:"yetib boramiz"},{ar:"إِلَى لَوْحَةٍ",uz:"bir manzaraga"},{ar:"مِنْ صُنْعِ الرَّحْمَنِ",uz:"Rahmonning yaratishi"}],full_uz:"Rahmon yaratgan bir manzaraga yetib boramiz.",note:"صُنْعٌ — yaratish, mahorat bilan ishlash."},
{num:71,time:"00:06:07,160 --> 00:06:09,780",arabic:"إِلَى مُنْتَزَهِ بَانْفِ الْوَطَنِيِّ",segs:null,full_uz:"Banff milliy bog‘iga.",note:null},
{num:72,time:"00:06:09,780 --> 00:06:13,140",arabic:"حَيْثُ تَتَلَاقَى الْغَابَاتُ الْخَضْرَاءُ",segs:null,full_uz:"U yerda yashil o‘rmonlar tutashadi.",note:null},
{num:73,time:"00:06:13,140 --> 00:06:15,220",arabic:"وَالْبُحَيْرَاتُ الزَّرْقَاءُ",segs:null,full_uz:"Va moviy ko‘llar.",note:null},
{num:74,time:"00:06:15,220 --> 00:06:18,220",arabic:"وَالْقِمَمُ الْمُغَطَّاةُ بِالثُّلُوجِ",segs:null,full_uz:"Qor bilan qoplangan cho‘qqilar.",note:null},
{num:75,time:"00:06:18,220 --> 00:06:22,640",arabic:"فِي مَشْهَدٍ يُذَكِّرُكَ بِجَلَالِ الْخَلْقِ وَعَظَمَتِهِ",segs:[{ar:"فِي مَشْهَدٍ",uz:"bir manzarada"},{ar:"يُذَكِّرُكَ",uz:"sizga eslatadigan"},{ar:"بِجَلَالِ الْخَلْقِ وَعَظَمَتِهِ",uz:"yaratilishning ulug‘ligi va buyukligini"}],full_uz:"Yaratilishning ulug‘ligi va buyukligini eslatadigan bir manzarada.",note:"جَلَالٌ — ulug‘vorlik, shukuh."},
{num:76,time:"00:06:22,639 --> 00:06:34,699",arabic:"أُسِّسَ بَانْفُ عَامَ 1885 لِيَكُونَ أَوَّلَ حَدِيقَةٍ وَطَنِيَّةٍ فِي كَنَدَا",segs:[{ar:"أُسِّسَ بَانْفُ عَامَ 1885",uz:"Banff 1885-yilda tashkil etilgan"},{ar:"لِيَكُونَ أَوَّلَ حَدِيقَةٍ وَطَنِيَّةٍ",uz:"birinchi milliy bog‘ bo‘lishi uchun"},{ar:"فِي كَنَدَا",uz:"Kanadada"}],full_uz:"Banff 1885-yilda Kanadadagi birinchi milliy bog‘ bo‘lishi uchun tashkil etilgan.",note:"أُسِّسَ — tashkil etildi."},
{num:77,time:"00:06:34,699 --> 00:06:39,199",arabic:"وَجَنَّةٌ لِكُلِّ مَنْ يَطْلُبُ السُّكُونَ بَيْنَ هَمْسِ الطَّبِيعَةِ",segs:[{ar:"وَجَنَّةٌ",uz:"va jannatdir"},{ar:"لِكُلِّ مَنْ يَطْلُبُ السُّكُونَ",uz:"sokinlik izlagan har bir kishi uchun"},{ar:"بَيْنَ هَمْسِ الطَّبِيعَةِ",uz:"tabiat shivirlari orasida"}],full_uz:"Tabiat shivirlari orasida sokinlik izlagan har bir kishi uchun jannatdir.",note:"هَمْسٌ — shivir, pichirlash."},
{num:78,time:"00:06:44,199 --> 00:06:51,500",arabic:"جَوْهَرَةُ الْمَكَانِ هِيَ بُحَيْرَةُ لُوِيزْ بِمِيَاهِهَا الْفِيرُوزِيَّةِ الَّتِي تَكَادُ لَا تُصَدَّقُ",segs:[{ar:"جَوْهَرَةُ الْمَكَانِ",uz:"joyning durdonasi"},{ar:"هِيَ بُحَيْرَةُ لُوِيزْ",uz:"Luiz ko‘lidir"},{ar:"بِمِيَاهِهَا الْفِيرُوزِيَّةِ",uz:"uning feruza rangli suvlari bilan"},{ar:"الَّتِي تَكَادُ لَا تُصَدَّقُ",uz:"hatto ishonib bo‘lmaydigan"}],full_uz:"Joyning durdonasi — suvlari deyarli ishonib bo‘lmaydigan feruza rangdagi Luiz ko‘lidir.",note:"جَوْهَرَةٌ — dur, gavhar, bebaho narsa."},
{num:79,time:"00:06:51,500 --> 00:06:56,939",arabic:"تُحِيطُ بِهَا أَنْهَارٌ جَلِيدِيَّةٌ تَعْكِسُ صُورَتَهَا فِي صَمْتٍ عَجِيبٍ",segs:[{ar:"تُحِيطُ بِهَا أَنْهَارٌ جَلِيدِيَّةٌ",uz:"uni muzliklar o‘rab turadi"},{ar:"تَعْكِسُ صُورَتَهَا",uz:"uning aksini aks ettiradi"},{ar:"فِي صَمْتٍ عَجِيبٍ",uz:"ajoyib sukunatda"}],full_uz:"Uni ajoyib sukunatda o‘z aksini aks ettiruvchi muzliklar o‘rab turadi.",note:"أَنْهَارٌ جَلِيدِيَّةٌ — muzliklar."},
{num:80,time:"00:06:56,939 --> 00:07:06,300",arabic:"أَيْنَمَا نَظَرْتَ تَرَى الْمَشْهَدَ أَكْبَرَ مِنَ الْحَيَاةِ نَفْسِهَا",segs:[{ar:"أَيْنَمَا نَظَرْتَ",uz:"qayerga qarasangiz ham"},{ar:"تَرَى الْمَشْهَدَ",uz:"manzarani ko‘rasiz"},{ar:"أَكْبَرَ مِنَ الْحَيَاةِ نَفْسِهَا",uz:"hayotning o‘zidan ham ulkan"}],full_uz:"Qayerga qarasangiz ham hayotning o‘zidan ham ulkan manzarani ko‘rasiz.",note:null},
{num:81,time:"00:07:06,300 --> 00:07:09,980",arabic:"قَدْ تَلْمَحُ أَيْلًا يَرْعَى عَلَى حَافَّةِ الطَّرِيقِ",segs:[{ar:"قَدْ تَلْمَحُ أَيْلًا",uz:"bug‘uni ko‘rib qolishingiz mumkin"},{ar:"يَرْعَى",uz:"o‘tlayotgan"},{ar:"عَلَى حَافَّةِ الطَّرِيقِ",uz:"yo‘l chetida"}],full_uz:"Yo‘l chetida o‘tlab yurgan bug‘uni ko‘rib qolishingiz mumkin.",note:"أَيْلٌ — bug‘u."},
{num:82,time:"00:07:09,980 --> 00:07:14,779",arabic:"أَوْ دُبًّا رَمَادِيًّا يَعْبُرُ الْغَابَةَ بِهُدُوءٍ مَهِيبٍ",segs:[{ar:"أَوْ دُبًّا رَمَادِيًّا",uz:"yoki kulrang ayiqni"},{ar:"يَعْبُرُ الْغَابَةَ",uz:"o‘rmondan o‘tayotgan"},{ar:"بِهُدُوءٍ مَهِيبٍ",uz:"salobatli sokinlik bilan"}],full_uz:"Yoki o‘rmondan salobatli sokinlik bilan o‘tayotgan kulrang ayiqni.",note:"مَهِيبٌ — salobatli, haybatli."},
{num:83,time:"00:07:14,779 --> 00:07:17,420",arabic:"لَا يَكْتُبُهَا سِوَى الْخَالِقِ",segs:[{ar:"لَا يَكْتُبُهَا",uz:"uni yozmaydi"},{ar:"سِوَى الْخَالِقِ",uz:"Yaratuvchidan boshqa hech kim"}],full_uz:"Buni Yaratuvchidan boshqa hech kim yozmaydi.",note:"سِوَى — ...dan boshqa."},
{num:84,time:"00:07:21,500 --> 00:07:26,160",arabic:"وَفِي الشِّتَاءِ تَتَحَوَّلُ بَانْفُ إِلَى عَالَمٍ أَبْيَضَ مِنَ السُّكُونِ",segs:[{ar:"وَفِي الشِّتَاءِ",uz:"qishda"},{ar:"تَتَحَوَّلُ بَانْفُ",uz:"Banff aylanadi"},{ar:"إِلَى عَالَمٍ أَبْيَضَ مِنَ السُّكُونِ",uz:"sukunatdan oppoq bir olamga"}],full_uz:"Qishda Banff sukunatga burkangan oppoq olamga aylanadi.",note:null},
{num:85,time:"00:07:26,160 --> 00:07:30,060",arabic:"تَغْفُو فِيهِ الْأَرْضُ تَحْتَ بَطَّانِيَةٍ مِنَ الثَّلْجِ",segs:[{ar:"تَغْفُو فِيهِ الْأَرْضُ",uz:"unda yer mudraydi"},{ar:"تَحْتَ بَطَّانِيَةٍ مِنَ الثَّلْجِ",uz:"qor ko‘rpa ostida"}],full_uz:"Unda yer qor ko‘rpa ostida mudraydi.",note:"تَغْفُو — mudramoq, uyquga ketmoq."},
{num:86,time:"00:07:30,060 --> 00:07:33,339",arabic:"فِي حِكَايَةٍ لَا يَكْتُبُهَا سِوَى الْخَالِقِ",segs:[{ar:"فِي حِكَايَةٍ",uz:"bir hikoyada"},{ar:"لَا يَكْتُبُهَا سِوَى الْخَالِقِ",uz:"uni faqat Yaratuvchi yozadigan"}],full_uz:"Uni faqat Yaratuvchi yozadigan bir hikoyada.",note:null},
{num:87,time:"00:07:33,339 --> 00:07:45,319",arabic:"نُبْحِرُ شَمَالًا إِلَى السَّوَاحِلِ الْغَامِضَةِ فِي نُورْمَانْدِي، فَرَنْسَا",segs:[{ar:"نُبْحِرُ شَمَالًا",uz:"shimolga suzamiz"},{ar:"إِلَى السَّوَاحِلِ الْغَامِضَةِ",uz:"sirli qirg‘oqlarga"},{ar:"فِي نُورْمَانْدِي، فَرَنْسَا",uz:"Fransiyaning Normandiya hududiga"}],full_uz:"Shimolga, Fransiyaning Normandiyadagi sirli qirg‘oqlariga suzamiz.",note:"نُبْحِرُ — dengizda suzmoq, yo‘l olmoq."},
{num:88,time:"00:07:45,319 --> 00:07:50,839",arabic:"حَيْثُ يَنْهَضُ مِنْ قَلْبِ الْبَحْرِ مَشْهَدٌ كَأَنَّهُ خَرَجَ مِنْ حُلْمٍ عَتِيقٍ",segs:[{ar:"حَيْثُ يَنْهَضُ مِنْ قَلْبِ الْبَحْرِ",uz:"u yerda dengiz bag‘ridan ko‘tariladi"},{ar:"مَشْهَدٌ",uz:"bir manzara"},{ar:"كَأَنَّهُ خَرَجَ مِنْ حُلْمٍ عَتِيقٍ",uz:"go‘yo qadimiy tushdan chiqqandek"}],full_uz:"U yerda go‘yo qadimiy tushdan chiqqandek bir manzara dengiz bag‘ridan ko‘tariladi.",note:"عَتِيقٌ — qadimiy, eski."},
{num:89,time:"00:07:50,839 --> 00:07:58,939",arabic:"مِنْ بَعِيدٍ",segs:null,full_uz:"Uzoqdan.",note:null},
{num:90,time:"00:07:58,939 --> 00:08:02,739",arabic:"تَبْدُو الْجَزِيرَةُ كَقَصِيدَةٍ مِنْ ضَبَابٍ وَنُورٍ",segs:[{ar:"تَبْدُو الْجَزِيرَةُ",uz:"orol ko‘rinadi"},{ar:"كَقَصِيدَةٍ",uz:"she’r kabi"},{ar:"مِنْ ضَبَابٍ وَنُورٍ",uz:"tuman va nurdan"}],full_uz:"Orol tuman va nurdan yaralgan she’r kabi ko‘rinadi.",note:null},
{num:91,time:"00:08:02,739 --> 00:08:07,779",arabic:"تَعْلُوهَا دَيْرٌ مَهِيبٌ بُنِيَ مُنْذُ أَكْثَرَ مِنْ أَلْفِ عَامٍ",segs:[{ar:"تَعْلُوهَا دَيْرٌ مَهِيبٌ",uz:"uning ustida haybatli monastir bor"},{ar:"بُنِيَ مُنْذُ أَكْثَرَ مِنْ أَلْفِ عَامٍ",uz:"ming yildan ortiq vaqt oldin qurilgan"}],full_uz:"Uning ustida ming yildan ortiq vaqt oldin qurilgan haybatli monastir turadi.",note:"دَيْرٌ — monastir."},
{num:92,time:"00:08:07,779 --> 00:08:11,159",arabic:"يَقِفُ شَامِخًا بَيْنَ الْمَدِّ وَالْجَزْرِ",segs:[{ar:"يَقِفُ شَامِخًا",uz:"mag‘rur turadi"},{ar:"بَيْنَ الْمَدِّ وَالْجَزْرِ",uz:"to‘lqin ko‘tarilishi va qaytishi orasida"}],full_uz:"U suvning ko‘tarilishi va qaytishi orasida mag‘rur turadi.",note:"شَامِخٌ — baland, mag‘rur, salobatli."},
{num:93,time:"00:08:11,159 --> 00:08:14,339",arabic:"يَظْهَرُ وَيَخْتَفِي عَلَى إِيقَاعِ الْبَحْرِ",segs:[{ar:"يَظْهَرُ وَيَخْتَفِي",uz:"ko‘rinib, yo‘qoladi"},{ar:"عَلَى إِيقَاعِ الْبَحْرِ",uz:"dengiz ritmiga mos ravishda"}],full_uz:"Dengiz ritmiga mos ravishda ko‘rinib, yo‘qoladi.",note:"إِيقَاعٌ — ritm, ohang."},
{num:94,time:"00:08:14,339 --> 00:08:19,279",arabic:"كَأَنَّ الْمَوْجَ يَسْجُدُ مِنْ حَوْلِهِ تَعْظِيمًا لِرَبِّ الْبَحْرِ وَالْبَرِّ",segs:[{ar:"كَأَنَّ الْمَوْجَ يَسْجُدُ مِنْ حَوْلِهِ",uz:"go‘yo to‘lqinlar uning atrofida sajda qilayotgandek"},{ar:"تَعْظِيمًا لِرَبِّ الْبَحْرِ وَالْبَرِّ",uz:"dengiz va quruqlik Robbisini ulug‘lab"}],full_uz:"Go‘yo to‘lqinlar dengiz va quruqlik Robbisini ulug‘lab uning atrofida sajda qilayotgandek.",note:"تَعْظِيمًا — ulug‘lash uchun."},
{num:95,time:"00:08:19,279 --> 00:08:31,959",arabic:"تَتَعَرَّجُ شَوَارِعُهَا الْحَجَرِيَّةُ الضَّيِّقَةُ بَيْنَ أَبْرَاجٍ وَجُدْرَانٍ تَحْمِلُ أَثَرَ الزَّمَنِ",segs:[{ar:"تَتَعَرَّجُ شَوَارِعُهَا الْحَجَرِيَّةُ الضَّيِّقَةُ",uz:"uning tor tosh ko‘chalari egri-bugri cho‘ziladi"},{ar:"بَيْنَ أَبْرَاجٍ وَجُدْرَانٍ",uz:"minoral ar va devorlar orasidan"},{ar:"تَحْمِلُ أَثَرَ الزَّمَنِ",uz:"zamon izlarini ko‘tarib"}],full_uz:"Uning tor tosh ko‘chalari zamon izlarini saqlagan minoralar va devorlar orasidan egri-bugri cho‘ziladi.",note:"تَتَعَرَّجُ — egri-bugri bo‘lib cho‘zilmoq."},
{num:96,time:"00:08:31,959 --> 00:08:36,639",arabic:"وَفِي صَمْتِهَا يَسْمَعُ الْقَلْبُ صَدَى الْعِبَادَةِ",segs:[{ar:"وَفِي صَمْتِهَا",uz:"uning sukunatida"},{ar:"يَسْمَعُ الْقَلْبُ",uz:"qalb eshitadi"},{ar:"صَدَى الْعِبَادَةِ",uz:"ibodat aks-sadosini"}],full_uz:"Uning sukunatida qalb ibodat aks-sadosini eshitadi.",note:"صَدًى — aks-sado."},
{num:97,time:"00:08:36,639 --> 00:08:42,019",arabic:"كَأَنَّ الْمَكَانَ مَا زَالَ يَتَنَفَّسُ تَسْبِيحًا مِنَ الْقُرُونِ الْمَاضِيَةِ",segs:[{ar:"كَأَنَّ الْمَكَانَ",uz:"go‘yo bu joy"},{ar:"مَا زَالَ يَتَنَفَّسُ تَسْبِيحًا",uz:"hamon tasbeh bilan nafas olayotgandek"},{ar:"مِنَ الْقُرُونِ الْمَاضِيَةِ",uz:"o‘tgan asrlardan"}],full_uz:"Go‘yo bu joy o‘tgan asrlardan qolgan tasbeh bilan hamon nafas olayotgandek.",note:null},
{num:98,time:"00:08:49,279 --> 00:08:54,819",arabic:"يَقُولُونَ إِنَّ الْمَلَكَ مِيكَائِيلَ أَمَرَ بِبِنَاءِ هَذَا الْمَعْبَدِ فَوْقَ الصَّخْرَةِ",segs:[{ar:"يَقُولُونَ",uz:"aytishlaricha"},{ar:"إِنَّ الْمَلَكَ مِيكَائِيلَ",uz:"farishta Mikoil"},{ar:"أَمَرَ بِبِنَاءِ هَذَا الْمَعْبَدِ",uz:"bu ma’badni qurishni buyurgan"},{ar:"فَوْقَ الصَّخْرَةِ",uz:"qoya ustiga"}],full_uz:"Aytishlaricha, farishta Mikoil bu ma’badni qoya ustiga qurishni buyurgan.",note:"مَعْبَدٌ — ibodatxona, ma’bad."},
{num:99,time:"00:08:54,819 --> 00:09:01,839",arabic:"لَكِنَّ الْحَقِيقَةَ الْأَعْمَقَ أَنَّ الْإِلَهَ إِذَا أَرَادَ لِمَكَانٍ أَنْ يَكُونَ رَمْزًا لِلنُّورِ",segs:[{ar:"لَكِنَّ الْحَقِيقَةَ الْأَعْمَقَ",uz:"ammo chuqurroq haqiqat shuki"},{ar:"أَنَّ الْإِلَهَ",uz:"Iloh"},{ar:"إِذَا أَرَادَ لِمَكَانٍ",uz:"bir joyni xohlasa"},{ar:"أَنْ يَكُونَ رَمْزًا لِلنُّورِ",uz:"nur ramzi bo‘lishini"}],full_uz:"Ammo chuqurroq haqiqat shuki, Iloh bir joyning nur ramzi bo‘lishini xohlasa.",note:"رَمْزٌ — ramz."},
{num:100,time:"00:09:01,839 --> 00:09:06,939",arabic:"جَعَلَ الْقُلُوبَ تَهْتَدِي إِلَيْهِ رَغْمَ عَوَاصِفِ الْبَحْرِ وَالزَّمَانِ",segs:[{ar:"جَعَلَ الْقُلُوبَ تَهْتَدِي إِلَيْهِ",uz:"qalblarni unga hidoyat topadigan qildi"},{ar:"رَغْمَ عَوَاصِفِ الْبَحْرِ وَالزَّمَانِ",uz:"dengiz va zamon bo‘ronlariga qaramay"}],full_uz:"Dengiz va zamon bo‘ronlariga qaramay, qalblarni unga hidoyat topadigan qiladi.",note:"تَهْتَدِي — to‘g‘ri yo‘l topmoq, hidoyat topmoq."},
{num:101,time:"00:09:06,939 --> 00:09:13,319",arabic:"هُنَا بَيْنَ لَمَعَانِ الْبَحْرِ وَصَفَاءِ السَّمَاءِ",segs:null,full_uz:"Bu yerda, dengiz jilosi va osmon musaffoligi orasida.",note:null},
{num:102,time:"00:09:13,319 --> 00:09:18,459",arabic:"تَشْعُرُ أَنَّكَ تَسِيرُ فِي قِصَّةٍ مَا زَالَتْ تُكْتَبُ مُنْذُ أَلْفِ عَامٍ",segs:[{ar:"تَشْعُرُ أَنَّكَ تَسِيرُ",uz:"o‘zingiz yurayotganingizni his qilasiz"},{ar:"فِي قِصَّةٍ",uz:"bir hikoya ichida"},{ar:"مَا زَالَتْ تُكْتَبُ مُنْذُ أَلْفِ عَامٍ",uz:"ming yildan beri yozilayotgan"}],full_uz:"O‘zingiz ming yildan beri yozilayotgan bir hikoya ichida yurayotganingizni his qilasiz.",note:null},
{num:103,time:"00:09:18,460 --> 00:09:22,820",arabic:"قِصَّةٌ تُحَدِّثُكَ عَنِ الثَّبَاتِ وَالْإِيمَانِ",segs:[{ar:"قِصَّةٌ تُحَدِّثُكَ",uz:"sizga so‘zlaydigan hikoya"},{ar:"عَنِ الثَّبَاتِ وَالْإِيمَانِ",uz:"sobitlik va iymon haqida"}],full_uz:"Sobitlik va iymon haqida so‘zlaydigan hikoya.",note:"الثَّبَاتُ — sobitlik, qat’iyat."},
{num:104,time:"00:09:22,820 --> 00:09:26,720",arabic:"وَعَنْ جَمَالٍ لَا يَزُولُ لِأَنَّهُ مِنْ صُنْعِ اللَّهِ",segs:[{ar:"وَعَنْ جَمَالٍ لَا يَزُولُ",uz:"va yo‘qolmaydigan go‘zallik haqida"},{ar:"لِأَنَّهُ مِنْ صُنْعِ اللَّهِ",uz:"chunki u Allohning yaratishidandir"}],full_uz:"Va yo‘qolmaydigan go‘zallik haqida, chunki u Allohning yaratishidandir.",note:"يَزُولُ — yo‘qolmoq, barham topmoq."},
{num:105,time:"00:09:26,720 --> 00:09:33,379",arabic:"مِنْ شَمَالِ إِيرْلَنْدَا",segs:null,full_uz:"Shimoliy Irlandiyadan.",note:null},
{num:106,time:"00:09:33,379 --> 00:09:38,879",arabic:"حَيْثُ تُخْفِي السَّوَاحِلُ الْوَعْرَةُ سِرًّا مِنْ أَسْرَارِ الْجَمَالِ الْإِلَهِيِّ",segs:[{ar:"حَيْثُ تُخْفِي السَّوَاحِلُ الْوَعْرَةُ",uz:"u yerda qoyali qirg‘oqlar yashiradi"},{ar:"سِرًّا مِنْ أَسْرَارِ الْجَمَالِ الْإِلَهِيِّ",uz:"ilohiy go‘zallik sirlaridan birini"}],full_uz:"U yerda qoyali qirg‘oqlar ilohiy go‘zallik sirlaridan birini yashiradi.",note:"وَعْرٌ — qo‘pol, qoyali, notekis."},
{num:107,time:"00:09:38,879 --> 00:09:41,000",arabic:"طَرِيقُ الْعِمَالَقَةِ",segs:null,full_uz:"Gigantlar yo‘li.",note:"طَرِيقُ الْعِمَالَقَةِ — Giant’s Causeway."},
{num:108,time:"00:09:41,000 --> 00:09:43,379",arabic:"جَايَنْتْسْ كُوزْوَيْ",segs:null,full_uz:"Giants Causeway.",note:null},
{num:109,time:"00:09:43,379 --> 00:09:52,720",arabic:"أَكْثَرُ مِنْ أَرْبَعِينَ أَلْفَ عَمُودٍ مِنَ الْبَازَلْتِ تَتَشَابَكُ كَقِطَعِ فُسَيْفِسَاءَ عِمْلَاقَةٍ",segs:[{ar:"أَكْثَرُ مِنْ أَرْبَعِينَ أَلْفَ عَمُودٍ",uz:"qirq mingdan ortiq ustun"},{ar:"مِنَ الْبَازَلْتِ",uz:"bazaltdan"},{ar:"تَتَشَابَكُ",uz:"bir-biriga tutashadi"},{ar:"كَقِطَعِ فُسَيْفِسَاءَ عِمْلَاقَةٍ",uz:"ulkan mozaika bo‘laklaridek"}],full_uz:"Qirq mingdan ortiq bazalt ustunlari ulkan mozaika bo‘laklaridek bir-biriga tutashadi.",note:"فُسَيْفِسَاءُ — mozaika. الْبَازَلْتُ — bazalt."},
{num:110,time:"00:09:52,720 --> 00:09:58,240",arabic:"تَكَوَّنَتْ مُنْذُ مَلَايِينِ السِّنِينَ حِينَ بَرُدَتِ الْحُمَمُ الْبُرْكَانِيَّةُ",segs:[{ar:"تَكَوَّنَتْ مُنْذُ مَلَايِينِ السِّنِينَ",uz:"millionlab yillar oldin hosil bo‘lgan"},{ar:"حِينَ بَرُدَتِ الْحُمَمُ الْبُرْكَانِيَّةُ",uz:"vulqon lavası soviganda"}],full_uz:"Ular millionlab yillar oldin vulqon lavası soviganda hosil bo‘lgan.",note:"حُمَمٌ بُرْكَانِيَّةٌ — vulqon lavası."},
{num:111,time:"00:09:58,240 --> 00:10:04,360",arabic:"فَانْقَسَمَتْ بِانْتِظَامٍ مُذْهِلٍ تَشْهَدُ عَلَى دِقَّةِ الْخَلْقِ وَإِعْجَازِهِ",segs:[{ar:"فَانْقَسَمَتْ بِانْتِظَامٍ مُذْهِلٍ",uz:"shunda ular hayratlanarli tartibda bo‘lingan"},{ar:"تَشْهَدُ عَلَى دِقَّةِ الْخَلْقِ",uz:"yaratilishdagi aniqlikka guvohlik berib"},{ar:"وَإِعْجَازِهِ",uz:"va uning mo‘jizaviyligiga"}],full_uz:"Shunda ular hayratlanarli tartibda bo‘linib, yaratilishdagi aniqlik va uning mo‘jizaviyligiga guvohlik beradi.",note:"إِعْجَازٌ — mo‘jizaviylik, ojiz qoldiruvchi mukammallik."},
{num:112,time:"00:10:04,360 --> 00:10:10,279",arabic:"وَمَعَ كُلِّ مَوْجَةٍ تَضْرِبُ الشَّاطِئَ",segs:[{ar:"وَمَعَ كُلِّ مَوْجَةٍ",uz:"har bir to‘lqin bilan"},{ar:"تَضْرِبُ الشَّاطِئَ",uz:"qirg‘oqqa uriladigan"}],full_uz:"Qirg‘oqqa uriladigan har bir to‘lqin bilan.",note:null},
{num:113,time:"00:10:10,279 --> 00:10:14,139",arabic:"وَكُلُّ نَسْمَةٍ مَالِحَةٍ تُلَامِسُ وَجْهَكَ",segs:[{ar:"وَكُلُّ نَسْمَةٍ مَالِحَةٍ",uz:"va har bir sho‘r shabada"},{ar:"تُلَامِسُ وَجْهَكَ",uz:"yuzingizga tegadi"}],full_uz:"Va yuzingizga tegadigan har bir sho‘r shabada.",note:"نَسْمَةٌ — shabada, mayin shamol."},
{num:114,time:"00:10:14,139 --> 00:10:18,659",arabic:"تَشْعُرُ أَنَّ الْأَرْضَ تَرْوِي حِكَايَةَ قُدْرَةٍ لَا تُقَاسُ",segs:[{ar:"تَشْعُرُ أَنَّ الْأَرْضَ",uz:"yer ... ekanini his qilasiz"},{ar:"تَرْوِي حِكَايَةَ قُدْرَةٍ",uz:"qudrat haqidagi hikoyani so‘zlaydi"},{ar:"لَا تُقَاسُ",uz:"o‘lchab bo‘lmaydigan"}],full_uz:"Yer o‘lchab bo‘lmaydigan qudrat haqida hikoya so‘zlayotganini his qilasiz.",note:"تُقَاسُ — o‘lchanmoq."},
{num:115,time:"00:10:18,659 --> 00:10:22,940",arabic:"حِكَايَةُ رَبٍّ إِذَا أَرَادَ شَيْئًا قَالَ لَهُ",segs:[{ar:"حِكَايَةُ رَبٍّ",uz:"bir Robb haqidagi hikoya"},{ar:"إِذَا أَرَادَ شَيْئًا",uz:"U biror narsani xohlasa"},{ar:"قَالَ لَهُ",uz:"unga aytadi"}],full_uz:"Biror narsani xohlasa, unga aytadigan Robb haqidagi hikoya.",note:null},
{num:116,time:"00:10:22,940 --> 00:10:25,220",arabic:"كُنْ فَيَكُونُ",segs:null,full_uz:"“Bo‘l!” — bas, u bo‘ladi.",note:null},
{num:117,time:"00:10:25,220 --> 00:10:34,120",arabic:"سَوَاءٌ آمَنْتَ بِرِوَايَاتِ الْأَسَاطِيرِ أَوْ حَقَائِقِ الْعِلْمِ",segs:[{ar:"سَوَاءٌ آمَنْتَ بِرِوَايَاتِ الْأَسَاطِيرِ",uz:"afsonalar haqidagi rivoyatlarga ishonsangiz ham"},{ar:"أَوْ حَقَائِقِ الْعِلْمِ",uz:"yoki ilm haqiqatlariga"}],full_uz:"Afsonalar haqidagi rivoyatlarga ishonsangiz ham, ilm haqiqatlariga ishonsangiz ham.",note:"سَوَاءٌ — baribir, farqi yo‘q."},
{num:118,time:"00:10:34,120 --> 00:10:40,060",arabic:"يَبْقَى طَرِيقُ الْعِمَالَقَةِ شَاهِدًا عَلَى لِقَاءِ الْعِلْمِ بِالْعَجَبِ",segs:[{ar:"يَبْقَى طَرِيقُ الْعِمَالَقَةِ",uz:"Gigantlar yo‘li qoladi"},{ar:"شَاهِدًا عَلَى لِقَاءِ الْعِلْمِ بِالْعَجَبِ",uz:"ilmning hayrat bilan uchrashuviga guvoh sifatida"}],full_uz:"Gigantlar yo‘li ilmning hayrat bilan uchrashuviga guvoh bo‘lib qoladi.",note:"الْعَجَبُ — hayrat, ajablanish."},
{num:119,time:"00:10:40,060 --> 00:10:43,360",arabic:"حَيْثُ تَمْتَزِجُ الْحِكَايَةُ بِالْحَقِيقَةِ",segs:null,full_uz:"Bu yerda hikoya haqiqat bilan qorishadi.",note:"تَمْتَزِجُ — qorishmoq, aralashmoq."},
{num:120,time:"00:10:43,360 --> 00:10:50,720",arabic:"وَتَشْعُرُ أَنَّكَ تَخْطُو فِي عَالَمٍ آخَرَ صَنَعَتْهُ يَدُ الْخَالِقِ بِدِقَّةٍ وَجَلَالٍ",segs:[{ar:"وَتَشْعُرُ أَنَّكَ تَخْطُو",uz:"va o‘zingiz qadam tashlayotganingizni his qilasiz"},{ar:"فِي عَالَمٍ آخَرَ",uz:"boshqa bir olamda"},{ar:"صَنَعَتْهُ يَدُ الْخَالِقِ",uz:"uni Yaratuvchining qo‘li yaratgan"},{ar:"بِدِقَّةٍ وَجَلَالٍ",uz:"aniqlik va ulug‘vorlik bilan"}],full_uz:"O‘zingiz Yaratuvchining qo‘li aniqlik va ulug‘vorlik bilan yaratgan boshqa bir olamda qadam tashlayotgandek his qilasiz.",note:"جَلَالٌ — ulug‘vorlik, salobat."},
{num:121,time:"00:10:59,560 --> 00:11:03,159",arabic:"وَمِنَ الشَّرْقِ الْبَعِيدِ إِلَى الْغَرْبِ الْأَمْرِيكِيِّ",segs:[{ar:"وَمِنَ الشَّرْقِ الْبَعِيدِ",uz:"uzoq sharqdan"},{ar:"إِلَى الْغَرْبِ الْأَمْرِيكِيِّ",uz:"Amerika g‘arbiga"}],full_uz:"Uzoq sharqdan Amerika g‘arbiga.",note:null},
{num:122,time:"00:11:03,159 --> 00:11:06,219",arabic:"نَصِلُ إِلَى الْقَلْبِ الْبَرِّيِّ لِلْأَرْضِ",segs:[{ar:"نَصِلُ",uz:"yetib boramiz"},{ar:"إِلَى الْقَلْبِ الْبَرِّيِّ لِلْأَرْضِ",uz:"yerning yovvoyi yuragiga"}],full_uz:"Yerning yovvoyi yuragiga yetib boramiz.",note:"بَرِّيٌّ — yovvoyi, tabiiy."},
{num:123,time:"00:11:06,219 --> 00:11:09,019",arabic:"إِلَى مُنْتَزَهِ يَلُوسْتُونَ الْوَطَنِيِّ",segs:null,full_uz:"Yellowstone milliy bog‘iga.",note:null},
{num:124,time:"00:11:09,019 --> 00:11:11,419",arabic:"يَلُوسْتُونْ نَاشِنَالْ بَارْكْ",segs:null,full_uz:"Yellowstone National Park.",note:null},
{num:125,time:"00:11:11,419 --> 00:11:14,419",arabic:"أَوَّلُ مَحْمِيَّةٍ طَبِيعِيَّةٍ فِي الْعَالَمِ",segs:null,full_uz:"Dunyodagi birinchi tabiiy qo‘riqxona.",note:"مَحْمِيَّةٌ طَبِيعِيَّةٌ — tabiiy qo‘riqxona."},
{num:126,time:"00:11:14,419 --> 00:11:18,819",arabic:"وَأَحَدُ أَعْجَبِ مَشَاهِدِ قُدْرَةِ اللَّهِ عَلَى جَمْعِ الْأَضْدَادِ",segs:[{ar:"وَأَحَدُ أَعْجَبِ مَشَاهِدِ قُدْرَةِ اللَّهِ",uz:"Alloh qudratining eng hayratlanarli manzaralaridan biri"},{ar:"عَلَى جَمْعِ الْأَضْدَادِ",uz:"qarama-qarshiliklarni jamlashda"}],full_uz:"Alloh qudratining qarama-qarshiliklarni jamlashdagi eng hayratlanarli manzaralaridan biridir.",note:"الْأَضْدَادُ — qarama-qarshiliklar."},
{num:127,time:"00:11:18,819 --> 00:11:20,480",arabic:"النَّارُ وَالْمَاءُ",segs:null,full_uz:"Olov va suv.",note:null},
{num:128,time:"00:11:20,480 --> 00:11:22,019",arabic:"الصَّخْرُ وَاللَّوْنُ",segs:null,full_uz:"Qoya va rang.",note:null},
{num:129,time:"00:11:22,019 --> 00:11:23,799",arabic:"السُّكُونُ وَالْهَيَجَانُ",segs:null,full_uz:"Sukunat va jo‘shqinlik.",note:null},
{num:130,time:"00:11:23,799 --> 00:11:30,039",arabic:"هُنَا الْأَرْضُ تَتَنَفَّسُ",segs:null,full_uz:"Bu yerda yer nafas oladi.",note:null},
{num:131,time:"00:11:30,039 --> 00:11:35,339",arabic:"وَالْيَنَابِيعُ الْحَارَّةُ تَنْفَجِرُ إِلَى السَّمَاءِ بِأَلْوَانٍ لَا تُصَدَّقُ",segs:[{ar:"وَالْيَنَابِيعُ الْحَارَّةُ",uz:"va issiq buloqlar"},{ar:"تَنْفَجِرُ إِلَى السَّمَاءِ",uz:"osmonga otiladi"},{ar:"بِأَلْوَانٍ لَا تُصَدَّقُ",uz:"ishonib bo‘lmaydigan ranglarda"}],full_uz:"Issiq buloqlar ishonib bo‘lmaydigan ranglarda osmonga otiladi.",note:"تَنْفَجِرُ — otilmoq, portlab chiqmoq."},
{num:132,time:"00:11:35,339 --> 00:11:42,299",arabic:"الْأَزْرَقُ وَالْأَخْضَرُ وَالذَّهَبِيُّ يَنْسَابُونَ كَأَنَّهُمْ خُيُوطُ ضَوْءٍ مِنَ الْجَنَّةِ",segs:[{ar:"الْأَزْرَقُ وَالْأَخْضَرُ وَالذَّهَبِيُّ",uz:"ko‘k, yashil va oltin ranglar"},{ar:"يَنْسَابُونَ",uz:"oqib tushadi"},{ar:"كَأَنَّهُمْ خُيُوطُ ضَوْءٍ مِنَ الْجَنَّةِ",uz:"go‘yo jannatdan tushayotgan nur iplaridek"}],full_uz:"Ko‘k, yashil va oltin ranglar go‘yo jannatdan tushayotgan nur iplaridek oqadi.",note:"يَنْسَابُ — silliq oqmoq, sirg‘alib o‘tmoq."},
{num:133,time:"00:11:42,299 --> 00:11:49,659",arabic:"فِي قَلْبِ الْمُنْتَزَهِ تَتَلَأْلَأُ الْيَنْبُوعُ الْمَنْشُورِيُّ الْعَظِيمُ",segs:[{ar:"فِي قَلْبِ الْمُنْتَزَهِ",uz:"bog‘ning markazida"},{ar:"تَتَلَأْلَأُ",uz:"yaltirab turadi"},{ar:"الْيَنْبُوعُ الْمَنْشُورِيُّ الْعَظِيمُ",uz:"Buyuk Prizmatik buloq"}],full_uz:"Bog‘ning markazida Buyuk Prizmatik buloq yaltirab turadi.",note:"الْيَنْبُوعُ الْمَنْشُورِيُّ الْعَظِيمُ — Grand Prismatic Spring."},
{num:134,time:"00:11:49,659 --> 00:11:53,019",arabic:"جْرَانْدْ بْرِيزْمَاتِكْ سْبْرِينْجْ",segs:null,full_uz:"Grand Prismatic Spring.",note:null},
{num:135,time:"00:11:53,019 --> 00:11:58,199",arabic:"بِأَلْوَانِهَا الَّتِي تُذَكِّرُ بِأَنَّ الْجَمَالَ لَيْسَ زِينَةً",segs:[{ar:"بِأَلْوَانِهَا",uz:"uning ranglari bilan"},{ar:"الَّتِي تُذَكِّرُ بِأَنَّ الْجَمَالَ",uz:"go‘zallikni eslatadigan"},{ar:"لَيْسَ زِينَةً",uz:"bezak emasligini"}],full_uz:"Uning ranglari go‘zallik bezak emasligini eslatadi.",note:"زِينَةٌ — bezak, ziynat."},
{num:136,time:"00:11:58,200 --> 00:12:02,560",arabic:"بَلْ لُغَةٌ يَتَحَدَّثُ بِهَا الْخَالِقُ إِلَى الْقُلُوبِ",segs:[{ar:"بَلْ لُغَةٌ",uz:"balki bir tildir"},{ar:"يَتَحَدَّثُ بِهَا الْخَالِقُ",uz:"Yaratuvchi u bilan so‘zlaydi"},{ar:"إِلَى الْقُلُوبِ",uz:"qalblarga"}],full_uz:"Balki Yaratuvchi qalblarga u orqali so‘zlaydigan tildir.",note:null},
{num:137,time:"00:12:02,560 --> 00:12:09,360",arabic:"وَإِلَى جِوَارِهَا يَقِفُ النَّبْعُ الْعَتِيقُ",segs:[{ar:"وَإِلَى جِوَارِهَا",uz:"uning yonida"},{ar:"يَقِفُ النَّبْعُ الْعَتِيقُ",uz:"qadimiy buloq turadi"}],full_uz:"Uning yonida qadimiy buloq turadi.",note:"عَتِيقٌ — qadimiy, eski."},
{num:138,time:"00:12:09,360 --> 00:12:11,379",arabic:"أُولْدْ فِيثْفُلْ",segs:null,full_uz:"Old Faithful.",note:null},
{num:139,time:"00:12:11,379 --> 00:12:15,220",arabic:"يَنْفَجِرُ مُنْذُ قُرُونٍ دُونَ أَنْ يُخْطِئَ مَوْعِدَهُ",segs:[{ar:"يَنْفَجِرُ مُنْذُ قُرُونٍ",uz:"asrlar davomida otiladi"},{ar:"دُونَ أَنْ يُخْطِئَ مَوْعِدَهُ",uz:"vaqtini adashtirmasdan"}],full_uz:"U asrlar davomida o‘z vaqtini adashtirmay otilib keladi.",note:"مَوْعِدٌ — belgilangan vaqt, muddat."},
{num:140,time:"00:12:15,220 --> 00:12:17,780",arabic:"شَاهِدًا عَلَى النِّظَامِ الدَّقِيقِ",segs:null,full_uz:"Nozik tartibga guvoh bo‘lib.",note:null},
{num:141,time:"00:12:17,780 --> 00:12:20,520",arabic:"الَّذِي لَا يَخْتَلُّ فِي مَلَكُوتِ اللَّهِ",segs:[{ar:"الَّذِي لَا يَخْتَلُّ",uz:"buzilmaydigan"},{ar:"فِي مَلَكُوتِ اللَّهِ",uz:"Allohning saltanatida"}],full_uz:"Allohning saltanatida buzilmaydigan tartib.",note:"مَلَكُوتٌ — saltanat, ilohiy mulk."},
{num:142,time:"00:12:20,520 --> 00:12:25,580",arabic:"لَكِنْ يَلُوسْتُونْ",segs:null,full_uz:"Ammo Yellowstone.",note:null},
{num:143,time:"00:12:25,580 --> 00:12:29,000",arabic:"لَيْسَ مُجَرَّدَ أَرْضٍ مِنَ الْبُخَارِ وَالْمَاءِ",segs:[{ar:"لَيْسَ مُجَرَّدَ أَرْضٍ",uz:"shunchaki yer emas"},{ar:"مِنَ الْبُخَارِ وَالْمَاءِ",uz:"bug‘ va suvdan iborat"}],full_uz:"U shunchaki bug‘ va suvdan iborat yer emas.",note:null},
{num:144,time:"00:12:29,000 --> 00:12:32,080",arabic:"بَلْ مَأْوًى لِلْحَيَاةِ بِكُلِّ أَشْكَالِهَا",segs:[{ar:"بَلْ مَأْوًى لِلْحَيَاةِ",uz:"balki hayot uchun boshpanadir"},{ar:"بِكُلِّ أَشْكَالِهَا",uz:"uning barcha shakllari bilan"}],full_uz:"Balki hayotning barcha shakllari uchun boshpanadir.",note:"مَأْوًى — boshpana, maskan."},
{num:145,time:"00:12:32,080 --> 00:12:37,080",arabic:"الدُّبَبَةُ وَالذِّئَابُ وَالْبِيسُونُ وَالْأَيَائِلُ",segs:null,full_uz:"Ayiqlar, bo‘rilar, bizonlar va bug‘ular.",note:null},
{num:146,time:"00:12:37,080 --> 00:12:40,440",arabic:"تَجُوبُ سُهُولَهَا الْوَاسِعَةَ بِحُرِّيَّةٍ",segs:[{ar:"تَجُوبُ سُهُولَهَا الْوَاسِعَةَ",uz:"uning keng tekisliklarida kezadi"},{ar:"بِحُرِّيَّةٍ",uz:"erkin holda"}],full_uz:"Ular uning keng tekisliklarida erkin kezadi.",note:"تَجُوبُ — kezib yurmoq."},
{num:147,time:"00:12:40,440 --> 00:12:43,460",arabic:"تُذَكِّرُكَ أَنَّ الْأَرْضَ مَا خُلِقَتْ",segs:[{ar:"تُذَكِّرُكَ",uz:"sizga eslatadi"},{ar:"أَنَّ الْأَرْضَ مَا خُلِقَتْ",uz:"yer yaratilmaganini"}],full_uz:"Bu sizga yer yaratilmaganini eslatadi.",note:null},
{num:148,time:"00:12:43,460 --> 00:12:47,400",arabic:"إِلَّا لِتَكُونَ مَسْكَنًا لِلْكَائِنَاتِ بِإِذْنِ رَبِّهَا",segs:[{ar:"إِلَّا لِتَكُونَ مَسْكَنًا لِلْكَائِنَاتِ",uz:"mavjudotlar uchun maskan bo‘lish uchungina"},{ar:"بِإِذْنِ رَبِّهَا",uz:"o‘z Robbisining izni bilan"}],full_uz:"Balki o‘z Robbisining izni bilan mavjudotlar uchun maskan bo‘lish uchun yaratilganini.",note:"مَسْكَنٌ — yashash joyi, maskan."},
{num:149,time:"00:12:47,399 --> 00:12:58,939",arabic:"وَمِنْ هُنَاكَ نُبْحِرُ شَرْقًا نَحْوَ سَوَاحِلِ فِيتْنَامَ",segs:[{ar:"وَمِنْ هُنَاكَ",uz:"u yerdan"},{ar:"نُبْحِرُ شَرْقًا",uz:"sharqqa suzamiz"},{ar:"نَحْوَ سَوَاحِلِ فِيتْنَامَ",uz:"Vetnam qirg‘oqlari tomon"}],full_uz:"U yerdan sharqqa, Vetnam qirg‘oqlari tomon suzamiz.",note:null},
{num:150,time:"00:12:58,939 --> 00:13:01,980",arabic:"حَيْثُ تَمْتَزِجُ الزُّمُرُّدَةُ بِالْمَاءِ",segs:[{ar:"حَيْثُ تَمْتَزِجُ الزُّمُرُّدَةُ",uz:"zumrad rang yashil suv bilan qorishadi"},{ar:"بِالْمَاءِ",uz:"suv bilan"}],full_uz:"U yerda zumrad rang suv bilan qorishadi.",note:"زُمُرُّدَةٌ — zumrad."},
{num:151,time:"00:13:01,980 --> 00:13:05,220",arabic:"وَتَنْهَضُ مِنَ الْبَحْرِ قِمَمٌ مِنَ الْحَجَرِ",segs:[{ar:"وَتَنْهَضُ مِنَ الْبَحْرِ",uz:"dengizdan ko‘tariladi"},{ar:"قِمَمٌ مِنَ الْحَجَرِ",uz:"tosh cho‘qqilar"}],full_uz:"Dengizdan tosh cho‘qqilar ko‘tariladi.",note:null},
{num:152,time:"00:13:05,220 --> 00:13:08,120",arabic:"كَأَنَّهَا حِكَايَاتٌ خَرَجَتْ مِنَ الْحُلْمِ",segs:[{ar:"كَأَنَّهَا حِكَايَاتٌ",uz:"go‘yo hikoyalardek"},{ar:"خَرَجَتْ مِنَ الْحُلْمِ",uz:"tushdan chiqqan"}],full_uz:"Go‘yo tushdan chiqqan hikoyalardek.",note:null},
{num:153,time:"00:13:08,120 --> 00:13:10,659",arabic:"إِنَّهَا خَلِيجُ هَالُونْغْ",segs:null,full_uz:"Bu Halong ko‘rfazidir.",note:"خَلِيجٌ — ko‘rfaz."},
{num:154,time:"00:13:10,659 --> 00:13:12,179",arabic:"هَالُونْغْ بَيْ",segs:null,full_uz:"Halong Bay.",note:null},
{num:155,time:"00:13:12,179 --> 00:13:20,419",arabic:"فِي هَذَا الْمَكَانِ يَمْتَدُّ مَشْهَدٌ يَأْخُذُ الْأَنْفَاسَ",segs:[{ar:"فِي هَذَا الْمَكَانِ",uz:"bu joyda"},{ar:"يَمْتَدُّ مَشْهَدٌ",uz:"bir manzara cho‘ziladi"},{ar:"يَأْخُذُ الْأَنْفَاسَ",uz:"nafasni tortib oladigan"}],full_uz:"Bu joyda nafasni tortib oladigan bir manzara cho‘zilib yotadi.",note:"يَأْخُذُ الْأَنْفَاسَ — hayratga soladigan, nafasni tortib oladigan."},
{num:156,time:"00:13:20,419 --> 00:13:29,399",arabic:"مِيَاهٌ خَضْرَاءُ صَافِيَةٌ تَتَخَلَّلُهَا أَكْثَرُ مِنْ أَلْفٍ وَسِتِّمِائَةِ جَزِيرَةٍ مِنَ الْحَجَرِ الْجِيرِيِّ",segs:[{ar:"مِيَاهٌ خَضْرَاءُ صَافِيَةٌ",uz:"musaffo yashil suvlar"},{ar:"تَتَخَلَّلُهَا أَكْثَرُ مِنْ أَلْفٍ وَسِتِّمِائَةِ جَزِيرَةٍ",uz:"ular orasida ming olti yuzdan ortiq orol bor"},{ar:"مِنَ الْحَجَرِ الْجِيرِيِّ",uz:"ohaktoshdan"}],full_uz:"Musaffo yashil suvlar orasida ohaktoshdan iborat ming olti yuzdan ortiq orol joylashgan.",note:"الْحَجَرُ الْجِيرِيُّ — ohaktosh."},
{num:157,time:"00:13:29,399 --> 00:13:36,599",arabic:"تَرْتَفِعُ شَامِخَةً مِنَ الْبَحْرِ كَأَنَّهَا ظُهُورُ تَنَانِينِ نَائِمَةٍ فِي سَلَامٍ أَزَلِيٍّ",segs:[{ar:"تَرْتَفِعُ شَامِخَةً مِنَ الْبَحْرِ",uz:"dengizdan salobat bilan ko‘tariladi"},{ar:"كَأَنَّهَا ظُهُورُ تَنَانِينِ نَائِمَةٍ",uz:"go‘yo uxlayotgan ajdarlarning bellaridek"},{ar:"فِي سَلَامٍ أَزَلِيٍّ",uz:"abadiy osoyishtalikda"}],full_uz:"Ular abadiy osoyishtalikda uxlayotgan ajdarlarning bellaridek dengizdan salobat bilan ko‘tariladi.",note:"شَامِخٌ — baland, salobatli."},
{num:158,time:"00:13:36,600 --> 00:13:51,639",arabic:"عَلَى مَدَى مَلَايِينِ السِّنِينَ نَحَتَتِ الرِّيَاحُ وَالْأَمْوَاجُ الصُّخُورَ بِأَمْرِ اللَّهِ",segs:[{ar:"عَلَى مَدَى مَلَايِينِ السِّنِينَ",uz:"millionlab yillar davomida"},{ar:"نَحَتَتِ الرِّيَاحُ وَالْأَمْوَاجُ الصُّخُورَ",uz:"shamollar va to‘lqinlar qoyalarni o‘ydilar"},{ar:"بِأَمْرِ اللَّهِ",uz:"Allohning amri bilan"}],full_uz:"Millionlab yillar davomida shamollar va to‘lqinlar Allohning amri bilan qoyalarni o‘yib bordi.",note:"نَحَتَ — o‘ymoq, yo‘nmoq."},
{num:159,time:"00:13:51,639 --> 00:13:55,779",arabic:"فَكَوَّنَتْ كُهُوفًا وَأَقْوَاسًا وَبُحَيْرَاتٍ خَفِيَّةً",segs:[{ar:"فَكَوَّنَتْ كُهُوفًا وَأَقْوَاسًا",uz:"natijada g‘orlar va arkalar hosil qildi"},{ar:"وَبُحَيْرَاتٍ خَفِيَّةً",uz:"va yashirin ko‘llarni"}],full_uz:"Natijada g‘orlar, arkalar va yashirin ko‘llar hosil bo‘ldi.",note:"أَقْوَاسٌ — arkalar, ravoqlar."},
{num:160,time:"00:13:55,779 --> 00:13:59,720",arabic:"تَجْعَلُ الْقَلْبَ يُسَبِّحُ لِجَلَالِ الْخَالِقِ",segs:[{ar:"تَجْعَلُ الْقَلْبَ يُسَبِّحُ",uz:"qalbni tasbeh aytishga majbur qiladi"},{ar:"لِجَلَالِ الْخَالِقِ",uz:"Yaratuvchining ulug‘vorligi uchun"}],full_uz:"Bu manzaralar qalbni Yaratuvchining ulug‘vorligi uchun tasbeh aytishga undaydi.",note:null},
{num:161,time:"00:13:59,720 --> 00:14:04,420",arabic:"الَّذِي أَبْدَعَ هَذَا الْجَمَالَ بِلَا أَدَوَاتٍ وَلَا أَنَامِلَ",segs:[{ar:"الَّذِي أَبْدَعَ هَذَا الْجَمَالَ",uz:"bu go‘zallikni yaratgan Zot"},{ar:"بِلَا أَدَوَاتٍ وَلَا أَنَامِلَ",uz:"asboblarsiz va barmoqlarsiz"}],full_uz:"Bu go‘zallikni asboblarsiz va barmoqlarsiz yaratgan Zot.",note:"أَبْدَعَ — mislsiz, ajoyib tarzda yaratmoq."},
{num:162,time:"00:14:04,419 --> 00:14:25,699",arabic:"نَرْحَلُ إِلَى ضِفَافِ نَهْرِ يَامُونَةَ فِي أَغْرَا بِالْهِنْدِ",segs:[{ar:"نَرْحَلُ إِلَى ضِفَافِ نَهْرِ يَامُونَةَ",uz:"Yamuna daryosi sohillariga yo‘l olamiz"},{ar:"فِي أَغْرَا بِالْهِنْدِ",uz:"Hindistonning Agra shahrida"}],full_uz:"Hindistonning Agra shahridagi Yamuna daryosi sohillariga yo‘l olamiz.",note:null},
{num:163,time:"00:14:25,699 --> 00:14:29,959",arabic:"حَيْثُ تَحَوَّلَ الْحُبُّ إِلَى حَجَرٍ نَاطِقٍ بِالْجَمَالِ",segs:[{ar:"حَيْثُ تَحَوَّلَ الْحُبُّ",uz:"u yerda muhabbat aylandi"},{ar:"إِلَى حَجَرٍ نَاطِقٍ بِالْجَمَالِ",uz:"go‘zallik so‘zlovchi toshga"}],full_uz:"U yerda muhabbat go‘zallik haqida so‘zlovchi toshga aylandi.",note:"نَاطِقٌ — so‘zlovchi, gapiruvchi."},
{num:164,time:"00:14:29,960 --> 00:14:34,920",arabic:"وَتَجَلَّى الْوَفَاءُ فِي أَنْقَى صُوَرِهِ تَاجُ مَحَلٍّ",segs:[{ar:"وَتَجَلَّى الْوَفَاءُ",uz:"va vafo namoyon bo‘ldi"},{ar:"فِي أَنْقَى صُوَرِهِ",uz:"o‘zining eng sof ko‘rinishida"},{ar:"تَاجُ مَحَلٍّ",uz:"Toj Mahal"}],full_uz:"Va vafo o‘zining eng sof ko‘rinishida — Toj Mahalda namoyon bo‘ldi.",note:"الْوَفَاءُ — vafo, sadoqat."},
{num:165,time:"00:14:34,920 --> 00:14:38,620",arabic:"تَحْتَ شَمْسِ الْهِنْدِ الْبَيْضَاءِ",segs:null,full_uz:"Hindistonning oqish quyoshi ostida.",note:null},
{num:166,time:"00:14:38,620 --> 00:14:41,800",arabic:"يَلْتَمِعُ هَذَا الْقَصْرُ الرُّخَامِيُّ",segs:null,full_uz:"Bu marmar saroy yaltiraydi.",note:"رُخَامِيٌّ — marmardan yasalgan."},
{num:167,time:"00:14:41,800 --> 00:14:44,340",arabic:"كَأَنَّهُ قِطْعَةٌ مِنَ النُّورِ",segs:null,full_uz:"Go‘yo nurdan bir parcha.",note:null},
{num:168,time:"00:14:44,340 --> 00:14:48,220",arabic:"بُنِيَ مُنْذُ قُرُونٍ بِيَدِ إِنْسَانٍ أَحَبَّ",segs:[{ar:"بُنِيَ مُنْذُ قُرُونٍ",uz:"asrlar oldin qurilgan"},{ar:"بِيَدِ إِنْسَانٍ أَحَبَّ",uz:"sevgan bir inson qo‘li bilan"}],full_uz:"Asrlar oldin sevgan bir inson qo‘li bilan qurilgan.",note:null},
{num:169,time:"00:14:48,220 --> 00:14:53,160",arabic:"فَأَبْدَعَ بِنَاءً صَارَ مِنْ رُمُوزِ الْجَمَالِ عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"فَأَبْدَعَ بِنَاءً",uz:"va ajoyib bir bino yaratdi"},{ar:"صَارَ مِنْ رُمُوزِ الْجَمَالِ",uz:"go‘zallik ramzlaridan biriga aylandi"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"}],full_uz:"Va yer yuzidagi go‘zallik ramzlaridan biriga aylangan ajoyib bino yaratdi.",note:"رُمُوزٌ — ramzlar."},
{num:170,time:"00:14:53,160 --> 00:14:59,200",arabic:"لَكِنْ وَرَاءَ الْحَجَرِ",segs:null,full_uz:"Ammo tosh ortida.",note:null},
{num:171,time:"00:14:59,200 --> 00:15:05,740",arabic:"رِسَالَةٌ أَعْمَقُ أَنَّ الْمَشَاعِرَ الصَّادِقَةَ قَدْ تَصِيرُ أَثَرًا خَالِدًا",segs:[{ar:"رِسَالَةٌ أَعْمَقُ",uz:"chuqurroq bir ma’no bor"},{ar:"أَنَّ الْمَشَاعِرَ الصَّادِقَةَ",uz:"samimiy tuyg‘ular"},{ar:"قَدْ تَصِيرُ أَثَرًا خَالِدًا",uz:"abadiy izga aylanishi mumkinligi"}],full_uz:"Ammo tosh ortida samimiy tuyg‘ular abadiy izga aylanishi mumkinligi haqidagi chuqurroq ma’no bor.",note:"خَالِدٌ — boqiy, abadiy."},
{num:172,time:"00:15:05,740 --> 00:15:10,160",arabic:"وَأَنَّ الْجَمَالَ الْحَقِيقِيَّ لَا يُخَلِّدُهُ الرُّخَامُ",segs:[{ar:"وَأَنَّ الْجَمَالَ الْحَقِيقِيَّ",uz:"va haqiqiy go‘zallikni"},{ar:"لَا يُخَلِّدُهُ الرُّخَامُ",uz:"marmar boqiy qilmaydi"}],full_uz:"Va haqiqiy go‘zallikni marmar boqiy qilmasligini.",note:"يُخَلِّدُ — boqiy qilmoq, abadiylashtirmoq."},
{num:173,time:"00:15:10,160 --> 00:15:15,840",arabic:"بَلِ النِّيَّةُ الْخَالِصَةُ الَّتِي يُبَارِكُهَا اللَّهُ فَتَبْقَى مَعَ الْأَزْمَانِ",segs:[{ar:"بَلِ النِّيَّةُ الْخَالِصَةُ",uz:"balki sof niyat"},{ar:"الَّتِي يُبَارِكُهَا اللَّهُ",uz:"Alloh baraka beradigan"},{ar:"فَتَبْقَى مَعَ الْأَزْمَانِ",uz:"va u zamonlar bilan qoladi"}],full_uz:"Balki Alloh baraka beradigan sof niyat zamonlar osha qoladi.",note:"النِّيَّةُ الْخَالِصَةُ — sof niyat."},
{num:174,time:"00:15:15,840 --> 00:15:21,800",arabic:"بُنِيَ تَاجُ مَحَلٍّ فِي الْقَرْنِ السَّابِعَ عَشَرَ",segs:[{ar:"بُنِيَ تَاجُ مَحَلٍّ",uz:"Toj Mahal qurilgan"},{ar:"فِي الْقَرْنِ السَّابِعَ عَشَرَ",uz:"o‘n yettinchi asrda"}],full_uz:"Toj Mahal o‘n yettinchi asrda qurilgan.",note:null},
{num:175,time:"00:15:21,800 --> 00:15:25,220",arabic:"عَلَى يَدِ الْإِمْبِرَاطُورِ شَاهْ جَهَانَ",segs:[{ar:"عَلَى يَدِ الْإِمْبِرَاطُورِ",uz:"imperator qo‘li bilan"},{ar:"شَاهْ جَهَانَ",uz:"Shoh Jahon"}],full_uz:"Imperator Shoh Jahon tomonidan.",note:null},
{num:176,time:"00:15:25,220 --> 00:15:28,580",arabic:"وَفَاءً لِزَوْجَتِهِ مُمْتَازَ مَحَلٍّ",segs:[{ar:"وَفَاءً لِزَوْجَتِهِ",uz:"xotiniga vafo sifatida"},{ar:"مُمْتَازَ مَحَلٍّ",uz:"Mumtoz Mahal"}],full_uz:"Xotini Mumtoz Mahalga vafo sifatida.",note:null},
{num:177,time:"00:15:28,580 --> 00:15:34,000",arabic:"فَكَانَ شَاهِدًا مِنْ رُخَامٍ أَبْيَضَ عَلَى حُبٍّ لَا يَفْنَى",segs:[{ar:"فَكَانَ شَاهِدًا مِنْ رُخَامٍ أَبْيَضَ",uz:"u oq marmardan yasalgan guvoh bo‘ldi"},{ar:"عَلَى حُبٍّ لَا يَفْنَى",uz:"yo‘qolmaydigan muhabbatga"}],full_uz:"U yo‘qolmaydigan muhabbatga guvoh bo‘lgan oq marmardan yasalgan obidaga aylandi.",note:"يَفْنَى — yo‘qolmoq, tugamoq."},
{num:178,time:"00:15:34,000 --> 00:15:37,500",arabic:"وَعَلَى وَفَاءٍ خُلِّدَ فِي ذَاكِرَةِ الزَّمَانِ",segs:[{ar:"وَعَلَى وَفَاءٍ",uz:"va vafoga"},{ar:"خُلِّدَ فِي ذَاكِرَةِ الزَّمَانِ",uz:"zamon xotirasida abadiylashtirilgan"}],full_uz:"Va zamon xotirasida abadiylashtirilgan vafoga.",note:null},
{num:179,time:"00:15:37,500 --> 00:15:42,740",arabic:"كُلُّ تَفْصِيلٍ فِيهِ يَنْطِقُ بِالْإِتْقَانِ",segs:[{ar:"كُلُّ تَفْصِيلٍ فِيهِ",uz:"undagi har bir tafsilot"},{ar:"يَنْطِقُ بِالْإِتْقَانِ",uz:"mukammallikdan so‘zlaydi"}],full_uz:"Undagi har bir tafsilot mukammallikdan so‘zlaydi.",note:"الْإِتْقَانُ — mukammallik, puxtalik."},
{num:180,time:"00:15:42,740 --> 00:15:44,740",arabic:"تَنَاظُرُهُ الْمِثَالِيُّ",segs:null,full_uz:"Uning mukammal mutanosibligi.",note:"تَنَاظُرٌ — mutanosiblik, simmetriya."},
{num:181,time:"00:15:44,740 --> 00:15:47,400",arabic:"نُقُوشُهُ الزَّهْرِيَّةُ الرَّقِيقَةُ",segs:null,full_uz:"Nafis gulli naqshlari.",note:"نَقْشٌ زَهْرِيٌّ — gulli naqsh."},
{num:182,time:"00:15:47,400 --> 00:15:51,660",arabic:"وَرُخَامُهُ الَّذِي يَتَبَدَّلُ لَوْنُهُ مَعَ ضَوْءِ الشَّمْسِ",segs:[{ar:"وَرُخَامُهُ",uz:"va uning marmari"},{ar:"الَّذِي يَتَبَدَّلُ لَوْنُهُ",uz:"rangi o‘zgarib turadigan"},{ar:"مَعَ ضَوْءِ الشَّمْسِ",uz:"quyosh nuri bilan"}],full_uz:"Va quyosh nuri bilan rangi o‘zgarib turadigan marmari.",note:"يَتَبَدَّلُ — o‘zgarib turmoq."},
{num:183,time:"00:15:51,660 --> 00:15:54,520",arabic:"كَأَنَّهُ يَتَنَفَّسُ حَيَاةً مِنْ نُورٍ",segs:[{ar:"كَأَنَّهُ يَتَنَفَّسُ",uz:"go‘yo nafas olayotgandek"},{ar:"حَيَاةً مِنْ نُورٍ",uz:"nurdan hayotni"}],full_uz:"Go‘yo nurdan yaralgan hayot bilan nafas olayotgandek.",note:null},
{num:184,time:"00:15:54,519 --> 00:16:03,259",arabic:"وَحِينَ تَعْبُرُ بَوَّابَتَهُ الْكُبْرَى وَتَرَى الْقُبَّةَ تَرْتَفِعُ فَوْقَ الْبِرْكَةِ الْعَاكِسَةِ",segs:[{ar:"وَحِينَ تَعْبُرُ بَوَّابَتَهُ الْكُبْرَى",uz:"katta darvozasidan o‘tganingizda"},{ar:"وَتَرَى الْقُبَّةَ تَرْتَفِعُ",uz:"va gumbazning ko‘tarilganini ko‘rsangiz"},{ar:"فَوْقَ الْبِرْكَةِ الْعَاكِسَةِ",uz:"aks ettiruvchi hovuz ustida"}],full_uz:"Katta darvozasidan o‘tib, gumbazning aks ettiruvchi hovuz ustida ko‘tarilganini ko‘rganingizda.",note:"بَوَّابَةٌ — darvoza."},
{num:185,time:"00:16:03,259 --> 00:16:09,460",arabic:"يَخِيمُ الصَّمْتُ وَيَغْدُو الْهَوَاءُ مُشَبَّعًا بِرَائِحَةِ التَّارِيخِ وَالْحَنِينِ",segs:[{ar:"يَخِيمُ الصَّمْتُ",uz:"sukunat cho‘kadi"},{ar:"وَيَغْدُو الْهَوَاءُ مُشَبَّعًا",uz:"va havo to‘ladi"},{ar:"بِرَائِحَةِ التَّارِيخِ وَالْحَنِينِ",uz:"tarix va sog‘inch hidiga"}],full_uz:"Sukunat cho‘kadi va havo tarix hamda sog‘inch iforiga to‘ladi.",note:"يَخِيمُ — cho‘kmoq, hukm surmoq."},
{num:186,time:"00:16:09,460 --> 00:16:14,000",arabic:"كَأَنَّ الْمَكَانَ نَفْسَهُ يُصَلِّي لِذِكْرَى لَا تَزُولُ",segs:[{ar:"كَأَنَّ الْمَكَانَ نَفْسَهُ يُصَلِّي",uz:"go‘yo joyning o‘zi ibodat qilayotgandek"},{ar:"لِذِكْرَى لَا تَزُولُ",uz:"yo‘qolmaydigan xotira uchun"}],full_uz:"Go‘yo joyning o‘zi yo‘qolmaydigan xotira uchun ibodat qilayotgandek.",note:null},
{num:187,time:"00:16:14,000 --> 00:16:22,759",arabic:"وَفِي قَلْبِ غَابَاتِ كُرْوَاتِيَا تَخْتَبِئُ لَوْحَةٌ مِنْ أَنْقَى مَا رَسَمَ الْخَالِقُ",segs:[{ar:"وَفِي قَلْبِ غَابَاتِ كُرْوَاتِيَا",uz:"Xorvatiya o‘rmonlari bag‘rida"},{ar:"تَخْتَبِئُ لَوْحَةٌ",uz:"bir manzara yashiringan"},{ar:"مِنْ أَنْقَى مَا رَسَمَ الْخَالِقُ",uz:"Yaratuvchi chizgan eng sof manzaralardan"}],full_uz:"Xorvatiya o‘rmonlari bag‘rida Yaratuvchi yaratgan eng sof manzaralardan biri yashiringan.",note:"تَخْتَبِئُ — yashirinmoq."},
{num:188,time:"00:16:22,759 --> 00:16:26,120",arabic:"إِنَّهَا بُحَيْرَاتُ بْلِيتْفِيسَ الْوَطَنِيَّةُ",segs:null,full_uz:"Bu Plitvitsa milliy ko‘llaridir.",note:null},
{num:189,time:"00:16:26,120 --> 00:16:32,819",arabic:"جَنَّةٌ مَائِيَّةٌ تَتَكَوَّنُ مِنْ سِتَّ عَشْرَةَ بُحَيْرَةً صَافِيَةٍ كَالْكِرِسْتَالِ",segs:[{ar:"جَنَّةٌ مَائِيَّةٌ",uz:"suvli jannat"},{ar:"تَتَكَوَّنُ مِنْ سِتَّ عَشْرَةَ بُحَيْرَةً",uz:"o‘n olti ko‘ldan tashkil topgan"},{ar:"صَافِيَةٍ كَالْكِرِسْتَالِ",uz:"billurdek tiniq"}],full_uz:"Billurdek tiniq o‘n olti ko‘ldan tashkil topgan suvli jannat.",note:null},
{num:190,time:"00:16:32,819 --> 00:16:39,580",arabic:"تَتَدَرَّجُ بَيْنَهَا الشَّلَّالَاتُ فِي انْسِجَامٍ كَأَنَّهَا خُيُوطُ ضَوْءٍ تَنْسَابُ بَيْنَ الْأَشْجَارِ",segs:[{ar:"تَتَدَرَّجُ بَيْنَهَا الشَّلَّالَاتُ",uz:"ular orasida sharsharalar pog‘onalanadi"},{ar:"فِي انْسِجَامٍ",uz:"uyg‘un tarzda"},{ar:"كَأَنَّهَا خُيُوطُ ضَوْءٍ",uz:"go‘yo nur iplaridek"},{ar:"تَنْسَابُ بَيْنَ الْأَشْجَارِ",uz:"daraxtlar orasida oqadi"}],full_uz:"Sharsharalar ular orasida uyg‘un tarzda pog‘onalanib, daraxtlar orasida oqayotgan nur iplaridek ko‘rinadi.",note:null},
{num:191,time:"00:16:39,580 --> 00:16:49,439",arabic:"تَتَبَدَّلُ أَلْوَانُ الْمِيَاهِ بَيْنَ الْفِيرُوزِيِّ وَالزُّمُرُّدِيِّ وَالْيَاقُوتِيِّ",segs:[{ar:"تَتَبَدَّلُ أَلْوَانُ الْمِيَاهِ",uz:"suvlarning ranglari o‘zgaradi"},{ar:"بَيْنَ الْفِيرُوزِيِّ وَالزُّمُرُّدِيِّ وَالْيَاقُوتِيِّ",uz:"feruza, zumrad va yoqut ranglari orasida"}],full_uz:"Suvlarning ranglari feruza, zumrad va yoqut ranglari orasida o‘zgarib turadi.",note:"يَاقُوتِيٌّ — yoqut rangli."},
{num:192,time:"00:16:49,440 --> 00:16:52,960",arabic:"بِحَسَبِ الضَّوْءِ وَالْمَعَادِنِ وَالْفُصُولِ",segs:null,full_uz:"Yorug‘lik, minerallar va fasllarga qarab.",note:"بِحَسَبِ — ...ga qarab."},
{num:193,time:"00:16:52,960 --> 00:16:56,260",arabic:"فَلَا تَرَاهَا مَرَّتَيْنِ بِنَفْسِ اللَّوْنِ",segs:[{ar:"فَلَا تَرَاهَا مَرَّتَيْنِ",uz:"shuning uchun uni ikki marta ko‘rmaysiz"},{ar:"بِنَفْسِ اللَّوْنِ",uz:"aynan bir xil rangda"}],full_uz:"Shuning uchun uni ikki marta aynan bir xil rangda ko‘rmaysiz.",note:null},
{num:194,time:"00:16:56,260 --> 00:17:01,440",arabic:"وَكَأَنَّهَا مِرْآةٌ تَعْكِسُ تَغَيُّرَ الْحَيَاةِ ذَاتِهَا",segs:[{ar:"وَكَأَنَّهَا مِرْآةٌ",uz:"go‘yo ko‘zgu"},{ar:"تَعْكِسُ تَغَيُّرَ الْحَيَاةِ ذَاتِهَا",uz:"hayotning o‘zgarishini aks ettiradigan"}],full_uz:"Go‘yo hayotning o‘zgarishini aks ettiradigan ko‘zgudek.",note:"مِرْآةٌ — ko‘zgu."},
{num:195,time:"00:17:01,440 --> 00:17:11,100",arabic:"تَمْتَدُّ جُسُورٌ خَشَبِيَّةٌ فَوْقَ الْجَدَاوِلِ وَالْبِرَكِ",segs:[{ar:"تَمْتَدُّ جُسُورٌ خَشَبِيَّةٌ",uz:"yog‘och ko‘priklar cho‘zilib boradi"},{ar:"فَوْقَ الْجَدَاوِلِ وَالْبِرَكِ",uz:"soylar va hovuzlar ustidan"}],full_uz:"Yog‘och ko‘priklar soylar va hovuzlar ustidan cho‘zilib boradi.",note:"جَدْوَلٌ — soy, kichik oqim."},
{num:196,time:"00:17:11,100 --> 00:17:16,019",arabic:"تَجْعَلُ الزَّائِرَ يَسِيرُ وَسَطَ الْمَاءِ كَأَنَّهُ يَمْشِي عَلَى حُلْمٍ",segs:[{ar:"تَجْعَلُ الزَّائِرَ يَسِيرُ وَسَطَ الْمَاءِ",uz:"tashrif buyuruvchini suv o‘rtasida yuradigan qiladi"},{ar:"كَأَنَّهُ يَمْشِي عَلَى حُلْمٍ",uz:"go‘yo tush ustida yurgandek"}],full_uz:"Ular tashrif buyuruvchini go‘yo tush ustida yurgandek suv o‘rtasida yurgizadi.",note:null},
{num:197,time:"00:17:16,019 --> 00:17:33,059",arabic:"فِي الرَّبِيعِ وَالصَّيْفِ تَمْتَلِئُ الْغَابَةُ بِزَقْزَقَةِ الطُّيُورِ وَعِطْرِ الْأَزْهَارِ الْبَرِّيَّةِ",segs:[{ar:"فِي الرَّبِيعِ وَالصَّيْفِ",uz:"bahor va yozda"},{ar:"تَمْتَلِئُ الْغَابَةُ",uz:"o‘rmon to‘ladi"},{ar:"بِزَقْزَقَةِ الطُّيُورِ",uz:"qushlarning sayrashi bilan"},{ar:"وَعِطْرِ الْأَزْهَارِ الْبَرِّيَّةِ",uz:"va yovvoyi gullarning ifori bilan"}],full_uz:"Bahor va yozda o‘rmon qushlar sayrashi va yovvoyi gullarning iforiga to‘ladi.",note:"زَقْزَقَةٌ — qushlarning sayrashi."},
{num:198,time:"00:17:33,059 --> 00:17:39,879",arabic:"وَفِي الشِّتَاءِ تَتَجَمَّدُ الشَّلَّالَاتُ لِتَصِيرَ تَمَاثِيلَ مِنْ ثَلْجٍ وَنُورٍ",segs:[{ar:"وَفِي الشِّتَاءِ",uz:"qishda"},{ar:"تَتَجَمَّدُ الشَّلَّالَاتُ",uz:"sharsharalar muzlaydi"},{ar:"لِتَصِيرَ تَمَاثِيلَ مِنْ ثَلْجٍ وَنُورٍ",uz:"qor va nurdan haykallarga aylanishi uchun"}],full_uz:"Qishda sharsharalar muzlab, qor va nurdan yasalgan haykallarga aylanadi.",note:"تَتَجَمَّدُ — muzlamoq."},
{num:199,time:"00:17:39,880 --> 00:17:43,640",arabic:"فَيَتَحَوَّلُ الْمَكَانُ إِلَى أُسْطُورَةٍ بَيْضَاءَ",segs:[{ar:"فَيَتَحَوَّلُ الْمَكَانُ",uz:"shunda joy aylanadi"},{ar:"إِلَى أُسْطُورَةٍ بَيْضَاءَ",uz:"oq afsonaga"}],full_uz:"Shunda bu joy oq afsonaga aylanadi.",note:"أُسْطُورَةٌ — afsona."},
{num:200,time:"00:17:43,640 --> 00:17:47,580",arabic:"يُسَبِّحُ فِيهَا السَّقِيعُ بِاسْمِ الْخَالِقِ الْجَلِيلِ",segs:[{ar:"يُسَبِّحُ فِيهَا السَّقِيعُ",uz:"unda qirov tasbeh aytadi"},{ar:"بِاسْمِ الْخَالِقِ الْجَلِيلِ",uz:"ulug‘ Yaratuvchining nomi bilan"}],full_uz:"Unda qirov ulug‘ Yaratuvchining nomi bilan tasbeh aytayotgandek bo‘ladi.",note:"السَّقِيعُ — qirov, muzlagan shabnam."},
{num:201,time:"00:17:47,580 --> 00:18:02,340",arabic:"نُحَلِّقُ جَنُوبًا إِلَى التِّلَالِ الْمُشْرِقَةِ بِنُورِ الشَّمْسِ",segs:[{ar:"نُحَلِّقُ جَنُوبًا",uz:"janubga uchamiz"},{ar:"إِلَى التِّلَالِ الْمُشْرِقَةِ",uz:"yorqin tepaliklarga"},{ar:"بِنُورِ الشَّمْسِ",uz:"quyosh nuri bilan"}],full_uz:"Janubga, quyosh nuri bilan yorishgan tepaliklarga uchamiz.",note:"تَلٌّ — tepalik."},
{num:202,time:"00:18:02,340 --> 00:18:06,880",arabic:"فِي قَلْبِ الْأَنْدَلُسِ حَيْثُ يَلْتَقِي التَّارِيخُ بِالْفَنِّ",segs:[{ar:"فِي قَلْبِ الْأَنْدَلُسِ",uz:"Andalusiya yuragida"},{ar:"حَيْثُ يَلْتَقِي التَّارِيخُ بِالْفَنِّ",uz:"tarix san’at bilan uchrashadigan joyda"}],full_uz:"Andalusiya yuragida, tarix san’at bilan uchrashadigan joyda.",note:null},
{num:203,time:"00:18:06,880 --> 00:18:12,360",arabic:"وَتَلْتَفُّ الْأَحْلَامُ حَوْلَ مُعْجِزَةٍ مِنْ مُعْجِزَاتِ الْجَمَالِ",segs:[{ar:"وَتَلْتَفُّ الْأَحْلَامُ",uz:"orzu-havaslar aylanadi"},{ar:"حَوْلَ مُعْجِزَةٍ",uz:"bir mo‘jiza atrofida"},{ar:"مِنْ مُعْجِزَاتِ الْجَمَالِ",uz:"go‘zallik mo‘jizalaridan"}],full_uz:"Orzular go‘zallik mo‘jizalaridan biri atrofida aylanadi.",note:"تَلْتَفُّ — o‘ralmoq, atrofida aylanish."},
{num:204,time:"00:18:12,360 --> 00:18:14,740",arabic:"قَصْرُ الْحَمْرَاءِ",segs:null,full_uz:"Alhambra saroyi.",note:null},
{num:205,time:"00:18:14,740 --> 00:18:21,740",arabic:"يَعْلُو الْقَصْرُ فَوْقَ مَدِينَةِ غَرْنَاطَةَ كَالتَّاجِ الذَّهَبِيِّ عِنْدَ الْمَغِيبِ",segs:[{ar:"يَعْلُو الْقَصْرُ فَوْقَ مَدِينَةِ غَرْنَاطَةَ",uz:"saroy Granada shahri ustida yuksaladi"},{ar:"كَالتَّاجِ الذَّهَبِيِّ",uz:"oltin toj kabi"},{ar:"عِنْدَ الْمَغِيبِ",uz:"quyosh botishida"}],full_uz:"Saroy quyosh botishida Granada shahri ustida oltin toj kabi yuksaladi.",note:"الْمَغِيبُ — quyosh botishi."},
{num:206,time:"00:18:21,740 --> 00:18:26,000",arabic:"جُدْرَانُهُ تَهْمِسُ بِحِكَايَاتٍ عُمْرُهَا قُرُونٌ",segs:[{ar:"جُدْرَانُهُ تَهْمِسُ",uz:"uning devorlari shivirlaydi"},{ar:"بِحِكَايَاتٍ عُمْرُهَا قُرُونٌ",uz:"asrlar yoshidagi hikoyalarni"}],full_uz:"Uning devorlari asrlik hikoyalarni shivirlaydi.",note:null},
{num:207,time:"00:18:26,000 --> 00:18:31,020",arabic:"وَأَرْوِقَتُهُ تَشْهَدُ أَنَّ الْإِتْقَانَ إِذَا امْتَزَجَ بِالْإِيمَانِ",segs:[{ar:"وَأَرْوِقَتُهُ تَشْهَدُ",uz:"uning ravoqlari guvohlik beradi"},{ar:"أَنَّ الْإِتْقَانَ",uz:"mukammallik"},{ar:"إِذَا امْتَزَجَ بِالْإِيمَانِ",uz:"iymon bilan qorishsa"}],full_uz:"Uning ravoqlari mukammallik iymon bilan qorishsa.",note:"رِوَاقٌ — ravoq, ayvon."},
{num:208,time:"00:18:31,020 --> 00:18:33,220",arabic:"صَارَ جَلَالًا خَالِدًا",segs:null,full_uz:"Boqiy ulug‘vorlikka aylanadi.",note:null},
{num:209,time:"00:18:33,220 --> 00:18:39,259",arabic:"بَنَاهُ مُلُوكُ الْمُسْلِمِينَ فِي الْقَرْنِ الثَّالِثَ عَشَرَ",segs:[{ar:"بَنَاهُ مُلُوكُ الْمُسْلِمِينَ",uz:"uni musulmon podshohlari qurdilar"},{ar:"فِي الْقَرْنِ الثَّالِثَ عَشَرَ",uz:"o‘n uchinchi asrda"}],full_uz:"Uni o‘n uchinchi asrda musulmon podshohlari qurgan.",note:null},
{num:210,time:"00:18:39,259 --> 00:18:43,539",arabic:"فَجَعَلُوهُ آيَةً مِنْ رَوَائِعِ الْعِمَارَةِ الْإِسْلَامِيَّةِ",segs:[{ar:"فَجَعَلُوهُ آيَةً",uz:"shunday qilib uni bir oyatga aylantirdilar"},{ar:"مِنْ رَوَائِعِ الْعِمَارَةِ الْإِسْلَامِيَّةِ",uz:"islom me’morchiligi durdonalaridan"}],full_uz:"Shunday qilib, uni islom me’morchiligi durdonalaridan biriga aylantirdilar.",note:"رَوَائِعُ الْعِمَارَةِ — me’morchilik durdonalari."},
{num:211,time:"00:18:43,539 --> 00:18:50,660",arabic:"كُلُّ قَوْسٍ فِيهِ وَكُلُّ رِوَاقٍ وَسَاحَةٍ مَنْحُوتَةٌ بِتَفَاصِيلَ دَقِيقَةٍ",segs:[{ar:"كُلُّ قَوْسٍ فِيهِ",uz:"undagi har bir ravoq"},{ar:"وَكُلُّ رِوَاقٍ وَسَاحَةٍ",uz:"har bir ayvon va hovli"},{ar:"مَنْحُوتَةٌ بِتَفَاصِيلَ دَقِيقَةٍ",uz:"nozik tafsilotlar bilan o‘yilgan"}],full_uz:"Undagi har bir ravoq, har bir ayvon va hovli nozik tafsilotlar bilan o‘yilgan.",note:"مَنْحُوتٌ — o‘yilgan, naqshlangan."},
{num:212,time:"00:18:50,660 --> 00:18:53,620",arabic:"كَأَنَّهَا تَسْبِيحَةٌ مِنْ حَجَرٍ",segs:null,full_uz:"Go‘yo toshdan yasalgan tasbeh.",note:null},
{num:213,time:"00:18:53,619 --> 00:19:05,979",arabic:"وَأَنْتَ تَسِيرُ بَيْنَ أَبْهَائِهِ تُطَالِعُ نُقُوشَ الْأَرَابِيسْكِ الْمُتَشَابِكَةَ وَأَعْمِدَةَ الرُّخَامِ النَّاصِعَةَ",segs:[{ar:"وَأَنْتَ تَسِيرُ بَيْنَ أَبْهَائِهِ",uz:"uning saroylari orasida yurganingizda"},{ar:"تُطَالِعُ نُقُوشَ الْأَرَابِيسْكِ الْمُتَشَابِكَةَ",uz:"bir-biriga chirmashgan arabesk naqshlarini tomosha qilasiz"},{ar:"وَأَعْمِدَةَ الرُّخَامِ النَّاصِعَةَ",uz:"va oppoq marmar ustunlarni"}],full_uz:"Uning saroylari orasida yurganingizda bir-biriga chirmashgan arabesk naqshlari va oppoq marmar ustunlarni tomosha qilasiz.",note:"أَرَابِيسْكُ — arabesk bezak uslubi."},
{num:214,time:"00:19:05,979 --> 00:19:14,000",arabic:"وَنَوَافِيرَ الْمَاءِ الَّتِي تَهْمِسُ بِأَلْحَانِ الصَّفَاءِ كَأَنَّهَا تُعِيدُ إِلَى الْقَلْبِ سَكِينَةَ الْإِيمَانِ",segs:[{ar:"وَنَوَافِيرَ الْمَاءِ",uz:"va suv favvoralarini"},{ar:"الَّتِي تَهْمِسُ بِأَلْحَانِ الصَّفَاءِ",uz:"musaffolik ohanglarini shivirlaydigan"},{ar:"كَأَنَّهَا تُعِيدُ إِلَى الْقَلْبِ",uz:"go‘yo qalbga qaytarayotgandek"},{ar:"سَكِينَةَ الْإِيمَانِ",uz:"iymon xotirjamligini"}],full_uz:"Va musaffolik ohanglarini shivirlaydigan suv favvoralarini ko‘rasiz, go‘yo ular qalbga iymon xotirjamligini qaytarayotgandek.",note:"سَكِينَةٌ — xotirjamlik, sokinlik."},
{num:215,time:"00:19:14,000 --> 00:19:23,759",arabic:"مِنْ بَاحَةِ الْأُسُودِ إِلَى حَدَائِقِ الْجَنَّةِ الْعَابِقَةِ بِالْعِطْرِ",segs:[{ar:"مِنْ بَاحَةِ الْأُسُودِ",uz:"Arslonlar hovlisidan"},{ar:"إِلَى حَدَائِقِ الْجَنَّةِ",uz:"jannat bog‘larigacha"},{ar:"الْعَابِقَةِ بِالْعِطْرِ",uz:"xushbo‘y hidlarga to‘la"}],full_uz:"Arslonlar hovlisidan xushbo‘y hidlarga to‘la jannat bog‘larigacha.",note:"عَابِقٌ — kuchli ifor taratuvchi."},
{num:216,time:"00:19:23,759 --> 00:19:27,940",arabic:"كُلُّ زَاوِيَةٍ فِي الْحَمْرَاءِ قَصِيدَةٌ حَيَّةٌ",segs:[{ar:"كُلُّ زَاوِيَةٍ فِي الْحَمْرَاءِ",uz:"Alhambradagi har bir burchak"},{ar:"قَصِيدَةٌ حَيَّةٌ",uz:"tirik she’r"}],full_uz:"Alhambradagi har bir burchak tirik she’rdir.",note:null},
{num:217,time:"00:19:27,940 --> 00:19:30,859",arabic:"كُتِبَتْ بِالْحَجَرِ وَالْمَاءِ وَالنُّورِ",segs:null,full_uz:"Tosh, suv va nur bilan yozilgan.",note:null},
{num:218,time:"00:19:30,859 --> 00:19:33,339",arabic:"وَنُقِشَتْ بِحُرُوفٍ تَقُولُ",segs:[{ar:"وَنُقِشَتْ بِحُرُوفٍ",uz:"harflar bilan naqshlangan"},{ar:"تَقُولُ",uz:"ular aytadi"}],full_uz:"Unda shunday deyilgan harflar naqshlangan.",note:"نُقِشَتْ — naqshlandi, o‘yib yozildi."},
{num:219,time:"00:19:33,339 --> 00:19:37,460",arabic:"سُبْحَانَ مَنْ أَبْدَعَ فَأَحْسَنَ الْخَلْقَ وَالتَّصْوِيرَ",segs:[{ar:"سُبْحَانَ مَنْ أَبْدَعَ",uz:"ajoyib yaratgan Zot pokdir"},{ar:"فَأَحْسَنَ الْخَلْقَ وَالتَّصْوِيرَ",uz:"va yaratish hamda tasvirlashni go‘zal qilgan"}],full_uz:"Ajoyib yaratgan, yaratish va tasvirlashni go‘zal qilgan Zot pokdir.",note:"التَّصْوِيرُ — shakl berish, tasvirlash."},
{num:220,time:"00:19:44,000 --> 00:19:51,599",arabic:"وَفِي قَلْبِ الْمُحِيطِ الْهَادِئِ الْجَنُوبِيِّ",segs:null,full_uz:"Janubiy Tinch okeanining bag‘rida.",note:null},
{num:221,time:"00:19:51,599 --> 00:19:56,960",arabic:"تَتَجَلَّى جَزِيرَةٌ كَأَنَّهَا وُلِدَتْ مِنْ حُلْمٍ إِلَهِيٍّ",segs:[{ar:"تَتَجَلَّى جَزِيرَةٌ",uz:"bir orol namoyon bo‘ladi"},{ar:"كَأَنَّهَا وُلِدَتْ",uz:"go‘yo tug‘ilgandek"},{ar:"مِنْ حُلْمٍ إِلَهِيٍّ",uz:"ilohiy tushdan"}],full_uz:"Go‘yo ilohiy tushdan tug‘ilgandek bir orol namoyon bo‘ladi.",note:null},
{num:222,time:"00:19:56,960 --> 00:19:59,779",arabic:"إِنَّهَا بُورَا بُورَا",segs:null,full_uz:"Bu Bora Bora.",note:null},
{num:223,time:"00:19:59,779 --> 00:20:05,960",arabic:"جَزِيرَةٌ تُحِيطُ بِهَا بُحَيْرَةٌ فِيرُوزِيَّةٌ",segs:[{ar:"جَزِيرَةٌ",uz:"bir orol"},{ar:"تُحِيطُ بِهَا بُحَيْرَةٌ فِيرُوزِيَّةٌ",uz:"uni feruza rangli laguna o‘rab turadi"}],full_uz:"Uni feruza rangli laguna o‘rab turadigan orol.",note:"بُحَيْرَةٌ فِيرُوزِيَّةٌ — feruza rangli laguna."},
{num:224,time:"00:20:05,960 --> 00:20:10,039",arabic:"تَتَنَاثَرُ فَوْقَهَا أَكْوَاخٌ خَشَبِيَّةٌ عَائِمَةٌ",segs:[{ar:"تَتَنَاثَرُ فَوْقَهَا",uz:"uning ustiga sochilgan"},{ar:"أَكْوَاخٌ خَشَبِيَّةٌ عَائِمَةٌ",uz:"suzib yuruvchi yog‘och kulbalar"}],full_uz:"Uning ustida suzib yuruvchi yog‘och kulbalar sochilib yotadi.",note:"تَتَنَاثَرُ — sochilib yotmoq."},
{num:225,time:"00:20:10,039 --> 00:20:14,039",arabic:"وَتَحْتَضِنُهَا حَدَائِقُ الْمَرْجَانِ الْمُلَوَّنَةُ",segs:[{ar:"وَتَحْتَضِنُهَا",uz:"va uni bag‘riga oladi"},{ar:"حَدَائِقُ الْمَرْجَانِ الْمُلَوَّنَةُ",uz:"rang-barang marjon bog‘lari"}],full_uz:"Va uni rang-barang marjon bog‘lari bag‘riga oladi.",note:"تَحْتَضِنُ — bag‘riga olmoq, o‘rab turmoq."},
{num:226,time:"00:20:14,039 --> 00:20:21,440",arabic:"فِي مَرْكَزِهَا يَرْتَفِعُ جَبَلُ أُوتِيمَانُو",segs:[{ar:"فِي مَرْكَزِهَا",uz:"uning markazida"},{ar:"يَرْتَفِعُ جَبَلُ أُوتِيمَانُو",uz:"Otemanu tog‘i ko‘tariladi"}],full_uz:"Uning markazida Otemanu tog‘i ko‘tarilib turadi.",note:null},
{num:227,time:"00:20:21,440 --> 00:20:24,259",arabic:"قِمَّةٌ بُرْكَانِيَّةٌ مَهِيبَةٌ",segs:null,full_uz:"Haybatli vulqon cho‘qqisi.",note:"مَهِيبٌ — haybatli, salobatli."},
{num:228,time:"00:20:24,259 --> 00:20:28,000",arabic:"تُشْرِفُ عَلَى مِيَاهٍ تَتَبَدَّلُ أَلْوَانُهَا",segs:[{ar:"تُشْرِفُ عَلَى مِيَاهٍ",uz:"suvlarga qarab turadi"},{ar:"تَتَبَدَّلُ أَلْوَانُهَا",uz:"ularning ranglari o‘zgarib turadi"}],full_uz:"U ranglari o‘zgarib turadigan suvlarga qarab turadi.",note:"أَشْرَفَ عَلَى — balanddan qarab turmoq."},
{num:229,time:"00:20:28,000 --> 00:20:31,180",arabic:"بَيْنَ الزُّرْقَةِ وَالتُّرْكْوَازِ وَالْفِضَّةِ",segs:null,full_uz:"Moviy, feruza va kumush ranglar orasida.",note:"التُّرْكْوَازُ — feruza."},
{num:230,time:"00:20:31,180 --> 00:20:35,220",arabic:"كَأَنَّ الْبَحْرَ هُنَاكَ لَوْحَةٌ لَا تَنْتَهِي",segs:[{ar:"كَأَنَّ الْبَحْرَ هُنَاكَ",uz:"go‘yo u yerdagi dengiz"},{ar:"لَوْحَةٌ لَا تَنْتَهِي",uz:"tugamaydigan bir manzara"}],full_uz:"Go‘yo u yerdagi dengiz tugamaydigan bir manzaradek.",note:null},
{num:231,time:"00:20:40,039 --> 00:20:48,579",arabic:"تَحْتَ السَّطْحِ أَسْمَاكٌ زَاهِيَةٌ وَشَفَانِينُ رَشِيقَةٌ تَسْبَحُ فِي شِعَابٍ تُشْبِهُ أَقْوَاسَ قُزَحٍ تَحْتَ الْمَاءِ",segs:[{ar:"تَحْتَ السَّطْحِ",uz:"suv yuzasi ostida"},{ar:"أَسْمَاكٌ زَاهِيَةٌ وَشَفَانِينُ رَشِيقَةٌ",uz:"rang-barang baliqlar va nafis skat baliqlari"},{ar:"تَسْبَحُ فِي شِعَابٍ",uz:"riflar orasida suzadi"},{ar:"تُشْبِهُ أَقْوَاسَ قُزَحٍ تَحْتَ الْمَاءِ",uz:"suv ostidagi kamalaklarga o‘xshaydigan"}],full_uz:"Suv yuzasi ostida rang-barang baliqlar va nafis skat baliqlari suv ostidagi kamalaklarga o‘xshagan riflar orasida suzadi.",note:"شَفَنِينٌ — skat baliq."},
{num:232,time:"00:20:48,579 --> 00:21:03,899",arabic:"سَوَاءٌ كُنْتَ تُبْحِرُ فِي الْبُحَيْرَةِ أَوْ تَسْبَحُ بَيْنَ أَسْمَاكِ الْقِرْشِ الْوَدِيعَةِ أَوْ تُرَاقِبُ الْغُرُوبَ مِنْ شُرْفَةِ كُوخِكَ",segs:[{ar:"سَوَاءٌ كُنْتَ تُبْحِرُ فِي الْبُحَيْرَةِ",uz:"lagunada suzayotgan bo‘lsangiz ham"},{ar:"أَوْ تَسْبَحُ بَيْنَ أَسْمَاكِ الْقِرْشِ الْوَدِيعَةِ",uz:"yoki beozor akulalar orasida suzayotgan bo‘lsangiz"},{ar:"أَوْ تُرَاقِبُ الْغُرُوبَ",uz:"yoki quyosh botishini tomosha qilsangiz"},{ar:"مِنْ شُرْفَةِ كُوخِكَ",uz:"kulbangiz ayvonidan"}],full_uz:"Lagunada suzayotgan bo‘lsangiz ham, beozor akulalar orasida suzsangiz ham yoki kulbangiz ayvonidan quyosh botishini tomosha qilsangiz ham.",note:"وَدِيعٌ — beozor, muloyim."},
{num:233,time:"00:21:03,899 --> 00:21:08,440",arabic:"فَكُلُّ لَحْظَةٍ فِي بُورَا بُورَا تُشْبِهُ الْحُلْمَ",segs:[{ar:"فَكُلُّ لَحْظَةٍ فِي بُورَا بُورَا",uz:"Bora Boradagi har bir lahza"},{ar:"تُشْبِهُ الْحُلْمَ",uz:"tushga o‘xshaydi"}],full_uz:"Bora Boradagi har bir lahza tushga o‘xshaydi.",note:null},
{num:234,time:"00:21:10,039 --> 00:21:16,500",arabic:"هُنَا يَتَبَاطَأُ الزَّمَنُ",segs:null,full_uz:"Bu yerda vaqt sekinlashadi.",note:"يَتَبَاطَأُ — sekinlashmoq."},
{num:235,time:"00:21:16,500 --> 00:21:19,940",arabic:"يَهْمِسُ الْبَحْرُ بِأُغْنِيَةٍ نَاعِمَةٍ",segs:[{ar:"يَهْمِسُ الْبَحْرُ",uz:"dengiz shivirlaydi"},{ar:"بِأُغْنِيَةٍ نَاعِمَةٍ",uz:"mayin qo‘shiq bilan"}],full_uz:"Dengiz mayin qo‘shiq bilan shivirlaydi.",note:"أُغْنِيَةٌ نَاعِمَةٌ — mayin qo‘shiq."},
{num:236,time:"00:21:19,940 --> 00:21:23,619",arabic:"وَيَتَحَوَّلُ الْهُدُوءُ إِلَى إِحْسَاسٍ مَلْمُوسٍ",segs:[{ar:"وَيَتَحَوَّلُ الْهُدُوءُ",uz:"va sokinlik aylanadi"},{ar:"إِلَى إِحْسَاسٍ مَلْمُوسٍ",uz:"seziladigan tuyg‘uga"}],full_uz:"Va sokinlik seziladigan tuyg‘uga aylanadi.",note:"مَلْمُوسٌ — seziladigan, aniq."},
{num:237,time:"00:21:23,619 --> 00:21:27,240",arabic:"كَأَنَّ الْجَنَّةَ وَجَدَتْ عُنْوَانًا عَلَى الْأَرْضِ",segs:[{ar:"كَأَنَّ الْجَنَّةَ",uz:"go‘yo jannat"},{ar:"وَجَدَتْ عُنْوَانًا عَلَى الْأَرْضِ",uz:"yerda manzil topgandek"}],full_uz:"Go‘yo jannat yerda o‘z manzilini topgandek.",note:"عُنْوَانٌ — manzil, adres."},
{num:238,time:"00:21:27,240 --> 00:21:39,119",arabic:"مَحَطَّتُنَا التَّالِيَةُ",segs:null,full_uz:"Keyingi manzilimiz.",note:null},
{num:239,time:"00:21:39,119 --> 00:21:43,399",arabic:"إِلَى أَعْمَاقِ أَدْغَالِ شِبْهِ جَزِيرَةِ يُوكَاتَانَ",segs:[{ar:"إِلَى أَعْمَاقِ أَدْغَالِ",uz:"o‘rmonlarning ichkarisiga"},{ar:"شِبْهِ جَزِيرَةِ يُوكَاتَانَ",uz:"Yukatan yarimorolining"}],full_uz:"Yukatan yarimorolining o‘rmonlari ichkarisiga.",note:"أَدْغَالٌ — zich o‘rmon, changalzor."},
{num:240,time:"00:21:43,399 --> 00:21:50,179",arabic:"حَيْثُ شَيَّدَ شَعْبُ الْمَايَا مَدِينَةً تُعَدُّ مِنْ أَعْجَبِ مَا عَرَفَهُ التَّارِيخُ الْإِنْسَانِيُّ",segs:[{ar:"حَيْثُ شَيَّدَ شَعْبُ الْمَايَا مَدِينَةً",uz:"u yerda mayyalar xalqi bir shahar qurgan"},{ar:"تُعَدُّ مِنْ أَعْجَبِ مَا عَرَفَهُ",uz:"u eng hayratlanarli narsalardan sanaladi"},{ar:"التَّارِيخُ الْإِنْسَانِيُّ",uz:"insoniyat tarixida ma’lum bo‘lgan"}],full_uz:"U yerda mayyalar xalqi insoniyat tarixida ma’lum bo‘lgan eng hayratlanarli shaharlardan birini qurgan.",note:"شَيَّدَ — barpo etmoq, qurmoq."},
{num:241,time:"00:21:50,179 --> 00:22:00,599",arabic:"كَانَتْ يَوْمًا مَرْكَزًا لِلْقُوَّةِ وَالْعِلْمِ وَالْعِبَادَةِ",segs:[{ar:"كَانَتْ يَوْمًا",uz:"bir vaqtlar edi"},{ar:"مَرْكَزًا لِلْقُوَّةِ وَالْعِلْمِ وَالْعِبَادَةِ",uz:"kuch, ilm va ibodat markazi"}],full_uz:"Bir vaqtlar u kuch, ilm va ibodat markazi bo‘lgan.",note:null},
{num:242,time:"00:22:00,599 --> 00:22:05,279",arabic:"وَمَا تَزَالُ الْيَوْمَ شَاهِدَةً عَلَى حَضَارَةٍ تَجَاوَزَتْ زَمَنَهَا",segs:[{ar:"وَمَا تَزَالُ الْيَوْمَ شَاهِدَةً",uz:"va bugun ham guvoh bo‘lib turibdi"},{ar:"عَلَى حَضَارَةٍ تَجَاوَزَتْ زَمَنَهَا",uz:"o‘z zamonidan oshib ketgan sivilizatsiyaga"}],full_uz:"Va bugun ham o‘z zamonidan oshib ketgan sivilizatsiyaga guvoh bo‘lib turibdi.",note:"تَجَاوَزَ — oshib o‘tmoq, chegaradan chiqmoq."},
{num:243,time:"00:22:05,279 --> 00:22:07,799",arabic:"حَضَارَةٌ أَلْهَمَهَا اللَّهُ",segs:null,full_uz:"Alloh ilhom bergan sivilizatsiya.",note:"أَلْهَمَ — ilhom bermoq."},
{num:244,time:"00:22:07,799 --> 00:22:10,899",arabic:"فَجَمَعَتْ بَيْنَ الْفِكْرِ وَالْفَنِّ وَالدِّقَّةِ",segs:[{ar:"فَجَمَعَتْ بَيْنَ الْفِكْرِ وَالْفَنِّ",uz:"fikr va san’atni jamladi"},{ar:"وَالدِّقَّةِ",uz:"va aniqlikni"}],full_uz:"U fikr, san’at va aniqlikni jamlagan.",note:null},
{num:245,time:"00:22:10,899 --> 00:22:15,099",arabic:"الَّتِي تَرْوِي قِصَّةَ الْإِنْسَانِ الْبَاحِثِ عَنِ النُّورِ",segs:[{ar:"الَّتِي تَرْوِي قِصَّةَ الْإِنْسَانِ",uz:"inson haqida hikoya qiladigan"},{ar:"الْبَاحِثِ عَنِ النُّورِ",uz:"nurni izlovchi"}],full_uz:"Nurni izlovchi inson haqida hikoya qiladigan.",note:null},
{num:246,time:"00:22:15,099 --> 00:22:24,700",arabic:"فِي قَلْبِ الْمَدِينَةِ يَقِفُ الْهَرَمُ الْعَظِيمُ",segs:[{ar:"فِي قَلْبِ الْمَدِينَةِ",uz:"shahar markazida"},{ar:"يَقِفُ الْهَرَمُ الْعَظِيمُ",uz:"Buyuk piramida turadi"}],full_uz:"Shahar markazida Buyuk piramida turadi.",note:null},
{num:247,time:"00:22:24,700 --> 00:22:26,980",arabic:"مَعْبَدُ كُوكُولْكَانَ",segs:null,full_uz:"Kukulkan ibodatxonasi.",note:null},
{num:248,time:"00:22:26,980 --> 00:22:30,579",arabic:"هَرَمٌ هِنْدَسَتُهُ مِثَالِيَّةٌ",segs:null,full_uz:"Me’morchiligi mukammal piramida.",note:"مِثَالِيٌّ — ideal, mukammal."},
{num:249,time:"00:22:30,579 --> 00:22:32,879",arabic:"يُحَاكِي حَرَكَةَ النُّجُومِ",segs:null,full_uz:"Yulduzlar harakatiga taqlid qiladi.",note:"حَاكَى — taqlid qilmoq, o‘xshatmoq."},
{num:250,time:"00:22:32,880 --> 00:22:37,860",arabic:"وَيَسْتَقْبِلُ الشَّمْسَ فِي فَصْلَيِ الِاعْتِدَالِ بِدِقَّةٍ مُدْهِشَةٍ",segs:[{ar:"وَيَسْتَقْبِلُ الشَّمْسَ",uz:"quyoshni qarshi oladi"},{ar:"فِي فَصْلَيِ الِاعْتِدَالِ",uz:"tengkunlik ikki faslida"},{ar:"بِدِقَّةٍ مُدْهِشَةٍ",uz:"hayratlanarli aniqlik bilan"}],full_uz:"Tengkunlik davrlarida quyoshni hayratlanarli aniqlik bilan qarshi oladi.",note:"الِاعْتِدَالُ — tengkunlik."},
{num:251,time:"00:22:37,860 --> 00:22:42,860",arabic:"حَتَّى يُخَيَّلَ لِلنَّاظِرِ أَنَّ ثُعْبَانًا مِنْ نُورٍ يَنْسَابُ عَلَى دَرَجَاتِهِ",segs:[{ar:"حَتَّى يُخَيَّلَ لِلنَّاظِرِ",uz:"hatto tomoshabinga shunday tuyuladiki"},{ar:"أَنَّ ثُعْبَانًا مِنْ نُورٍ",uz:"nurdan ilon"},{ar:"يَنْسَابُ عَلَى دَرَجَاتِهِ",uz:"uning zinapoyalari bo‘ylab sirg‘aladi"}],full_uz:"Hatto tomoshabinga uning zinapoyalari bo‘ylab nurdan bir ilon sirg‘alayotgandek tuyuladi.",note:"يَنْسَابُ — sirg‘almoq, silliq oqmoq."},
{num:252,time:"00:22:42,860 --> 00:22:48,380",arabic:"شَهَادَةٌ عَلَى عَبْقَرِيَّةٍ أَلْهَمَهَا الْخَالِقُ لِمَنْ شَاءَ مِنْ عِبَادِهِ",segs:[{ar:"شَهَادَةٌ عَلَى عَبْقَرِيَّةٍ",uz:"dahoning guvohi"},{ar:"أَلْهَمَهَا الْخَالِقُ",uz:"uni Yaratuvchi ilhomlantirgan"},{ar:"لِمَنْ شَاءَ مِنْ عِبَادِهِ",uz:"bandalaridan O‘zi xohlagan kishiga"}],full_uz:"Bu Yaratuvchi O‘z bandalaridan xohlagan kishiga ilhom bergan dahoning guvohidir.",note:"عَبْقَرِيَّةٌ — daholik, zukkolik."},
{num:253,time:"00:22:48,380 --> 00:22:57,380",arabic:"حَوْلَ الْمَعْبَدِ تَنْتَشِرُ الْآبَارُ الْمُقَدَّسَةُ",segs:[{ar:"حَوْلَ الْمَعْبَدِ",uz:"ibodatxona atrofida"},{ar:"تَنْتَشِرُ الْآبَارُ الْمُقَدَّسَةُ",uz:"muqaddas quduqlar tarqalgan"}],full_uz:"Ibodatxona atrofida muqaddas quduqlar joylashgan.",note:"تَنْتَشِرُ — tarqalmoq, joylashmoq."},
{num:254,time:"00:22:57,380 --> 00:23:02,100",arabic:"وَسَاحَاتُ اللَّعِبِ وَالْمَعَابِدُ الْمُزَخْرَفَةُ بِالنُّقُوشِ",segs:[{ar:"وَسَاحَاتُ اللَّعِبِ",uz:"o‘yin maydonlari"},{ar:"وَالْمَعَابِدُ الْمُزَخْرَفَةُ بِالنُّقُوشِ",uz:"naqshlar bilan bezatilgan ibodatxonalar"}],full_uz:"Shuningdek, o‘yin maydonlari va naqshlar bilan bezatilgan ibodatxonalar bor.",note:"مُزَخْرَفٌ — bezatilgan, naqshlangan."},
{num:255,time:"00:23:02,099 --> 00:23:10,419",arabic:"كُلُّ حَجَرٍ فِيهَا يَهْمِسُ بِسِرٍّ قَدِيمٍ عَنْ أُمَّةٍ عَرَفَتْ أَنَّ لِلْكَوْنِ نِظَامًا",segs:[{ar:"كُلُّ حَجَرٍ فِيهَا",uz:"undagi har bir tosh"},{ar:"يَهْمِسُ بِسِرٍّ قَدِيمٍ",uz:"qadimiy bir sirni shivirlaydi"},{ar:"عَنْ أُمَّةٍ عَرَفَتْ",uz:"bir xalq haqida, u bilgan"},{ar:"أَنَّ لِلْكَوْنِ نِظَامًا",uz:"koinotning bir tizimi borligini"}],full_uz:"Undagi har bir tosh koinotning bir tizimi borligini anglagan bir xalq haqidagi qadimiy sirni shivirlaydi.",note:"أُمَّةٌ — xalq, ummat."},
{num:256,time:"00:23:10,419 --> 00:23:15,699",arabic:"وَأَنَّ خَلْفَ كُلِّ نَجْمٍ فِي السَّمَاءِ خَالِقًا عَلِيمًا لَا يَغِيبُ",segs:[{ar:"وَأَنَّ خَلْفَ كُلِّ نَجْمٍ فِي السَّمَاءِ",uz:"va osmondagi har bir yulduz ortida"},{ar:"خَالِقًا عَلِيمًا",uz:"biluvchi Yaratuvchi borligini"},{ar:"لَا يَغِيبُ",uz:"g‘oyib bo‘lmaydigan"}],full_uz:"Va osmondagi har bir yulduz ortida g‘oyib bo‘lmaydigan Biluvchi Yaratuvchi borligini.",note:"عَلِيمٌ — biluvchi, har narsani biladigan."},
{num:257,time:"00:23:15,699 --> 00:23:31,319",arabic:"نَرْحَلُ إِلَى الْجَنُوبِ الْأُرْدُنِّيِّ حَيْثُ تَحْتَضِنُ الصَّحْرَاءُ سِرًّا وَرْدِيًّا بَيْنَ الْجِبَالِ الصَّخْرِيَّةِ",segs:[{ar:"نَرْحَلُ إِلَى الْجَنُوبِ الْأُرْدُنِّيِّ",uz:"Iordaniyaning janubiga yo‘l olamiz"},{ar:"حَيْثُ تَحْتَضِنُ الصَّحْرَاءُ",uz:"u yerda sahro bag‘riga oladi"},{ar:"سِرًّا وَرْدِيًّا",uz:"pushti rangli bir sirni"},{ar:"بَيْنَ الْجِبَالِ الصَّخْرِيَّةِ",uz:"qoyali tog‘lar orasida"}],full_uz:"Iordaniyaning janubiga yo‘l olamiz, u yerda sahro qoyali tog‘lar orasida pushti rangli bir sirni bag‘rida saqlaydi.",note:"وَرْدِيٌّ — pushti rangli."},
{num:258,time:"00:23:31,319 --> 00:23:36,000",arabic:"إِنَّهَا الْبَتْرَاءُ دُرَّةُ الْعُصُورِ الْقَدِيمَةِ",segs:[{ar:"إِنَّهَا الْبَتْرَاءُ",uz:"bu Petra"},{ar:"دُرَّةُ الْعُصُورِ الْقَدِيمَةِ",uz:"qadimgi davrlarning durdonasi"}],full_uz:"Bu qadimgi davrlarning durdonasi Petra.",note:"دُرَّةٌ — dur, gavhar, durdona."},
{num:259,time:"00:23:36,000 --> 00:23:41,439",arabic:"مَدِينَةٌ نُحِتَتْ فِي الصَّخْرِ وَنُسِيَتْ فِي الزَّمَنِ",segs:[{ar:"مَدِينَةٌ نُحِتَتْ فِي الصَّخْرِ",uz:"qoyaga o‘yib qurilgan shahar"},{ar:"وَنُسِيَتْ فِي الزَّمَنِ",uz:"va zamon ichida unutilgan"}],full_uz:"Qoyaga o‘yib qurilgan va zamon ichida unutilgan shahar.",note:"نُحِتَ — o‘yib yaratildi."},
{num:260,time:"00:23:41,439 --> 00:23:46,039",arabic:"ثُمَّ عَادَتْ لِتُدْهِشَ كُلَّ مَنْ يَرَاهَا",segs:[{ar:"ثُمَّ عَادَتْ",uz:"so‘ng qaytdi"},{ar:"لِتُدْهِشَ كُلَّ مَنْ يَرَاهَا",uz:"uni ko‘rgan har bir kishini hayratga solish uchun"}],full_uz:"So‘ng uni ko‘rgan har bir kishini hayratga solish uchun qayta namoyon bo‘ldi.",note:"أَدْهَشَ — hayratga solmoq."},
{num:261,time:"00:23:46,039 --> 00:23:53,779",arabic:"حِينَ تَسِيرُ فِي الْمَمَرِّ الضَّيِّقِ الْمَعْرُوفِ بِالسِّيقِ",segs:[{ar:"حِينَ تَسِيرُ فِي الْمَمَرِّ الضَّيِّقِ",uz:"tor yo‘lakdan yurganingizda"},{ar:"الْمَعْرُوفِ بِالسِّيقِ",uz:"Siq deb ataladigan"}],full_uz:"Siq deb ataladigan tor yo‘lakdan yurganingizda.",note:"السِّيقُ — Siq, Petradagi tor darali yo‘lak."},
{num:262,time:"00:23:53,779 --> 00:23:58,779",arabic:"تَعْلُو الْجُدْرَانُ مِنْ حَوْلِكَ كَأَنَّهَا جُدْرَانُ الزَّمَنِ ذَاتِهِ",segs:[{ar:"تَعْلُو الْجُدْرَانُ مِنْ حَوْلِكَ",uz:"atrofingizdagi devorlar baland ko‘tariladi"},{ar:"كَأَنَّهَا جُدْرَانُ الزَّمَنِ ذَاتِهِ",uz:"go‘yo zamonning o‘z devorlaridek"}],full_uz:"Atrofingizdagi devorlar go‘yo zamonning o‘z devorlaridek baland ko‘tariladi.",note:null},
{num:263,time:"00:23:58,779 --> 00:24:07,200",arabic:"تَتَلَأْلَأُ بِدَرَجَاتِ الْأَحْمَرِ وَالذَّهَبِ حَتَّى تَنْفَتِحَ فَجْأَةً لِتَكْشِفَ عَنِ الْمَشْهَدِ الْمَهِيبِ",segs:[{ar:"تَتَلَأْلَأُ بِدَرَجَاتِ الْأَحْمَرِ وَالذَّهَبِ",uz:"qizil va oltin tuslarda yaltiraydi"},{ar:"حَتَّى تَنْفَتِحَ فَجْأَةً",uz:"to‘satdan ochilguncha"},{ar:"لِتَكْشِفَ عَنِ الْمَشْهَدِ الْمَهِيبِ",uz:"haybatli manzarani ochib berish uchun"}],full_uz:"Ular qizil va oltin tuslarda yaltirab, to‘satdan ochilib haybatli manzarani namoyon qiladi.",note:"دَرَجَاتٌ — tuslar, darajalar."},
{num:264,time:"00:24:07,200 --> 00:24:19,879",arabic:"الْخَزْنَةُ أَيْقُونَةُ الْبَتْرَاءِ مَنْحُوتَةٌ بِإِتْقَانٍ مُذْهِلٍ مُنْذُ أَكْثَرَ مِنْ أَلْفَيْ عَامٍ",segs:[{ar:"الْخَزْنَةُ أَيْقُونَةُ الْبَتْرَاءِ",uz:"Xazna — Petraning ramzi"},{ar:"مَنْحُوتَةٌ بِإِتْقَانٍ مُذْهِلٍ",uz:"hayratlanarli mukammallik bilan o‘yilgan"},{ar:"مُنْذُ أَكْثَرَ مِنْ أَلْفَيْ عَامٍ",uz:"ikki ming yildan ortiq vaqt oldin"}],full_uz:"Petraning ramzi bo‘lgan Xazna ikki ming yildan ortiq vaqt oldin hayratlanarli mukammallik bilan o‘yilgan.",note:"أَيْقُونَةٌ — timsol, ramz."},
{num:265,time:"00:24:19,879 --> 00:24:27,680",arabic:"تُظْهِرُ كَيْفَ أَوْدَعَ اللَّهُ فِي الْإِنْسَانِ قُدْرَةً عَلَى الْإِبْدَاعِ حِينَ يَمَسُّ قَلْبَهُ نُورُ الْفَهْمِ",segs:[{ar:"تُظْهِرُ كَيْفَ أَوْدَعَ اللَّهُ فِي الْإِنْسَانِ",uz:"u Alloh insonga qanday joylaganini ko‘rsatadi"},{ar:"قُدْرَةً عَلَى الْإِبْدَاعِ",uz:"ijod qilish qobiliyatini"},{ar:"حِينَ يَمَسُّ قَلْبَهُ نُورُ الْفَهْمِ",uz:"uning qalbiga anglash nuri tekkanda"}],full_uz:"U inson qalbiga anglash nuri tekkanda Alloh unga ijod qilish qobiliyatini qanday joylaganini ko‘rsatadi.",note:"الْإِبْدَاعُ — ijod, yangicha yaratish."},
{num:266,time:"00:24:27,680 --> 00:24:35,140",arabic:"لَكِنَّ الْخَزْنَةَ لَيْسَتْ سِوَى الْبِدَايَةِ",segs:null,full_uz:"Ammo Xazna faqat boshlanishidir.",note:"لَيْسَ سِوَى — faqat ...dir."},
{num:267,time:"00:24:35,140 --> 00:24:39,600",arabic:"فَفِي أَعْمَاقِ الْجِبَالِ مَعَابِدُ وَمَقَابِرُ وَمَسَارِحُ",segs:null,full_uz:"Chunki tog‘larning ichkarisida ibodatxonalar, maqbaralar va teat rlar bor.",note:"مَسْرَحٌ — teatr."},
{num:268,time:"00:24:39,600 --> 00:24:43,640",arabic:"كَأَنَّ الْمَدِينَةَ كُلَّهَا تُسَبِّحُ بِاسْمِ رَبِّهَا",segs:[{ar:"كَأَنَّ الْمَدِينَةَ كُلَّهَا",uz:"go‘yo butun shahar"},{ar:"تُسَبِّحُ بِاسْمِ رَبِّهَا",uz:"o‘z Robbisining nomi bilan tasbeh aytadi"}],full_uz:"Go‘yo butun shahar o‘z Robbisining nomi bilan tasbeh aytayotgandek.",note:null},
{num:269,time:"00:24:43,640 --> 00:24:48,200",arabic:"شَهَادَةٌ عَلَى أَنَّ الْجَمَالَ حِينَ يَسْتَلْهِمُ مِنَ الْأَرْضِ",segs:[{ar:"شَهَادَةٌ عَلَى أَنَّ الْجَمَالَ",uz:"go‘zallikning guvohi"},{ar:"حِينَ يَسْتَلْهِمُ مِنَ الْأَرْضِ",uz:"yerdan ilhom olganida"}],full_uz:"Go‘zallik yerdan ilhom olganidagi holatning guvohi.",note:"اسْتَلْهَمَ — ilhom olmoq."},
{num:270,time:"00:24:48,200 --> 00:24:51,420",arabic:"يُصْبِحُ عِبَادَةً مِنْ نَوْعٍ آخَرَ",segs:[{ar:"يُصْبِحُ عِبَادَةً",uz:"ibodatga aylanadi"},{ar:"مِنْ نَوْعٍ آخَرَ",uz:"boshqa bir turdagi"}],full_uz:"Boshqa turdagi ibodatga aylanadi.",note:null},
{num:271,time:"00:24:57,680 --> 00:25:06,340",arabic:"نَنْتَقِلُ إِلَى جِبَالِ الشَّرْقِ الْأَقْصَى حَيْثُ يَمْتَدُّ سُورُ الصِّينِ الْعَظِيمُ",segs:[{ar:"نَنْتَقِلُ إِلَى جِبَالِ الشَّرْقِ الْأَقْصَى",uz:"Uzoq Sharq tog‘lariga o‘tamiz"},{ar:"حَيْثُ يَمْتَدُّ سُورُ الصِّينِ الْعَظِيمُ",uz:"u yerda Buyuk Xitoy devori cho‘zilib yotadi"}],full_uz:"Uzoq Sharq tog‘lariga o‘tamiz, u yerda Buyuk Xitoy devori cho‘zilib yotadi.",note:null},
{num:272,time:"00:25:06,340 --> 00:25:13,980",arabic:"تُحْفَةُ الصَّبْرِ وَالْعَزِيمَةِ تَرْبِطُ التَّارِيخَ بِالْحَاضِرِ عَبْرَ أَكْثَرَ مِنْ أَلْفِ عَامٍ",segs:[{ar:"تُحْفَةُ الصَّبْرِ وَالْعَزِيمَةِ",uz:"sabr va qat’iyat durdonasi"},{ar:"تَرْبِطُ التَّارِيخَ بِالْحَاضِرِ",uz:"tarixni hozirgi zamon bilan bog‘laydi"},{ar:"عَبْرَ أَكْثَرَ مِنْ أَلْفِ عَامٍ",uz:"ming yildan ortiq vaqt davomida"}],full_uz:"Sabr va qat’iyat durdonasi tarixni ming yildan ortiq vaqt davomida hozirgi zamon bilan bog‘laydi.",note:"الْعَزِيمَةُ — qat’iyat, iroda."},
{num:273,time:"00:25:18,980 --> 00:25:22,920",arabic:"يَمْتَدُّ السُّورُ عَلَى مَدَى ثَلَاثَةَ عَشَرَ أَلْفَ مِيلٍ",segs:[{ar:"يَمْتَدُّ السُّورُ",uz:"devor cho‘ziladi"},{ar:"عَلَى مَدَى ثَلَاثَةَ عَشَرَ أَلْفَ مِيلٍ",uz:"o‘n uch ming mil masofa bo‘ylab"}],full_uz:"Devor o‘n uch ming mil masofa bo‘ylab cho‘ziladi.",note:null},
{num:274,time:"00:25:22,920 --> 00:25:25,900",arabic:"يَتَلَوَّى فَوْقَ الْجِبَالِ وَالْوِدْيَانِ",segs:[{ar:"يَتَلَوَّى فَوْقَ الْجِبَالِ",uz:"tog‘lar ustidan egri-bugri cho‘ziladi"},{ar:"وَالْوِدْيَانِ",uz:"va vodiylar"}],full_uz:"U tog‘lar va vodiylar ustidan egri-bugri cho‘zilib boradi.",note:"يَتَلَوَّى — egri-bugri bo‘lib cho‘zilmoq."},
{num:275,time:"00:25:25,900 --> 00:25:30,380",arabic:"كَأَنَّهُ نَهْرٌ مِنْ حَجَرٍ حَفَرَهُ الْإِنْسَانُ بِإِرَادَةٍ",segs:[{ar:"كَأَنَّهُ نَهْرٌ مِنْ حَجَرٍ",uz:"go‘yo toshdan yasalgan daryodek"},{ar:"حَفَرَهُ الْإِنْسَانُ بِإِرَادَةٍ",uz:"inson uni iroda bilan qurgan"}],full_uz:"Go‘yo inson iroda bilan qurgan toshdan yasalgan daryodek.",note:"حَفَرَ — qazimoq, o‘yib yaratmoq."},
{num:276,time:"00:25:30,380 --> 00:25:33,120",arabic:"عَلَّمَهُ اللَّهُ إِيَّاهَا",segs:null,full_uz:"Alloh unga uni o‘rgatgan.",note:"عَلَّمَ — o‘rgatmoq."},
{num:277,time:"00:25:33,120 --> 00:25:39,720",arabic:"بُنِيَ لِيَحْمِيَ الْبِلَادَ مِنَ الْغُزَاةِ",segs:[{ar:"بُنِيَ لِيَحْمِيَ الْبِلَادَ",uz:"mamlakatni himoya qilish uchun qurilgan"},{ar:"مِنَ الْغُزَاةِ",uz:"bosqinchilardan"}],full_uz:"Mamlakatni bosqinchilardan himoya qilish uchun qurilgan.",note:"الْغُزَاةُ — bosqinchilar."},
{num:278,time:"00:25:39,720 --> 00:25:43,640",arabic:"لَكِنَّهُ صَارَ رَمْزًا أَعْظَمَ مِنْ ذَلِكَ بِكَثِيرٍ",segs:[{ar:"لَكِنَّهُ صَارَ رَمْزًا",uz:"ammo u ramzga aylandi"},{ar:"أَعْظَمَ مِنْ ذَلِكَ بِكَثِيرٍ",uz:"bundan ancha ulug‘roq"}],full_uz:"Ammo u bundan ancha ulug‘roq ramzga aylandi.",note:null},
{num:279,time:"00:25:43,640 --> 00:25:48,200",arabic:"رَمْزًا لِوَحْدَةِ الْبَشَرِ حِينَ يَجْتَمِعُونَ عَلَى غَايَةٍ",segs:[{ar:"رَمْزًا لِوَحْدَةِ الْبَشَرِ",uz:"insoniyat birligining ramzi"},{ar:"حِينَ يَجْتَمِعُونَ عَلَى غَايَةٍ",uz:"ular bir maqsad yo‘lida birlashganda"}],full_uz:"Insonlar bir maqsad yo‘lida birlashganlaridagi insoniyat birligining ramzi.",note:"غَايَةٌ — maqsad, niyat."},
{num:280,time:"00:25:48,200 --> 00:25:53,299",arabic:"وَلِقُوَّةِ الْإِصْرَارِ حِينَ تُسَخَّرُ بِإِذْنِ اللَّهِ فِي الْخَيْرِ وَالْعُمْرَانِ",segs:[{ar:"وَلِقُوَّةِ الْإِصْرَارِ",uz:"va qat’iyat kuchining ramzi"},{ar:"حِينَ تُسَخَّرُ بِإِذْنِ اللَّهِ",uz:"u Allohning izni bilan safarbar qilinganda"},{ar:"فِي الْخَيْرِ وَالْعُمْرَانِ",uz:"yaxshilik va bunyodkorlik yo‘lida"}],full_uz:"Va qat’iyat kuchining Allohning izni bilan yaxshilik va bunyodkorlik yo‘lida safarbar qilingandagi ramzidir.",note:"الْإِصْرَارُ — qat’iyat, sobit turish. الْعُمْرَانُ — obodlik, bunyodkorlik."},
{num:281,time:"00:25:53,299 --> 00:26:02,480",arabic:"كُلُّ لَبِنَةٍ فِيهِ تَرْوِي حِكَايَةَ عَامِلٍ صَبَرَ فِي الْبَرْدِ وَالْحَرِّ",segs:[{ar:"كُلُّ لَبِنَةٍ فِيهِ",uz:"undagi har bir g‘isht"},{ar:"تَرْوِي حِكَايَةَ عَامِلٍ",uz:"bir ishchi haqida hikoya qiladi"},{ar:"صَبَرَ فِي الْبَرْدِ وَالْحَرِّ",uz:"u sovuq va issiqda sabr qilgan"}],full_uz:"Undagi har bir g‘isht sovuq va issiqda sabr qilgan bir ishchi haqida hikoya qiladi.",note:"لَبِنَةٌ — g‘isht."},
{num:282,time:"00:26:02,480 --> 00:26:05,299",arabic:"رَجَاءَ أَنْ يَتْرُكَ أَثَرًا بَاقِيًا",segs:[{ar:"رَجَاءَ",uz:"umid qilib"},{ar:"أَنْ يَتْرُكَ أَثَرًا بَاقِيًا",uz:"qoladigan bir iz qoldirishni"}],full_uz:"Qoladigan bir iz qoldirish umidida.",note:"رَجَاءٌ — umid."},
{num:283,time:"00:26:05,299 --> 00:26:10,039",arabic:"فَصَارَ السُّورُ شَاهِدًا عَلَى مَا يَسْتَطِيعُ الْإِنْسَانُ أَنْ يَفْعَلَهُ",segs:[{ar:"فَصَارَ السُّورُ شَاهِدًا",uz:"shunda devor guvohga aylandi"},{ar:"عَلَى مَا يَسْتَطِيعُ الْإِنْسَانُ أَنْ يَفْعَلَهُ",uz:"inson nimalar qila olishiga"}],full_uz:"Shunda devor inson nimalar qila olishiga guvohga aylandi.",note:null},
{num:284,time:"00:26:10,039 --> 00:26:16,120",arabic:"إِذَا أَخْلَصَ السَّعْيَ فِي أَرْضٍ كَتَبَ اللَّهُ فِيهَا الْهِمَّةَ وَالْبَقَاءَ",segs:[{ar:"إِذَا أَخْلَصَ السَّعْيَ",uz:"agar sa’y-harakatini chin dildan qilsa"},{ar:"فِي أَرْضٍ",uz:"bir yurtda"},{ar:"كَتَبَ اللَّهُ فِيهَا الْهِمَّةَ وَالْبَقَاءَ",uz:"Alloh unda g‘ayrat va davomiylikni belgilagan"}],full_uz:"Agar inson sa’y-harakatini chin dildan qilsa, Alloh unda g‘ayrat va davomiylikni belgilagan bir yurtda.",note:"الْهِمَّةُ — g‘ayrat, intilish."},
{num:285,time:"00:26:16,119 --> 00:26:24,000",arabic:"وَأَنْتَ تَسِيرُ فَوْقَ حِجَارَةِ السُّورِ الْعَظِيمِ",segs:[{ar:"وَأَنْتَ تَسِيرُ",uz:"siz yurganingizda"},{ar:"فَوْقَ حِجَارَةِ السُّورِ الْعَظِيمِ",uz:"Buyuk devorning toshlari ustida"}],full_uz:"Siz Buyuk devorning toshlari ustida yurganingizda.",note:null},
{num:286,time:"00:26:24,000 --> 00:26:27,639",arabic:"تَنْظُرُ إِلَى الْأُفُقِ الْمُمْتَدِّ بِلَا نِهَايَةٍ",segs:[{ar:"تَنْظُرُ إِلَى الْأُفُقِ",uz:"ufqqa qaraysiz"},{ar:"الْمُمْتَدِّ بِلَا نِهَايَةٍ",uz:"cheksiz cho‘zilgan"}],full_uz:"Cheksiz cho‘zilgan ufqqa qaraysiz.",note:null},
{num:287,time:"00:26:27,639 --> 00:26:31,419",arabic:"فَتَشْعُرُ بِصِغَرِ نَفْسِكَ أَمَامَ عَظَمَةِ الزَّمَنِ",segs:[{ar:"فَتَشْعُرُ بِصِغَرِ نَفْسِكَ",uz:"shunda o‘zingizning kichikligingizni his qilasiz"},{ar:"أَمَامَ عَظَمَةِ الزَّمَنِ",uz:"zamonning ulug‘vorligi qarshisida"}],full_uz:"Shunda zamonning ulug‘vorligi qarshisida o‘zingizning naqadar kichik ekaningizni his qilasiz.",note:"صِغَرٌ — kichiklik."},
{num:288,time:"00:26:31,419 --> 00:26:37,419",arabic:"لَكِنَّكَ فِي الْوَقْتِ نَفْسِهِ تُدْرِكُ أَنَّكَ جُزْءٌ مِنْ هَذَا الْخَلْقِ الْكَبِيرِ",segs:[{ar:"لَكِنَّكَ فِي الْوَقْتِ نَفْسِهِ",uz:"ammo ayni paytda"},{ar:"تُدْرِكُ أَنَّكَ جُزْءٌ",uz:"o‘zingiz bir qism ekaningizni anglaysiz"},{ar:"مِنْ هَذَا الْخَلْقِ الْكَبِيرِ",uz:"bu ulkan yaratilishning"}],full_uz:"Ammo ayni paytda o‘zingiz bu ulkan yaratilishning bir qismi ekaningizni anglaysiz.",note:null},
{num:289,time:"00:26:37,419 --> 00:26:42,739",arabic:"نُقْطَةٌ فِي لَوْحَةٍ رَسَمَهَا اللَّهُ بِحِكْمَةٍ لَا تَنْتَهِي",segs:[{ar:"نُقْطَةٌ فِي لَوْحَةٍ",uz:"bir manzaradagi bir nuqta"},{ar:"رَسَمَهَا اللَّهُ",uz:"uni Alloh chizgan"},{ar:"بِحِكْمَةٍ لَا تَنْتَهِي",uz:"tugamaydigan hikmat bilan"}],full_uz:"Tugamaydigan hikmat bilan Alloh chizgan manzaradagi bir nuqtasiz.",note:"نُقْطَةٌ — nuqta."},
{num:290,time:"00:26:46,119 --> 00:26:51,339",arabic:"وَمِنْ قَلْبِ آسِيَا إِلَى حَافَّةِ أُورُوبَّا الْجَنُوبِيَّةِ",segs:[{ar:"وَمِنْ قَلْبِ آسِيَا",uz:"Osiyoning yuragidan"},{ar:"إِلَى حَافَّةِ أُورُوبَّا الْجَنُوبِيَّةِ",uz:"Yevropaning janubiy chekkasigacha"}],full_uz:"Osiyoning yuragidan Yevropaning janubiy chekkasigacha.",note:null},
{num:291,time:"00:26:51,339 --> 00:26:56,279",arabic:"نَصِلُ إِلَى حَيْثُ تَلْتَقِي الْجِبَالُ بِالْبَحْرِ فِي عِنَاقٍ مُدْهِشٍ",segs:[{ar:"نَصِلُ إِلَى حَيْثُ تَلْتَقِي الْجِبَالُ بِالْبَحْرِ",uz:"tog‘lar dengiz bilan uchrashadigan joyga yetib boramiz"},{ar:"فِي عِنَاقٍ مُدْهِشٍ",uz:"hayratlanarli quchoqlashuvda"}],full_uz:"Tog‘lar dengiz bilan hayratlanarli tarzda quchoqlashadigan joyga yetib boramiz.",note:"عِنَاقٌ — quchoqlashish."},
{num:292,time:"00:26:56,279 --> 00:26:59,059",arabic:"إِنَّهُ سَاحِلُ أَمَالْفِي",segs:null,full_uz:"Bu Amalfi sohilidir.",note:null},
{num:293,time:"00:26:59,059 --> 00:27:02,019",arabic:"أَمَالْفِي كُوسْتْ فِي إِيطَالْيَا",segs:null,full_uz:"Italiyadagi Amalfi Coast.",note:null},
{num:294,time:"00:27:02,019 --> 00:27:08,779",arabic:"الْمَكَانُ الَّذِي بَدَا وَكَأَنَّ الْجَمَالَ قَرَّرَ أَنْ يُقِيمَ فِيهِ إِلَى الْأَبَدِ",segs:[{ar:"الْمَكَانُ الَّذِي بَدَا",uz:"shunday ko‘ringan joyki"},{ar:"وَكَأَنَّ الْجَمَالَ قَرَّرَ",uz:"go‘yo go‘zallik qaror qilgandek"},{ar:"أَنْ يُقِيمَ فِيهِ إِلَى الْأَبَدِ",uz:"unda abadiy yashashga"}],full_uz:"Go‘yo go‘zallik unda abadiy yashashga qaror qilgandek tuyuladigan joy.",note:"يُقِيمُ — istiqomat qilmoq, yashamoq."},
{num:295,time:"00:27:08,779 --> 00:27:20,819",arabic:"يَمْتَدُّ هَذَا السَّاحِلُ لِمَسَافَةِ خَمْسِينَ كِيلُومِتْرًا مِنَ الْأَلْوَانِ وَالْعُطُورِ وَالدَّهْشَةِ",segs:[{ar:"يَمْتَدُّ هَذَا السَّاحِلُ",uz:"bu sohil cho‘ziladi"},{ar:"لِمَسَافَةِ خَمْسِينَ كِيلُومِتْرًا",uz:"ellik kilometr masofaga"},{ar:"مِنَ الْأَلْوَانِ وَالْعُطُورِ وَالدَّهْشَةِ",uz:"ranglar, iforlar va hayratdan iborat"}],full_uz:"Bu sohil ranglar, iforlar va hayratlarga boy ellik kilometr masofaga cho‘ziladi.",note:"عِطْرٌ — ifor, xushbo‘y hid."},
{num:296,time:"00:27:20,819 --> 00:27:25,079",arabic:"حَيْثُ تَتَدَلَّى الْقُرَى الْمُلَوَّنَةُ مِنْ سُفُوحِ الْجِبَالِ",segs:[{ar:"حَيْثُ تَتَدَلَّى الْقُرَى الْمُلَوَّنَةُ",uz:"rang-barang qishloqlar osilib turadi"},{ar:"مِنْ سُفُوحِ الْجِبَالِ",uz:"tog‘ yonbag‘irlaridan"}],full_uz:"U yerda rang-barang qishloqlar tog‘ yonbag‘irlaridan osilib turadi.",note:"تَتَدَلَّى — osilib turmoq, pastga tushib turmoq."},
{num:297,time:"00:27:25,079 --> 00:27:31,039",arabic:"وَتَنْحَدِرُ بَسَاتِينُ اللَّيْمُونِ نَحْوَ مِيَاهٍ بِلَوْنِ الْفَيْرُوزِ",segs:[{ar:"وَتَنْحَدِرُ بَسَاتِينُ اللَّيْمُونِ",uz:"limon bog‘lari pastga tushadi"},{ar:"نَحْوَ مِيَاهٍ بِلَوْنِ الْفَيْرُوزِ",uz:"feruza rangli suvlar tomon"}],full_uz:"Limon bog‘lari feruza rangli suvlar tomon pastga tushib boradi.",note:"تَنْحَدِرُ — pastga tushmoq, nishab bo‘ylab oqmoq."},
{num:298,time:"00:27:31,039 --> 00:27:40,480",arabic:"الطُّرُقُ تَلْتَفُّ فَوْقَ الْبَحْرِ كَأَنَّهَا خُطُوطٌ رَسَمَهَا فَنَّانٌ",segs:[{ar:"الطُّرُقُ تَلْتَفُّ فَوْقَ الْبَحْرِ",uz:"yo‘llar dengiz ustida burama bo‘lib ketadi"},{ar:"كَأَنَّهَا خُطُوطٌ رَسَمَهَا فَنَّانٌ",uz:"go‘yo rassom chizgan chiziqlardek"}],full_uz:"Yo‘llar go‘yo rassom chizgan chiziqlardek dengiz ustida burama bo‘lib ketadi.",note:"تَلْتَفُّ — burilmoq, o‘ralmoq."},
{num:299,time:"00:27:40,480 --> 00:27:44,659",arabic:"وَكُلُّ مُنْعَطَفٍ يَكْشِفُ لَوْحَةً جَدِيدَةً",segs:[{ar:"وَكُلُّ مُنْعَطَفٍ",uz:"har bir burilish"},{ar:"يَكْشِفُ لَوْحَةً جَدِيدَةً",uz:"yangi bir manzarani ochib beradi"}],full_uz:"Har bir burilish yangi bir manzarani ochib beradi.",note:"مُنْعَطَفٌ — burilish."},
{num:300,time:"00:27:44,659 --> 00:27:51,639",arabic:"بُوزِيتَانُ بِأَنَاقَتِهَا، رَافِيلْلُو بِهُدُوئِهَا، أَمَالْفِي بِسِحْرِهَا الْأَزَلِيِّ",segs:[{ar:"بُوزِيتَانُ بِأَنَاقَتِهَا",uz:"Pozitano o‘zining nafisligi bilan"},{ar:"رَافِيلْلُو بِهُدُوئِهَا",uz:"Ravello o‘zining sokinligi bilan"},{ar:"أَمَالْفِي بِسِحْرِهَا الْأَزَلِيِّ",uz:"Amalfi o‘zining abadiy jozibasi bilan"}],full_uz:"Pozitano o‘zining nafisligi, Ravello o‘zining sokinligi, Amalfi esa o‘zining abadiy jozibasi bilan ajralib turadi.",note:"أَنَاقَةٌ — nafislik, latofat. سِحْرٌ — joziba, sehr."},
{num:301,time:"00:27:51,639 --> 00:27:59,720",arabic:"لَكِنْ مَا يَجْعَلُ هَذَا السَّاحِلَ حَيًّا لَيْسَ مَنْظَرَهُ فَقَطْ، بَلْ إِحْسَاسُهُ",segs:[{ar:"لَكِنْ مَا يَجْعَلُ هَذَا السَّاحِلَ حَيًّا",uz:"ammo bu sohilni jonli qiladigan narsa"},{ar:"لَيْسَ مَنْظَرَهُ فَقَطْ",uz:"faqat uning manzarasi emas"},{ar:"بَلْ إِحْسَاسُهُ",uz:"balki uning hissiyotidir"}],full_uz:"Ammo bu sohilni jonli qiladigan narsa faqat uning manzarasi emas, balki uning hissiyotidir.",note:"إِحْسَاسٌ — hissiyot, tuyg‘u."},
{num:302,time:"00:27:59,720 --> 00:28:25,380",arabic:"رَائِحَةُ الْمِلْحِ وَاللَّيْمُونِ فِي الْهَوَاءِ، أَصْوَاتُ الدَّرَّاجَاتِ الصَّغِيرَةِ، وَضَحِكَاتُ النَّاسِ الَّتِي تَتَرَدَّدُ عَلَى الْمَقَاهِي وَقْتَ الْغُرُوبِ، كَأَنَّ لِلْحَيَاةِ هُنَا نَغْمَةً خَاصَّةً، تُذَكِّرُكَ بِأَنَّ الْفَرَحَ نَفْسَهُ مِنْ نِعَمِ الْخَالِقِ، وَأَنَّ الْجَمَالَ حِينَ يُعَاشُ بِصَفَاءٍ يَصِيرُ عِبَادَةً",segs:[{ar:"رَائِحَةُ الْمِلْحِ وَاللَّيْمُونِ فِي الْهَوَاءِ",uz:"havodagi tuz va limon hidi"},{ar:"أَصْوَاتُ الدَّرَّاجَاتِ الصَّغِيرَةِ",uz:"kichik mototsikllarning ovozlari"},{ar:"وَضَحِكَاتُ النَّاسِ الَّتِي تَتَرَدَّدُ عَلَى الْمَقَاهِي",uz:"va kafelarda aks-sado beradigan odamlarning kulgilari"},{ar:"وَقْتَ الْغُرُوبِ",uz:"quyosh botishi paytida"},{ar:"كَأَنَّ لِلْحَيَاةِ هُنَا نَغْمَةً خَاصَّةً",uz:"go‘yo bu yerda hayotning o‘ziga xos ohangi bordek"},{ar:"تُذَكِّرُكَ بِأَنَّ الْفَرَحَ نَفْسَهُ مِنْ نِعَمِ الْخَالِقِ",uz:"bu sizga quvonchning o‘zi ham Yaratuvchining ne’matlaridan ekanini eslatadi"},{ar:"وَأَنَّ الْجَمَالَ حِينَ يُعَاشُ بِصَفَاءٍ يَصِيرُ عِبَادَةً",uz:"va go‘zallik poklik bilan yashalganda ibodatga aylanishini"}],full_uz:"Havodagi tuz va limon hidi, kichik mototsikllarning ovozlari va quyosh botishi paytida kafelarda aks-sado beradigan odamlarning kulgilari — go‘yo bu yerda hayotning o‘ziga xos ohangi bordek. Bu sizga quvonchning o‘zi ham Yaratuvchining ne’matlaridan ekanini va go‘zallik poklik bilan yashalganda ibodatga aylanishini eslatadi.",note:"نَغْمَةٌ — ohang. صَفَاءٌ — poklik, musaffolik."},
{num:303,time:"00:28:29,720 --> 00:28:34,519",arabic:"نَنْتَقِلُ إِلَى جِبَالِ لُوزُونَ فِي الْفِلِبِّينِ",segs:[{ar:"نَنْتَقِلُ إِلَى جِبَالِ لُوزُونَ",uz:"Luzon tog‘lariga o‘tamiz"},{ar:"فِي الْفِلِبِّينِ",uz:"Filippinda"}],full_uz:"Filippindagi Luzon tog‘lariga o‘tamiz.",note:null},
{num:304,time:"00:28:34,519 --> 00:28:40,740",arabic:"حَيْثُ يَحْتَضِنُ الضَّبَابُ مُعْجِزَةً صَنَعَهَا الْإِنْسَانُ بِتَوْفِيقٍ مِنَ اللَّهِ",segs:[{ar:"حَيْثُ يَحْتَضِنُ الضَّبَابُ مُعْجِزَةً",uz:"u yerda tuman bir mo‘jizani bag‘riga oladi"},{ar:"صَنَعَهَا الْإِنْسَانُ",uz:"uni inson yaratgan"},{ar:"بِتَوْفِيقٍ مِنَ اللَّهِ",uz:"Allohning tavfiqi bilan"}],full_uz:"U yerda tuman inson Allohning tavfiqi bilan yaratgan bir mo‘jizani bag‘riga oladi.",note:"تَوْفِيقٌ — tavfiq, muvaffaqiyatga ilohiy ko‘mak."},
{num:305,time:"00:28:40,740 --> 00:28:44,079",arabic:"مُدَرَّجَاتُ الْأَرُزِّ فِي بَانَاوِي",segs:null,full_uz:"Banaue shahridagi guruch terrasalari.",note:"مُدَرَّجَاتُ الْأَرُزِّ — guruch terrasalari."},
{num:306,time:"00:28:44,079 --> 00:28:47,779",arabic:"بَانَاوِي رِيسْتِيرِيس",segs:null,full_uz:"Banaue Rice Terraces.",note:null},
{num:307,time:"00:28:47,779 --> 00:28:54,019",arabic:"نُحِتَتْ هَذِهِ الْمُدَرَّجَاتُ فِي الْجِبَالِ مُنْذُ أَكْثَرَ مِنْ أَلْفَيْ عَامٍ",segs:[{ar:"نُحِتَتْ هَذِهِ الْمُدَرَّجَاتُ فِي الْجِبَالِ",uz:"bu terr asalar tog‘larga o‘yilgan"},{ar:"مُنْذُ أَكْثَرَ مِنْ أَلْفَيْ عَامٍ",uz:"ikki ming yildan ortiq vaqt oldin"}],full_uz:"Bu terr asalar ikki ming yildan ortiq vaqt oldin tog‘larga o‘yilgan.",note:null},
{num:308,time:"00:28:54,019 --> 00:28:57,120",arabic:"بِأَيْدِي شَعْبِ الْإِيفُوغَاوِ الْبَسِيطِ",segs:[{ar:"بِأَيْدِي شَعْبِ الْإِيفُوغَاوِ",uz:"Ifugao xalqining qo‘llari bilan"},{ar:"الْبَسِيطِ",uz:"oddiy"}],full_uz:"Oddiy Ifugao xalqi qo‘llari bilan.",note:null},
{num:309,time:"00:28:57,120 --> 00:28:59,180",arabic:"بِأَدَوَاتٍ مُتَوَاضِعَةٍ",segs:null,full_uz:"Oddiy asboblar bilan.",note:"مُتَوَاضِعٌ — oddiy, sodda."},
{num:310,time:"00:28:59,180 --> 00:29:02,420",arabic:"وَلَكِنْ بِعَزِيمَةٍ لَا تُقْهَرُ",segs:[{ar:"وَلَكِنْ بِعَزِيمَةٍ",uz:"ammo qat’iyat bilan"},{ar:"لَا تُقْهَرُ",uz:"yengib bo‘lmaydigan"}],full_uz:"Ammo yengib bo‘lmaydigan qat’iyat bilan.",note:"تُقْهَرُ — yengilmoq, mag‘lub qilinmoq."},
{num:311,time:"00:29:02,420 --> 00:29:07,500",arabic:"سَلَالِمُ خَضْرَاءُ تَصْعَدُ نَحْوَ السَّمَاءِ",segs:[{ar:"سَلَالِمُ خَضْرَاءُ",uz:"yashil zinapoyalar"},{ar:"تَصْعَدُ نَحْوَ السَّمَاءِ",uz:"osmonga ko‘tariladi"}],full_uz:"Yashil zinapoyalar osmonga ko‘tariladi.",note:"سُلَّمٌ — zinapoya."},
{num:312,time:"00:29:07,500 --> 00:29:10,320",arabic:"تَجْمَعُ بَيْنَ الْجُهْدِ وَالْإِيمَانِ",segs:null,full_uz:"Ular mehnat va iymonni birlashtiradi.",note:null},
{num:313,time:"00:29:10,320 --> 00:29:14,279",arabic:"وَتَرْوِي قِصَّةَ الْإِنْسَانِ حِينَ يَعْمَلُ فِي الْأَرْضِ",segs:[{ar:"وَتَرْوِي قِصَّةَ الْإِنْسَانِ",uz:"va inson haqida hikoya qiladi"},{ar:"حِينَ يَعْمَلُ فِي الْأَرْضِ",uz:"u yerda mehnat qilganida"}],full_uz:"Va inson yerda mehnat qilganidagi holat haqida hikoya qiladi.",note:null},
{num:314,time:"00:29:14,279 --> 00:29:17,940",arabic:"كَأَنَّهُ يَزْرَعُ فِيهَا حَمْدَهُ لِلَّهِ",segs:[{ar:"كَأَنَّهُ يَزْرَعُ فِيهَا",uz:"go‘yo unda ekayotgandek"},{ar:"حَمْدَهُ لِلَّهِ",uz:"Allohga hamdini"}],full_uz:"Go‘yo unda Allohga hamdini ekayotgandek.",note:null},
{num:315,time:"00:29:17,940 --> 00:29:25,180",arabic:"يَقُولُونَ إِنَّهَا الْعَجِيبَةُ الثَّامِنَةُ مِنْ عَجَائِبِ الدُّنْيَا",segs:[{ar:"يَقُولُونَ",uz:"aytishlaricha"},{ar:"إِنَّهَا الْعَجِيبَةُ الثَّامِنَةُ",uz:"u sakkizinchi mo‘jiza"},{ar:"مِنْ عَجَائِبِ الدُّنْيَا",uz:"dunyo mo‘jizalaridan"}],full_uz:"Aytishlaricha, u dunyo mo‘jizalarining sakkizinchisidir.",note:"عَجِيبَةٌ — mo‘jiza, hayratlanarli narsa."},
{num:316,time:"00:29:25,180 --> 00:29:31,860",arabic:"لَكِنَّهَا فِي الْحَقِيقَةِ تَذْكِيرٌ بِأَنَّ الْإِبْدَاعَ لَا يَحْتَاجُ ثَرْوَةً أَوْ سُلْطَانًا",segs:[{ar:"لَكِنَّهَا فِي الْحَقِيقَةِ",uz:"ammo aslida u"},{ar:"تَذْكِيرٌ بِأَنَّ الْإِبْدَاعَ",uz:"ijodga ... ekanini eslatadi"},{ar:"لَا يَحْتَاجُ ثَرْوَةً أَوْ سُلْطَانًا",uz:"boylik yoki hokimiyat kerak emasligini"}],full_uz:"Ammo aslida u ijod uchun boylik yoki hokimiyat kerak emasligini eslatadi.",note:"سُلْطَانٌ — hokimiyat, saltanat."},
{num:317,time:"00:29:31,860 --> 00:29:34,700",arabic:"بَلْ قَلْبًا عَامِرًا بِالْعَزِيمَةِ",segs:[{ar:"بَلْ قَلْبًا",uz:"balki bir qalb"},{ar:"عَامِرًا بِالْعَزِيمَةِ",uz:"qat’iyatga to‘la"}],full_uz:"Balki qat’iyatga to‘la bir qalb kerak.",note:"عَامِرٌ — to‘la, obod."},
{num:318,time:"00:29:34,700 --> 00:29:40,140",arabic:"وَرُوحًا تَرَى فِي الْعَمَلِ عِبَادَةً تُقَرِّبُهَا إِلَى الْخَالِقِ",segs:[{ar:"وَرُوحًا تَرَى فِي الْعَمَلِ عِبَادَةً",uz:"va mehnatda ibodatni ko‘radigan ruh"},{ar:"تُقَرِّبُهَا إِلَى الْخَالِقِ",uz:"uni Yaratuvchiga yaqinlashtiradigan"}],full_uz:"Va mehnatda uni Yaratuvchiga yaqinlashtiradigan ibodatni ko‘radigan ruh kerak.",note:"تُقَرِّبُ — yaqinlashtirmoq."},
{num:319,time:"00:29:40,140 --> 00:29:47,960",arabic:"تَمْتَدُّ مُدَرَّجَاتُ بَانَاوِي كَدَرَجٍ أَخْضَرَ يَصْعَدُ نَحْوَ السَّمَاءِ",segs:[{ar:"تَمْتَدُّ مُدَرَّجَاتُ بَانَاوِي",uz:"Banaue terrasalari cho‘zilib yotadi"},{ar:"كَدَرَجٍ أَخْضَرَ",uz:"yashil zinapoyadek"},{ar:"يَصْعَدُ نَحْوَ السَّمَاءِ",uz:"osmonga ko‘tariladigan"}],full_uz:"Banaue terrasalari osmonga ko‘tariladigan yashil zinapoyadek cho‘zilib yotadi.",note:null},
{num:320,time:"00:29:47,960 --> 00:29:51,620",arabic:"تَتْبَعُ انْحِنَاءَاتِ الْجِبَالِ بِانْسِجَامٍ مُدْهِشٍ",segs:[{ar:"تَتْبَعُ انْحِنَاءَاتِ الْجِبَالِ",uz:"tog‘larning egri chiziqlariga ergashadi"},{ar:"بِانْسِجَامٍ مُدْهِشٍ",uz:"hayratlanarli uyg‘unlik bilan"}],full_uz:"Ular tog‘larning egri chiziqlariga hayratlanarli uyg‘unlik bilan ergashadi.",note:"انْحِنَاءٌ — egri chiziq, qayrilish."},
{num:321,time:"00:29:51,619 --> 00:29:56,539",arabic:"كَأَنَّهَا نُسِجَتْ بِخُيُوطٍ مِنْ ضَوْءٍ وَتُرَابٍ وَمَاءٍ",segs:[{ar:"كَأَنَّهَا نُسِجَتْ",uz:"go‘yo to‘qilgandek"},{ar:"بِخُيُوطٍ مِنْ ضَوْءٍ وَتُرَابٍ وَمَاءٍ",uz:"nur, tuproq va suv iplaridan"}],full_uz:"Go‘yo nur, tuproq va suv iplaridan to‘qilgandek.",note:"نَسَجَ — to‘qimoq."},
{num:322,time:"00:29:56,539 --> 00:30:01,179",arabic:"فِي مَوْسِمِ الزِّرَاعَةِ",segs:null,full_uz:"Ekin ekish mavsumida.",note:"مَوْسِمُ الزِّرَاعَةِ — ekin ekish mavsumi."},
{num:323,time:"00:30:01,179 --> 00:30:05,119",arabic:"تَتَلَأْلَأُ الْحُقُولُ كَمَرَايَا تَعْكِسُ الْغُيُومَ",segs:[{ar:"تَتَلَأْلَأُ الْحُقُولُ",uz:"dalalar yaltiraydi"},{ar:"كَمَرَايَا تَعْكِسُ الْغُيُومَ",uz:"bulutlarni aks ettiruvchi ko‘zgulardek"}],full_uz:"Dalalar bulutlarni aks ettiruvchi ko‘zgulardek yaltiraydi.",note:"مِرْآةٌ — ko‘zgu."},
{num:324,time:"00:30:05,119 --> 00:30:07,199",arabic:"وَفِي مَوْسِمِ الْحَصَادِ",segs:null,full_uz:"Hosil yig‘ish mavsumida.",note:"مَوْسِمُ الْحَصَادِ — hosil yig‘ish mavsumi."},
{num:325,time:"00:30:07,199 --> 00:30:10,199",arabic:"يَتَوَهَّجُ الْوَادِي بِلَوْنِ الذَّهَبِ",segs:[{ar:"يَتَوَهَّجُ الْوَادِي",uz:"vodiy yarqiraydi"},{ar:"بِلَوْنِ الذَّهَبِ",uz:"oltin rangda"}],full_uz:"Vodiy oltin rangda yarqiraydi.",note:"تَوَهَّجَ — yaltiramoq, yarqiramoq."},
{num:326,time:"00:30:10,199 --> 00:30:14,659",arabic:"فَتَبْدُو الْأَرْضُ وَكَأَنَّهَا تَبْتَسِمُ شُكْرًا لِرَبِّهَا",segs:[{ar:"فَتَبْدُو الْأَرْضُ",uz:"shunda yer ko‘rinadi"},{ar:"وَكَأَنَّهَا تَبْتَسِمُ",uz:"go‘yo u tabassum qilayotgandek"},{ar:"شُكْرًا لِرَبِّهَا",uz:"Robbisiga shukr qilib"}],full_uz:"Shunda yer go‘yo Robbisiga shukr qilib tabassum qilayotgandek ko‘rinadi.",note:null},
{num:327,time:"00:30:14,659 --> 00:30:21,159",arabic:"لَكِنَّ الْجَمَالَ هُنَا لَيْسَ فِي الْمَنْظَرِ وَحْدَهُ",segs:[{ar:"لَكِنَّ الْجَمَالَ هُنَا",uz:"ammo bu yerdagi go‘zallik"},{ar:"لَيْسَ فِي الْمَنْظَرِ وَحْدَهُ",uz:"faqat manzaraning o‘zida emas"}],full_uz:"Ammo bu yerdagi go‘zallik faqat manzaraning o‘zida emas.",note:null},
{num:328,time:"00:30:21,160 --> 00:30:27,440",arabic:"بَلْ فِي الْفِكْرَةِ الَّتِي يَحْمِلُهَا أَنَّ الْإِنْسَانَ حِينَ يَعِيشُ بِتَوَازُنٍ مَعَ الْأَرْضِ",segs:[{ar:"بَلْ فِي الْفِكْرَةِ الَّتِي يَحْمِلُهَا",uz:"balki u ifodalagan g‘oyada"},{ar:"أَنَّ الْإِنْسَانَ حِينَ يَعِيشُ بِتَوَازُنٍ مَعَ الْأَرْضِ",uz:"inson yer bilan muvozanatda yashaganda"}],full_uz:"Balki inson yer bilan muvozanatda yashaganda degan g‘oyani ifodalashidadir.",note:"تَوَازُنٌ — muvozanat."},
{num:329,time:"00:30:27,440 --> 00:30:32,160",arabic:"يَكْتُبُ قَصِيدَتَهُ الْخَاصَّةَ فِي التَّسْبِيحِ لِلْخَالِقِ",segs:[{ar:"يَكْتُبُ قَصِيدَتَهُ الْخَاصَّةَ",uz:"o‘zining alohida she’rini yozadi"},{ar:"فِي التَّسْبِيحِ لِلْخَالِقِ",uz:"Yaratuvchini tasbeh aytishda"}],full_uz:"U Yaratuvchini tasbeh etish haqidagi o‘ziga xos she’rini yozadi.",note:null},
{num:330,time:"00:30:32,160 --> 00:30:40,960",arabic:"نِظَامُ الرِّيِّ الَّذِي تُغَذِّيهِ جَدَاوِلُ الْجِبَالِ مَا زَالَ يَعْمَلُ بِدِقَّةٍ مُنْذُ آلَافِ السِّنِينَ",segs:[{ar:"نِظَامُ الرِّيِّ",uz:"sug‘orish tizimi"},{ar:"الَّذِي تُغَذِّيهِ جَدَاوِلُ الْجِبَالِ",uz:"uni tog‘ soylari oziqlantiradigan"},{ar:"مَا زَالَ يَعْمَلُ بِدِقَّةٍ",uz:"hamon aniq ishlaydi"},{ar:"مُنْذُ آلَافِ السِّنِينَ",uz:"minglab yillardan beri"}],full_uz:"Tog‘ soylari oziqlantiradigan sug‘orish tizimi minglab yillardan beri hamon aniq ishlaydi.",note:"جَدْوَلٌ — soy, kichik oqim."},
{num:331,time:"00:30:40,960 --> 00:30:47,040",arabic:"كَأَنَّ الطَّبِيعَةَ وَالْإِنْسَانَ عَقَدَا عَهْدًا عَلَى التَّعَاوُنِ بِإِذْنِ اللَّهِ",segs:[{ar:"كَأَنَّ الطَّبِيعَةَ وَالْإِنْسَانَ",uz:"go‘yo tabiat va inson"},{ar:"عَقَدَا عَهْدًا",uz:"ahd qilgandek"},{ar:"عَلَى التَّعَاوُنِ بِإِذْنِ اللَّهِ",uz:"Allohning izni bilan hamkorlik qilishga"}],full_uz:"Go‘yo tabiat va inson Allohning izni bilan hamkorlik qilishga ahd qilgandek.",note:"عَهْدٌ — ahd, kelishuv."},
{num:332,time:"00:30:51,160 --> 00:31:04,000",arabic:"فِي سَانْتُورِينِي، جَوْهَرَةِ بَحْرِ إِيجَةَ، جَزِيرَةٌ بُرْكَانِيَّةٌ بَيْضَاءُ تَتَشَبَّثُ بِقِمَمِ الْجِبَالِ، وَتُعَانِقُ السَّمَاءَ بِقِبَابِهَا الزَّرْقَاءِ",segs:[{ar:"فِي سَانْتُورِينِي، جَوْهَرَةِ بَحْرِ إِيجَةَ",uz:"Egey dengizining durdonasi Santorinida"},{ar:"جَزِيرَةٌ بُرْكَانِيَّةٌ بَيْضَاءُ",uz:"oq vulqon oroli"},{ar:"تَتَشَبَّثُ بِقِمَمِ الْجِبَالِ",uz:"tog‘ cho‘qqilariga yopishib turadi"},{ar:"وَتُعَانِقُ السَّمَاءَ بِقِبَابِهَا الزَّرْقَاءِ",uz:"va moviy gumbazlari bilan osmonni quchoqlaydi"}],full_uz:"Egey dengizining durdonasi Santorinida oq vulqon oroli tog‘ cho‘qqilariga yopishib, moviy gumbazlari bilan osmonni quchoqlab turadi.",note:"جَوْهَرَةٌ — durdona. تَتَشَبَّثُ — mahkam yopishmoq."},
{num:333,time:"00:31:04,000 --> 00:31:14,460",arabic:"وُلِدَتْ سَانْتُورِينِي مِنْ وَاحِدَةٍ مِنْ أَعْظَمِ الِانْفِجَارَاتِ الْبُرْكَانِيَّةِ فِي التَّارِيخِ",segs:[{ar:"وُلِدَتْ سَانْتُورِينِي",uz:"Santorini paydo bo‘lgan"},{ar:"مِنْ وَاحِدَةٍ مِنْ أَعْظَمِ الِانْفِجَارَاتِ الْبُرْكَانِيَّةِ",uz:"eng buyuk vulqon otilishlaridan biridan"},{ar:"فِي التَّارِيخِ",uz:"tarixdagi"}],full_uz:"Santorini tarixdagi eng buyuk vulqon otilishlaridan biridan paydo bo‘lgan.",note:"انْفِجَارٌ بُرْكَانِيٌّ — vulqon otilishi."},
{num:334,time:"00:31:14,460 --> 00:31:20,019",arabic:"فَصَاغَ اللَّهُ مِنْهَا مَشْهَدًا يَجْمَعُ بَيْنَ الْقُوَّةِ وَالْجَمَالِ",segs:[{ar:"فَصَاغَ اللَّهُ مِنْهَا مَشْهَدًا",uz:"shunda Alloh undan bir manzara yaratdi"},{ar:"يَجْمَعُ بَيْنَ الْقُوَّةِ وَالْجَمَالِ",uz:"kuch va go‘zallikni jamlaydigan"}],full_uz:"Shunda Alloh undan kuch va go‘zallikni jamlagan bir manzara yaratdi.",note:"صَاغَ — shakl bermoq, yaratmoq."},
{num:335,time:"00:31:20,019 --> 00:31:25,319",arabic:"كَأَنَّ النَّارَ وَالْمَاءَ اتَّفَقَا عَلَى رَسْمِ لَوْحَةٍ أَبَدِيَّةٍ",segs:[{ar:"كَأَنَّ النَّارَ وَالْمَاءَ اتَّفَقَا",uz:"go‘yo olov va suv kelishgandek"},{ar:"عَلَى رَسْمِ لَوْحَةٍ أَبَدِيَّةٍ",uz:"abadiy bir manzarani chizishga"}],full_uz:"Go‘yo olov va suv abadiy bir manzarani chizishga kelishgandek.",note:"أَبَدِيٌّ — abadiy."},
{num:336,time:"00:31:25,319 --> 00:31:35,460",arabic:"إِطْلَالَةُ الْكَالْدِيرَا لَا تُشْبِهُ أَيَّ مَنْظَرٍ آخَرَ عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"إِطْلَالَةُ الْكَالْدِيرَا",uz:"Kaldera manzarasi"},{ar:"لَا تُشْبِهُ أَيَّ مَنْظَرٍ آخَرَ",uz:"boshqa hech bir manzaraga o‘xshamaydi"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"}],full_uz:"Kaldera manzarasi yer yuzidagi boshqa hech bir manzaraga o‘xshamaydi.",note:"إِطْلَالَةٌ — manzara, ko‘rinish."},
{num:337,time:"00:31:35,460 --> 00:31:41,019",arabic:"مُنْحَدَرَاتٌ شَاهِقَةٌ تَهْبِطُ إِلَى مِيَاهٍ فِيرُوزِيَّةٍ لَامِعَةٍ",segs:[{ar:"مُنْحَدَرَاتٌ شَاهِقَةٌ",uz:"baland tik yonbag‘irlar"},{ar:"تَهْبِطُ إِلَى مِيَاهٍ فِيرُوزِيَّةٍ لَامِعَةٍ",uz:"yarqiragan feruza rangli suvlargacha tushadi"}],full_uz:"Baland tik yonbag‘irlar yarqiragan feruza rangli suvlargacha tushib boradi.",note:"مُنْحَدَرٌ — yonbag‘ir, nishablik."},
{num:338,time:"00:31:41,019 --> 00:31:45,899",arabic:"تَتَقَبَّلُ أَشِعَّةَ الشَّمْسِ كَأَنَّهَا قُبَلٌ مِنْ ذَهَبٍ",segs:[{ar:"تَتَقَبَّلُ أَشِعَّةَ الشَّمْسِ",uz:"quyosh nurlarini qabul qiladi"},{ar:"كَأَنَّهَا قُبَلٌ مِنْ ذَهَبٍ",uz:"go‘yo oltindan bo‘sa olgandek"}],full_uz:"Ular quyosh nurlarini go‘yo oltindan bo‘salar kabi qabul qiladi.",note:"قُبْلَةٌ — bo‘sa."},
{num:339,time:"00:31:45,900 --> 00:31:52,820",arabic:"فِي أَزِقَّةِ أُويَا وَفِيرَا الضَّيِّقَةِ",segs:null,full_uz:"Oya va Fira tor ko‘chalarida.",note:"زُقَاقٌ — tor ko‘cha."},
{num:340,time:"00:31:52,820 --> 00:31:56,100",arabic:"يَمْتَزِجُ الْبَيَاضُ بِالزُّرْقَةِ وَالضَّوْءِ",segs:[{ar:"يَمْتَزِجُ الْبَيَاضُ بِالزُّرْقَةِ",uz:"oqlik moviylik bilan qorishadi"},{ar:"وَالضَّوْءِ",uz:"va nur bilan"}],full_uz:"Oqlik moviylik va nur bilan qorishadi.",note:"يَمْتَزِجُ — qorishmoq, aralashmoq."},
{num:341,time:"00:31:56,100 --> 00:32:01,680",arabic:"وَكُلُّ زَاوِيَةٍ هُنَاكَ تَبْدُو كَصُورَةٍ الْتَقَطَتْهَا يَدُ الْحُلْمِ",segs:[{ar:"وَكُلُّ زَاوِيَةٍ هُنَاكَ",uz:"u yerdagi har bir burchak"},{ar:"تَبْدُو كَصُورَةٍ",uz:"suratdek ko‘rinadi"},{ar:"الْتَقَطَتْهَا يَدُ الْحُلْمِ",uz:"uni tushning qo‘li olgandek"}],full_uz:"U yerdagi har bir burchak go‘yo tushning qo‘li olgan suratdek ko‘rinadi.",note:"الْتَقَطَ — suratga olmoq."},
{num:342,time:"00:32:01,680 --> 00:32:09,600",arabic:"وَعِنْدَمَا تَمِيلُ الشَّمْسُ نَحْوَ الْغُرُوبِ",segs:null,full_uz:"Quyosh botishga og‘ganda.",note:"مَالَ نَحْوَ — tomon og‘moq."},
{num:343,time:"00:32:09,600 --> 00:32:12,620",arabic:"يَجْتَمِعُ النَّاسُ عِنْدَ حَوَافِّ الْجَزِيرَةِ",segs:[{ar:"يَجْتَمِعُ النَّاسُ",uz:"odamlar to‘planadi"},{ar:"عِنْدَ حَوَافِّ الْجَزِيرَةِ",uz:"orol chekkalarida"}],full_uz:"Odamlar orol chekkalarida to‘planadi.",note:"حَافَّةٌ — chekka."},
{num:344,time:"00:32:12,619 --> 00:32:16,459",arabic:"لِيَشْهَدُوا مَشْهَدًا يَصْعُبُ وَصْفُهُ بِالْكَلِمَاتِ",segs:[{ar:"لِيَشْهَدُوا مَشْهَدًا",uz:"bir manzaraga guvoh bo‘lish uchun"},{ar:"يَصْعُبُ وَصْفُهُ بِالْكَلِمَاتِ",uz:"uni so‘z bilan tasvirlash qiyin"}],full_uz:"So‘z bilan tasvirlash qiyin bo‘lgan manzaraga guvoh bo‘lish uchun.",note:"يَصْعُبُ — qiyin bo‘lmoq."},
{num:345,time:"00:32:16,459 --> 00:32:21,519",arabic:"حِينَ يَتَحَوَّلُ الْأُفُقُ إِلَى لَوْحَةٍ مِنْ نَارٍ وَوَرْدٍ وَبَنَفْسَجٍ",segs:[{ar:"حِينَ يَتَحَوَّلُ الْأُفُقُ",uz:"ufq aylanganda"},{ar:"إِلَى لَوْحَةٍ",uz:"bir manzaraga"},{ar:"مِنْ نَارٍ وَوَرْدٍ وَبَنَفْسَجٍ",uz:"olov, pushti va binafsha ranglardan"}],full_uz:"Ufq olov, pushti va binafsha ranglardan iborat bir manzaraga aylanganda.",note:"بَنَفْسَجٌ — binafsha rang."},
{num:346,time:"00:32:21,519 --> 00:32:28,059",arabic:"فِي تَسْبِيحَةِ ضَوْءٍ تُذَكِّرُكَ أَنَّ الْجَمَالَ وَعْدٌ مِنَ اللَّهِ لَا مُصَادَفَةٌ",segs:[{ar:"فِي تَسْبِيحَةِ ضَوْءٍ",uz:"nur tasbehida"},{ar:"تُذَكِّرُكَ",uz:"sizga eslatadi"},{ar:"أَنَّ الْجَمَالَ وَعْدٌ مِنَ اللَّهِ",uz:"go‘zallik Allohning va’dasi ekanini"},{ar:"لَا مُصَادَفَةٌ",uz:"tasodif emasligini"}],full_uz:"Nur tasbehida go‘zallik Allohning va’dasi, tasodif emasligini eslatadi.",note:"مُصَادَفَةٌ — tasodif."},
{num:347,time:"00:32:28,059 --> 00:32:38,379",arabic:"وَمِنْ أَعْمَاقِ الْبَحْرِ إِلَى أَعَالِي الْجِبَالِ",segs:null,full_uz:"Dengiz tubidan baland tog‘largacha.",note:null},
{num:348,time:"00:32:38,379 --> 00:32:41,000",arabic:"نَصِلُ إِلَى قَلْبِ الْيُونَانِ",segs:[{ar:"نَصِلُ",uz:"yetib boramiz"},{ar:"إِلَى قَلْبِ الْيُونَانِ",uz:"Yunonistonning yuragiga"}],full_uz:"Yunonistonning yuragiga yetib boramiz.",note:null},
{num:349,time:"00:32:41,000 --> 00:32:46,559",arabic:"حَيْثُ تَبْدُو الْأَدْيِرَةُ كَأَنَّهَا مُعَلَّقَةٌ بَيْنَ الْأَرْضِ وَالسَّمَاءِ",segs:[{ar:"حَيْثُ تَبْدُو الْأَدْيِرَةُ",uz:"u yerda monastirlar ko‘rinadi"},{ar:"كَأَنَّهَا مُعَلَّقَةٌ",uz:"go‘yo osilib turgandek"},{ar:"بَيْنَ الْأَرْضِ وَالسَّمَاءِ",uz:"yer bilan osmon orasida"}],full_uz:"U yerda monastirlar go‘yo yer bilan osmon orasida osilib turgandek ko‘rinadi.",note:"مُعَلَّقٌ — osilgan, muallaq."},
{num:350,time:"00:32:46,559 --> 00:32:50,160",arabic:"إِنَّهَا أَدْيِرَةُ مِيتْيُورَا",segs:null,full_uz:"Bu Meteora monastirlaridir.",note:null},
{num:351,time:"00:32:50,160 --> 00:32:58,819",arabic:"تَعْلُو فَوْقَ أَعْمِدَةٍ صَخْرِيَّةٍ شَاهِقَةٍ نَحَتَتْهَا الرِّيَاحُ",segs:[{ar:"تَعْلُو فَوْقَ أَعْمِدَةٍ صَخْرِيَّةٍ شَاهِقَةٍ",uz:"baland qoyali ustunlar ustida yuksaladi"},{ar:"نَحَتَتْهَا الرِّيَاحُ",uz:"ularni shamollar o‘ygan"}],full_uz:"U shamollar o‘ygan baland qoyali ustunlar ustida yuksaladi.",note:"أَعْمِدَةٌ صَخْرِيَّةٌ — qoyali ustunlar."},
{num:352,time:"00:32:58,819 --> 00:33:01,519",arabic:"بَنَاهَا الرُّهْبَانُ مُنْذُ قُرُونٍ",segs:[{ar:"بَنَاهَا الرُّهْبَانُ",uz:"uni rohiblar qurdilar"},{ar:"مُنْذُ قُرُونٍ",uz:"asrlar oldin"}],full_uz:"Uni rohiblar asrlar oldin qurgan.",note:"رَاهِبٌ — rohib."},
{num:353,time:"00:33:01,519 --> 00:33:04,359",arabic:"هَرَبًا مِنْ صَخَبِ الدُّنْيَا",segs:null,full_uz:"Dunyoning shovqin-suronidan qochib.",note:"صَخَبٌ — shovqin-suron."},
{num:354,time:"00:33:04,359 --> 00:33:09,259",arabic:"وَاشْتِيَاقًا إِلَى سَكِينَةٍ تُقَرِّبُهُمْ مِنَ الْخَالِقِ",segs:[{ar:"وَاشْتِيَاقًا إِلَى سَكِينَةٍ",uz:"va sokinlikni sog‘inib"},{ar:"تُقَرِّبُهُمْ مِنَ الْخَالِقِ",uz:"ularni Yaratuvchiga yaqinlashtiradigan"}],full_uz:"Va ularni Yaratuvchiga yaqinlashtiradigan sokinlikni sog‘inib.",note:"اشْتِيَاقٌ — sog‘inish, kuchli intilish."},
{num:355,time:"00:33:11,000 --> 00:33:18,480",arabic:"اسْمُهَا فِي الْيُونَانِيَّةِ يَعْنِي الْمُعَلَّقَةَ فِي الْهَوَاءِ",segs:[{ar:"اسْمُهَا فِي الْيُونَانِيَّةِ",uz:"uning yunon tilidagi nomi"},{ar:"يَعْنِي الْمُعَلَّقَةَ فِي الْهَوَاءِ",uz:"havoda osilgan degani"}],full_uz:"Uning yunon tilidagi nomi “havoda osilgan” degan ma’noni anglatadi.",note:"مُعَلَّقَةٌ فِي الْهَوَاءِ — havoda osilgan."},
{num:356,time:"00:33:18,480 --> 00:33:23,099",arabic:"وَمَا إِنْ تَرَاهَا حَتَّى تُدْرِكَ صِدْقَ الْاسْمِ",segs:[{ar:"وَمَا إِنْ تَرَاهَا",uz:"uni ko‘rishingiz bilanoq"},{ar:"حَتَّى تُدْرِكَ",uz:"anglaysiz"},{ar:"صِدْقَ الْاسْمِ",uz:"nomning to‘g‘riligini"}],full_uz:"Uni ko‘rishingiz bilanoq bu nom naqadar to‘g‘ri ekanini anglaysiz.",note:"صِدْقٌ — rostlik, to‘g‘rilik."},
{num:357,time:"00:33:23,099 --> 00:33:27,000",arabic:"فَالضَّبَابُ يَلُفُّ الْوَادِيَ مِنْ تَحْتِهَا",segs:[{ar:"فَالضَّبَابُ يَلُفُّ الْوَادِيَ",uz:"chunki tuman vodiyni o‘rab oladi"},{ar:"مِنْ تَحْتِهَا",uz:"uning ostidan"}],full_uz:"Chunki tuman uning ostidagi vodiyni o‘rab oladi.",note:"لَفَّ — o‘ramoq, qoplamoq."},
{num:358,time:"00:33:27,000 --> 00:33:31,400",arabic:"كَأَنَّهَا جُزُرٌ مِنْ نُورٍ تَسْبَحُ فِي بَحْرٍ مِنْ سَحَابٍ",segs:[{ar:"كَأَنَّهَا جُزُرٌ مِنْ نُورٍ",uz:"go‘yo nurdan orollardek"},{ar:"تَسْبَحُ فِي بَحْرٍ مِنْ سَحَابٍ",uz:"bulutlar dengizida suzayotgan"}],full_uz:"Go‘yo bulutlar dengizida suzayotgan nur orollaridek.",note:null},
{num:359,time:"00:33:31,400 --> 00:33:40,299",arabic:"كُلُّ دَيْرٍ هُنَا مُعْجِزَةُ صَبْرٍ وَإِيمَانٍ",segs:[{ar:"كُلُّ دَيْرٍ هُنَا",uz:"bu yerdagi har bir monastir"},{ar:"مُعْجِزَةُ صَبْرٍ وَإِيمَانٍ",uz:"sabr va iymon mo‘jizasi"}],full_uz:"Bu yerdagi har bir monastir sabr va iymon mo‘jizasidir.",note:null},
{num:360,time:"00:33:40,299 --> 00:33:44,440",arabic:"بُنِيَتِ الْحِجَارَةُ عَلَى الْقِمَمِ بِلَا طُرُقٍ وَلَا جُسُورٍ",segs:[{ar:"بُنِيَتِ الْحِجَارَةُ عَلَى الْقِمَمِ",uz:"toshlar cho‘qqilarga qurilgan"},{ar:"بِلَا طُرُقٍ وَلَا جُسُورٍ",uz:"yo‘llarsiz va ko‘priklarsiz"}],full_uz:"Toshlar yo‘llar va ko‘priklarsiz cho‘qqilarga qurilgan.",note:null},
{num:361,time:"00:33:44,440 --> 00:33:50,359",arabic:"لَكِنَّهَا صَمَدَتْ شَاهِدَةً عَلَى عَزِيمَةٍ لَا تَهُزُّهَا الْمَسَافَاتُ",segs:[{ar:"لَكِنَّهَا صَمَدَتْ",uz:"ammo ular bardosh berdi"},{ar:"شَاهِدَةً عَلَى عَزِيمَةٍ",uz:"qat’iyatga guvoh bo‘lib"},{ar:"لَا تَهُزُّهَا الْمَسَافَاتُ",uz:"masofalar uni tebrata olmaydigan"}],full_uz:"Ammo ular masofalar tebrata olmaydigan qat’iyatga guvoh bo‘lib bardosh berdi.",note:"صَمَدَ — bardosh bermoq, sobit turmoq."},
{num:362,time:"00:33:50,359 --> 00:33:54,659",arabic:"وَرُوحٍ تَبْحَثُ عَنِ السُّمُوِّ لَا عَنِ الْعُلُوِّ",segs:[{ar:"وَرُوحٍ تَبْحَثُ عَنِ السُّمُوِّ",uz:"va yuksalishni izlaydigan ruh"},{ar:"لَا عَنِ الْعُلُوِّ",uz:"balandlikni emas"}],full_uz:"Va balandlikni emas, ma’naviy yuksalishni izlaydigan ruh.",note:"السُّمُوُّ — yuksaklik, ma’naviy yuksalish. الْعُلُوُّ — balandlik."},
{num:363,time:"00:33:54,659 --> 00:34:03,220",arabic:"بُنِيَتْ أَدْيِرَةُ مِيتْيُورَا يَدًا بِيَدٍ",segs:[{ar:"بُنِيَتْ أَدْيِرَةُ مِيتْيُورَا",uz:"Meteora monastirlari qurilgan"},{ar:"يَدًا بِيَدٍ",uz:"qo‘lma-qo‘l, hamjihatlikda"}],full_uz:"Meteora monastirlari qo‘lma-qo‘l, hamjihatlikda qurilgan.",note:"يَدًا بِيَدٍ — qo‘lma-qo‘l, birgalikda."},
{num:364,time:"00:34:03,220 --> 00:34:05,680",arabic:"حَجَرًا فَوْقَ حَجَرٍ",segs:null,full_uz:"Tosh ustiga tosh qo‘yib.",note:null},
{num:365,time:"00:34:05,680 --> 00:34:08,719",arabic:"فِي أَمَاكِنَ بَدَتْ مُسْتَحِيلَةَ الْوُصُولِ",segs:[{ar:"فِي أَمَاكِنَ",uz:"joylarda"},{ar:"بَدَتْ مُسْتَحِيلَةَ الْوُصُولِ",uz:"yetib borish imkonsizdek ko‘ringan"}],full_uz:"Yetib borish imkonsizdek ko‘ringan joylarda.",note:"مُسْتَحِيلٌ — imkonsiz."},
{num:366,time:"00:34:08,719 --> 00:34:14,719",arabic:"لَكِنَّ الْإِرَادَةَ حِينَ تَتَّجِهُ نَحْوَ السَّمَاءِ لَا تَعْرِفُ الْمُسْتَحِيلَ",segs:[{ar:"لَكِنَّ الْإِرَادَةَ",uz:"ammo iroda"},{ar:"حِينَ تَتَّجِهُ نَحْوَ السَّمَاءِ",uz:"osmonga intilganda"},{ar:"لَا تَعْرِفُ الْمُسْتَحِيلَ",uz:"imkonsizlikni bilmaydi"}],full_uz:"Ammo iroda osmonga intilganda imkonsizlikni bilmaydi.",note:"الْإِرَادَةُ — iroda."},
{num:367,time:"00:34:14,719 --> 00:34:25,139",arabic:"وَأَنْتَ تَصْعَدُ الدَّرَجَاتِ أَوْ تَسِيرُ فِي الْمَمَرَّاتِ الْمُتَعَرِّجَةِ نَحْوَ الْقِمَّةِ",segs:[{ar:"وَأَنْتَ تَصْعَدُ الدَّرَجَاتِ",uz:"zinapoyalardan ko‘tarilganingizda"},{ar:"أَوْ تَسِيرُ فِي الْمَمَرَّاتِ الْمُتَعَرِّجَةِ",uz:"yoki egri-bugri yo‘laklardan yurganingizda"},{ar:"نَحْوَ الْقِمَّةِ",uz:"cho‘qqi tomon"}],full_uz:"Zinapoyalardan ko‘tarilib yoki egri-bugri yo‘laklardan cho‘qqi tomon yurganingizda.",note:"مُتَعَرِّجٌ — egri-bugri, burama."},
{num:368,time:"00:34:25,139 --> 00:34:30,939",arabic:"تَشْعُرُ بِالسَّكِينَةِ الَّتِي سَكَنَتْ هَذَا الْمَكَانَ مُنْذُ قُرُونٍ طَوِيلَةٍ",segs:[{ar:"تَشْعُرُ بِالسَّكِينَةِ",uz:"sokinlikni his qilasiz"},{ar:"الَّتِي سَكَنَتْ هَذَا الْمَكَانَ",uz:"bu joyni makon qilgan"},{ar:"مُنْذُ قُرُونٍ طَوِيلَةٍ",uz:"ko‘p asrlardan beri"}],full_uz:"Bu joyni ko‘p asrlardan beri makon qilgan sokinlikni his qilasiz.",note:null},
{num:369,time:"00:34:30,939 --> 00:34:35,539",arabic:"كَأَنَّ الْجِبَالَ تَحْفَظُ بَيْنَ صُخُورِهَا أَنْفَاسَ الْمُصَلِّينَ",segs:[{ar:"كَأَنَّ الْجِبَالَ تَحْفَظُ",uz:"go‘yo tog‘lar saqlayotgandek"},{ar:"بَيْنَ صُخُورِهَا",uz:"o‘z qoyalari orasida"},{ar:"أَنْفَاسَ الْمُصَلِّينَ",uz:"namozxonlarning nafaslarini"}],full_uz:"Go‘yo tog‘lar o‘z qoyalari orasida namozxonlarning nafaslarini saqlayotgandek.",note:"أَنْفَاسٌ — nafaslar."},
{num:370,time:"00:34:38,719 --> 00:34:46,659",arabic:"وَعِنْدَ الْغُرُوبِ حِينَ تَصْبُغُ الشَّمْسُ الْجُرُوفَ بِالذَّهَبِ وَالْقِرْمِزِيِّ",segs:[{ar:"وَعِنْدَ الْغُرُوبِ",uz:"quyosh botishida"},{ar:"حِينَ تَصْبُغُ الشَّمْسُ الْجُرُوفَ",uz:"quyosh jarliklarni bo‘yaganda"},{ar:"بِالذَّهَبِ وَالْقِرْمِزِيِّ",uz:"oltin va qirmizi rangga"}],full_uz:"Quyosh botishida, quyosh jarliklarni oltin va qirmizi rangga bo‘yaganda.",note:"الْقِرْمِزِيُّ — qirmizi, to‘q qizil."},
{num:371,time:"00:34:46,659 --> 00:34:51,059",arabic:"تُدْرِكُ أَنَّ مِيتْيُورَا لَيْسَتْ مُجَرَّدَ مَكَانٍ",segs:[{ar:"تُدْرِكُ",uz:"anglaysiz"},{ar:"أَنَّ مِيتْيُورَا لَيْسَتْ مُجَرَّدَ مَكَانٍ",uz:"Meteora shunchaki joy emasligini"}],full_uz:"Meteora shunchaki joy emasligini anglaysiz.",note:null},
{num:372,time:"00:34:51,059 --> 00:34:53,859",arabic:"بَلْ جِسْرٌ بَيْنَ الْأَرْضِ وَالسَّمَاءِ",segs:null,full_uz:"Balki yer bilan osmon orasidagi ko‘prikdir.",note:null},
{num:373,time:"00:34:53,859 --> 00:34:57,500",arabic:"حَيْثُ يَلْتَقِي الْإِيمَانُ بِمَا لَا نِهَايَةَ لَهُ",segs:[{ar:"حَيْثُ يَلْتَقِي الْإِيمَانُ",uz:"u yerda iymon uchrashadi"},{ar:"بِمَا لَا نِهَايَةَ لَهُ",uz:"chegarasi yo‘q narsalar bilan"}],full_uz:"U yerda iymon cheksizlik bilan uchrashadi.",note:null},
{num:374,time:"00:34:57,500 --> 00:35:07,699",arabic:"وَعَبْرَ آلَافِ الْكِيلُومِتْرَاتِ جَنُوبًا",segs:null,full_uz:"Minglab kilometr janubga.",note:null},
{num:375,time:"00:35:07,699 --> 00:35:11,339",arabic:"تَمْتَدُّ أَعْظَمُ غَابَةٍ عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"تَمْتَدُّ أَعْظَمُ غَابَةٍ",uz:"eng ulkan o‘rmon cho‘zilib yotadi"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"}],full_uz:"Yer yuzidagi eng ulkan o‘rmon cho‘zilib yotadi.",note:null},
{num:376,time:"00:35:11,339 --> 00:35:12,859",arabic:"الْأَمَازُونُ",segs:null,full_uz:"Amazonka.",note:null},
{num:377,time:"00:35:12,859 --> 00:35:14,679",arabic:"رِئَتَا الْكَوْكَبِ",segs:null,full_uz:"Sayyoraning o‘pkalari.",note:"رِئَةٌ — o‘pka."},
{num:378,time:"00:35:14,679 --> 00:35:18,919",arabic:"وَمَوْطِنُ الْحَيَاةِ النَّابِضَةِ مُنْذُ فَجْرِ الْخَلْقِ",segs:[{ar:"وَمَوْطِنُ الْحَيَاةِ النَّابِضَةِ",uz:"va jo‘shqin hayot maskani"},{ar:"مُنْذُ فَجْرِ الْخَلْقِ",uz:"yaratilish tongidan beri"}],full_uz:"Va yaratilish tongidan beri jo‘shqin hayot maskani.",note:"نَابِضٌ — jo‘shqin, tirik, urib turgan."},
{num:379,time:"00:35:18,919 --> 00:35:26,379",arabic:"تُغَطِّي أَكْثَرَ مِنْ خَمْسَةِ مَلَايِينَ كِيلُومِتْرٍ مُرَبَّعٍ",segs:null,full_uz:"U besh million kvadrat kilometrdan ortiq maydonni qoplaydi.",note:"مُرَبَّعٌ — kvadrat."},
{num:380,time:"00:35:26,379 --> 00:35:30,219",arabic:"وَتَضُمُّ مِنَ الْمَخْلُوقَاتِ مَا يَفُوقُ الْعَدَّ وَالْحَصْرَ",segs:[{ar:"وَتَضُمُّ مِنَ الْمَخْلُوقَاتِ",uz:"va unda shunchalik ko‘p mavjudotlar borki"},{ar:"مَا يَفُوقُ الْعَدَّ وَالْحَصْرَ",uz:"ularni sanab bo‘lmaydi"}],full_uz:"Unda sanab bo‘lmaydigan darajada ko‘p mavjudotlar bor.",note:"الْحَصْرُ — chegaralash, hisoblash."},
{num:381,time:"00:35:30,219 --> 00:35:34,299",arabic:"مِنَ النُّمُورِ الْمُرَقَّطَةِ إِلَى الدَّلَافِينِ الْوَرْدِيَّةِ",segs:[{ar:"مِنَ النُّمُورِ الْمُرَقَّطَةِ",uz:"ola-bula yo‘lbarslardan"},{ar:"إِلَى الدَّلَافِينِ الْوَرْدِيَّةِ",uz:"pushti delfinlargacha"}],full_uz:"Ola-bula yo‘lbarslardan pushti delfinlargacha.",note:"مُرَقَّطٌ — dog‘li, ola-bula."},
{num:382,time:"00:35:34,299 --> 00:35:36,839",arabic:"وَمِنْ طُيُورِ الْمَاكَاوِ الْبَهِيَّةِ",segs:null,full_uz:"Va chiroyli makao qushlaridan.",note:"بَهِيٌّ — chiroyli, ko‘rkam."},
{num:383,time:"00:35:36,840 --> 00:35:39,720",arabic:"إِلَى الْكَسْلَانِ الْمُتَدَلِّي عَلَى الْأَغْصَانِ",segs:[{ar:"إِلَى الْكَسْلَانِ",uz:"yalqov hayvonlargacha"},{ar:"الْمُتَدَلِّي عَلَى الْأَغْصَانِ",uz:"shoxlarda osilib turadigan"}],full_uz:"Shoxlarda osilib turadigan yalqov hayvonlargacha.",note:"كَسْلَانٌ — yalqov hayvon, sloth."},
{num:384,time:"00:35:39,720 --> 00:35:43,360",arabic:"إِلَى مَلَايِينَ الْأَنْوَاعِ مِنَ الْحَشَرَاتِ وَالنَّبَاتَاتِ",segs:[{ar:"إِلَى مَلَايِينَ الْأَنْوَاعِ",uz:"millionlab turlargacha"},{ar:"مِنَ الْحَشَرَاتِ وَالنَّبَاتَاتِ",uz:"hasharotlar va o‘simliklardan"}],full_uz:"Hasharotlar va o‘simliklarning millionlab turlarigacha.",note:"نَوْعٌ — tur."},
{num:385,time:"00:35:43,360 --> 00:35:46,300",arabic:"كَثِيرٌ مِنْهَا لَمْ يُكْتَشَفْ بَعْدُ",segs:[{ar:"كَثِيرٌ مِنْهَا",uz:"ularning ko‘pi"},{ar:"لَمْ يُكْتَشَفْ بَعْدُ",uz:"hali kashf qilinmagan"}],full_uz:"Ularning ko‘pi hali kashf qilinmagan.",note:"اكْتَشَفَ — kashf qilmoq."},
{num:386,time:"00:35:46,300 --> 00:35:55,100",arabic:"كُلُّ صَوْتٍ هُنَا نِدَاءُ الْقِرَدَةِ الْبَعِيدَةِ",segs:[{ar:"كُلُّ صَوْتٍ هُنَا",uz:"bu yerdagi har bir ovoz"},{ar:"نِدَاءُ الْقِرَدَةِ الْبَعِيدَةِ",uz:"uzoqdagi maymunlarning nidosi"}],full_uz:"Bu yerdagi har bir ovoz — uzoqdagi maymunlarning nidosi.",note:"نِدَاءٌ — nido, chaqiriq."},
{num:387,time:"00:35:55,100 --> 00:35:57,940",arabic:"وَهَمْسُ الْمَطَرِ فَوْقَ أَوْرَاقِ الْأَشْجَارِ",segs:null,full_uz:"Va daraxt barglari ustidagi yomg‘ir shiviri.",note:"هَمْسٌ — shivir, pichirlash."},
{num:388,time:"00:35:57,940 --> 00:36:01,800",arabic:"يَبْدُو جُزْءًا مِنْ سِيمْفُونِيَّةٍ كَوْنِيَّةٍ",segs:[{ar:"يَبْدُو جُزْءًا",uz:"bir qismdek ko‘rinadi"},{ar:"مِنْ سِيمْفُونِيَّةٍ كَوْنِيَّةٍ",uz:"koinot simfoniyasining"}],full_uz:"Koinot simfoniyasining bir qismidek ko‘rinadi.",note:"سِيمْفُونِيَّةٌ — simfoniya."},
{num:389,time:"00:36:01,800 --> 00:36:05,180",arabic:"تَعْزِفُهَا الْحَيَاةُ فِي أَبْهَى صُوَرِهَا",segs:[{ar:"تَعْزِفُهَا الْحَيَاةُ",uz:"uni hayot ijro etadi"},{ar:"فِي أَبْهَى صُوَرِهَا",uz:"o‘zining eng go‘zal ko‘rinishida"}],full_uz:"Uni hayot o‘zining eng go‘zal ko‘rinishida ijro etadi.",note:"أَبْهَى — eng go‘zal, eng yorqin."},
{num:390,time:"00:36:06,840 --> 00:36:14,800",arabic:"يَتَعَرَّجُ نَهْرُ الْأَمَازُونِ الْعَظِيمُ وَسَطَ هَذَا الْعَالَمِ الْأَخْضَرِ",segs:[{ar:"يَتَعَرَّجُ نَهْرُ الْأَمَازُونِ الْعَظِيمُ",uz:"ulkan Amazonka daryosi egri-bugri oqadi"},{ar:"وَسَطَ هَذَا الْعَالَمِ الْأَخْضَرِ",uz:"bu yashil olam o‘rtasidan"}],full_uz:"Ulkan Amazonka daryosi bu yashil olam o‘rtasidan egri-bugri oqadi.",note:"يَتَعَرَّجُ — egri-bugri oqmoq."},
{num:391,time:"00:36:14,800 --> 00:36:20,400",arabic:"حَامِلًا الْحَيَاةَ مِنْ جِبَالِ الْأَنْدِيزِ إِلَى شَوَاطِئِ الْأَطْلَسِيِّ",segs:[{ar:"حَامِلًا الْحَيَاةَ",uz:"hayotni olib borib"},{ar:"مِنْ جِبَالِ الْأَنْدِيزِ",uz:"And tog‘laridan"},{ar:"إِلَى شَوَاطِئِ الْأَطْلَسِيِّ",uz:"Atlantika sohillarigacha"}],full_uz:"Hayotni And tog‘laridan Atlantika sohillarigacha olib boradi.",note:"حَامِلٌ — olib boruvchi, ko‘taruvchi."},
{num:392,time:"00:36:20,400 --> 00:36:27,720",arabic:"وَفِي أَعْمَاقِهِ كَائِنَاتٌ غَامِضَةٌ تَبْدُو كَأَنَّهَا خَرَجَتْ مِنْ أُسْطُورَةٍ قَدِيمَةٍ",segs:[{ar:"وَفِي أَعْمَاقِهِ كَائِنَاتٌ غَامِضَةٌ",uz:"uning tubida sirli mavjudotlar bor"},{ar:"تَبْدُو كَأَنَّهَا خَرَجَتْ",uz:"go‘yo ular chiqqandek ko‘rinadi"},{ar:"مِنْ أُسْطُورَةٍ قَدِيمَةٍ",uz:"qadimiy afsonadan"}],full_uz:"Uning tubida go‘yo qadimiy afsonadan chiqqandek ko‘rinadigan sirli mavjudotlar bor.",note:"غَامِضٌ — sirli, noma’lum."},
{num:393,time:"00:36:27,720 --> 00:36:36,260",arabic:"أَنْ تَمْشِيَ فِي الْأَمَازُونِ هُوَ أَنْ تَخْطُوَ فِي قَلْبِ الْكَوْكَبِ نَفْسِهِ",segs:[{ar:"أَنْ تَمْشِيَ فِي الْأَمَازُونِ",uz:"Amazonkada yurish"},{ar:"هُوَ أَنْ تَخْطُوَ",uz:"bu qadam tashlashdir"},{ar:"فِي قَلْبِ الْكَوْكَبِ نَفْسِهِ",uz:"sayyoraning o‘z yuragida"}],full_uz:"Amazonkada yurish — sayyoraning o‘z yuragida qadam tashlashdir.",note:null},
{num:394,time:"00:36:36,260 --> 00:36:41,600",arabic:"حَيْثُ السِّيَادَةُ لِلطَّبِيعَةِ وَالْحَيَاةُ تَمْضِي بِلَا قُيُودٍ",segs:[{ar:"حَيْثُ السِّيَادَةُ لِلطَّبِيعَةِ",uz:"u yerda hukmronlik tabiatnikidir"},{ar:"وَالْحَيَاةُ تَمْضِي بِلَا قُيُودٍ",uz:"va hayot cheklovlarsiz davom etadi"}],full_uz:"U yerda hukmronlik tabiatniki, hayot esa cheklovlarsiz davom etadi.",note:"السِّيَادَةُ — hukmronlik, ustunlik."},
{num:395,time:"00:36:41,600 --> 00:36:46,600",arabic:"تَسْجُدُ فِي صَمْتٍ لِعَظَمَةِ الْخَالِقِ الَّذِي أَبْدَعَهَا",segs:[{ar:"تَسْجُدُ فِي صَمْتٍ",uz:"sukunatda sajda qiladi"},{ar:"لِعَظَمَةِ الْخَالِقِ",uz:"Yaratuvchining buyukligi oldida"},{ar:"الَّذِي أَبْدَعَهَا",uz:"uni ajoyib tarzda yaratgan"}],full_uz:"U uni ajoyib tarzda yaratgan Yaratuvchining buyukligi oldida sukunatda sajda qiladi.",note:"أَبْدَعَ — ajoyib, mislsiz tarzda yaratmoq."},
{num:396,time:"00:36:46,600 --> 00:36:56,180",arabic:"وَفِي قَلْبِ إِسْطَنْبُولَ حَيْثُ يَلْتَقِي الشَّرْقُ بِالْغَرْبِ",segs:[{ar:"وَفِي قَلْبِ إِسْطَنْبُولَ",uz:"Istanbulning yuragida"},{ar:"حَيْثُ يَلْتَقِي الشَّرْقُ بِالْغَرْبِ",uz:"Sharq G‘arb bilan uchrashadigan joyda"}],full_uz:"Istanbulning yuragida, Sharq G‘arb bilan uchrashadigan joyda.",note:null},
{num:397,time:"00:36:56,180 --> 00:37:01,880",arabic:"تَرْتَفِعُ قِبَابٌ وَمَآذِنُ تَمَسُّ السَّمَاءَ بِخُشُوعٍ مَهِيبٍ",segs:[{ar:"تَرْتَفِعُ قِبَابٌ وَمَآذِنُ",uz:"gumbazlar va minoralar yuksaladi"},{ar:"تَمَسُّ السَّمَاءَ",uz:"osmonga tegib"},{ar:"بِخُشُوعٍ مَهِيبٍ",uz:"haybatli xushu’ bilan"}],full_uz:"Gumbazlar va minoralar haybatli xushu’ bilan osmonga tegib yuksaladi.",note:"خُشُوعٌ — xushu’, kamtarlik va bo‘ysunish holati."},
{num:398,time:"00:37:01,880 --> 00:37:06,240",arabic:"إِنَّهُ الْمَسْجِدُ الْأَزْرَقُ السُّلْطَانُ أَحْمَدُ",segs:null,full_uz:"Bu Sulton Ahmad — Ko‘k masjid.",note:null},
{num:399,time:"00:37:06,239 --> 00:37:12,519",arabic:"تُحْفَةٌ مِنَ الْفَنِّ الْإِسْلَامِيِّ",segs:null,full_uz:"Islom san’atining bir durdonasi.",note:"تُحْفَةٌ — durdona, noyob asar."},
{num:400,time:"00:37:12,519 --> 00:37:16,619",arabic:"تَتَدَرَّجُ فِيهَا الْقِبَابُ فِي انْسِجَامٍ يُشْبِهُ الدُّعَاءَ",segs:[{ar:"تَتَدَرَّجُ فِيهَا الْقِبَابُ",uz:"unda gumbazlar pog‘onama-pog‘ona joylashadi"},{ar:"فِي انْسِجَامٍ يُشْبِهُ الدُّعَاءَ",uz:"duoga o‘xshash uyg‘unlikda"}],full_uz:"Undagi gumbazlar duoga o‘xshash uyg‘unlikda pog‘onama-pog‘ona joylashgan.",note:"تَتَدَرَّجُ — bosqichma-bosqich joylashmoq."},
{num:401,time:"00:37:16,619 --> 00:37:22,000",arabic:"وَتَمْتَدُّ الْمَآذِنُ السِّتُّ كَأَصَابِعِ صَلَاةٍ تُشِيرُ إِلَى السَّمَاءِ",segs:[{ar:"وَتَمْتَدُّ الْمَآذِنُ السِّتُّ",uz:"olti minora cho‘zilib turadi"},{ar:"كَأَصَابِعِ صَلَاةٍ",uz:"go‘yo ibodat barmoqlaridek"},{ar:"تُشِيرُ إِلَى السَّمَاءِ",uz:"osmonga ishora qiladigan"}],full_uz:"Olti minora go‘yo osmonga ishora qilayotgan ibodat barmoqlaridek cho‘zilib turadi.",note:null},
{num:402,time:"00:37:22,000 --> 00:37:28,639",arabic:"وَحِينَ تَخْطُو إِلَى الدَّاخِلِ",segs:null,full_uz:"Ichkariga qadam qo‘yganingizda.",note:"خَطَا — qadam tashlamoq."},
{num:403,time:"00:37:28,639 --> 00:37:31,839",arabic:"يَحْتَضِنُكَ بَحْرٌ مِنَ الزُّرْقَةِ وَالسَّكِينَةِ",segs:[{ar:"يَحْتَضِنُكَ بَحْرٌ",uz:"sizni bir dengiz bag‘riga oladi"},{ar:"مِنَ الزُّرْقَةِ وَالسَّكِينَةِ",uz:"moviylik va sokinlikdan iborat"}],full_uz:"Sizni moviylik va sokinlikdan iborat bir dengiz bag‘riga oladi.",note:"يَحْتَضِنُ — bag‘riga olmoq."},
{num:404,time:"00:37:31,839 --> 00:37:35,639",arabic:"أَكْثَرُ مِنْ عِشْرِينَ أَلْفَ بَلَاطَةٍ خَزَفِيَّةٍ زَرْقَاءَ",segs:[{ar:"أَكْثَرُ مِنْ عِشْرِينَ أَلْفَ",uz:"yigirma mingdan ortiq"},{ar:"بَلَاطَةٍ خَزَفِيَّةٍ زَرْقَاءَ",uz:"ko‘k sopol plitkalar"}],full_uz:"Yigirma mingdan ortiq ko‘k sopol plitkalar.",note:"بَلَاطَةٌ خَزَفِيَّةٌ — sopol plitka."},
{num:405,time:"00:37:35,639 --> 00:37:40,579",arabic:"تَتَوَهَّجُ تَحْتَ ضَوْءٍ يَتَسَلَّلُ مِنَ الزُّجَاجِ الْمُلَوَّنِ",segs:[{ar:"تَتَوَهَّجُ",uz:"yarqiraydi"},{ar:"تَحْتَ ضَوْءٍ",uz:"nur ostida"},{ar:"يَتَسَلَّلُ مِنَ الزُّجَاجِ الْمُلَوَّنِ",uz:"rangli oynadan sizib kiradigan"}],full_uz:"Ular rangli oynadan sizib kiradigan nur ostida yarqiraydi.",note:"يَتَسَلَّلُ — sekinlik bilan kirib kelmoq, sizib kirmoq."},
{num:406,time:"00:37:40,579 --> 00:37:44,119",arabic:"كَأَنَّ النُّورَ نَفْسَهُ يَسْجُدُ فِي صَمْتٍ",segs:[{ar:"كَأَنَّ النُّورَ نَفْسَهُ",uz:"go‘yo nurning o‘zi"},{ar:"يَسْجُدُ فِي صَمْتٍ",uz:"sukunatda sajda qilayotgandek"}],full_uz:"Go‘yo nurning o‘zi sukunatda sajda qilayotgandek.",note:null},
{num:407,time:"00:37:44,119 --> 00:37:50,759",arabic:"هُنَا لَا تَحْتَاجُ إِلَى كَلِمَاتٍ",segs:null,full_uz:"Bu yerda so‘zlarga ehtiyoj yo‘q.",note:null},
{num:408,time:"00:37:50,759 --> 00:37:54,639",arabic:"فَكُلُّ زُخْرُفَةٍ آيَةٌ وَكُلُّ انْعِكَاسٍ مِنَ الضَّوْءِ",segs:[{ar:"فَكُلُّ زُخْرُفَةٍ آيَةٌ",uz:"har bir bezak bir oyat"},{ar:"وَكُلُّ انْعِكَاسٍ مِنَ الضَّوْءِ",uz:"va nurning har bir aksi"}],full_uz:"Har bir bezak bir oyat, nurning har bir aksi.",note:"زُخْرُفَةٌ — bezak, naqsh."},
{num:409,time:"00:37:55,219 --> 00:37:58,019",arabic:"تَذْكِيرٌ بِجَمَالٍ مَصْدَرُهُ وَاحِدٌ",segs:[{ar:"تَذْكِيرٌ بِجَمَالٍ",uz:"go‘zallik haqidagi eslatma"},{ar:"مَصْدَرُهُ وَاحِدٌ",uz:"uning manbai yagona"}],full_uz:"Manbai yagona bo‘lgan go‘zallik haqidagi eslatma.",note:"مَصْدَرٌ — manba."},
{num:410,time:"00:37:58,019 --> 00:38:03,699",arabic:"الْخَالِقُ الَّذِي أَبْدَعَ هَذَا الْكَوْنَ بِمِيزَانٍ مِنْ نُورٍ وَتَنَاغُمٍ",segs:[{ar:"الْخَالِقُ",uz:"Yaratuvchi"},{ar:"الَّذِي أَبْدَعَ هَذَا الْكَوْنَ",uz:"bu koinotni ajoyib tarzda yaratgan"},{ar:"بِمِيزَانٍ مِنْ نُورٍ وَتَنَاغُمٍ",uz:"nur va uyg‘unlikdan iborat muvozanat bilan"}],full_uz:"Bu koinotni nur va uyg‘unlikdan iborat muvozanat bilan ajoyib tarzda yaratgan Yaratuvchi.",note:"تَنَاغُمٌ — uyg‘unlik, hamohanglik."},
{num:411,time:"00:38:05,639 --> 00:38:09,799",arabic:"يَعُمُّ الْهَوَاءَ سُكُونٌ مُقَدَّسٌ",segs:[{ar:"يَعُمُّ الْهَوَاءَ",uz:"havoni qoplaydi"},{ar:"سُكُونٌ مُقَدَّسٌ",uz:"muqaddas sukunat"}],full_uz:"Havoni muqaddas sukunat qoplaydi.",note:"يَعُمُّ — qoplamoq, keng tarqalmoq."},
{num:412,time:"00:38:09,799 --> 00:38:13,819",arabic:"يَحْمِلُ فِي طَيَّاتِهِ صَدَى قُرُونٍ مِنَ الصَّلَوَاتِ",segs:[{ar:"يَحْمِلُ فِي طَيَّاتِهِ",uz:"o‘z bag‘rida olib yuradi"},{ar:"صَدَى قُرُونٍ مِنَ الصَّلَوَاتِ",uz:"asrlar davom etgan ibodatlar aks-sadosini"}],full_uz:"U o‘z bag‘rida asrlar davom etgan ibodatlar aks-sadosini olib yuradi.",note:"طَيَّاتٌ — qatlamlar, bag‘irlar."},
{num:413,time:"00:38:13,819 --> 00:38:18,379",arabic:"وَهَمَسَاتِ الْخُشُوعِ الَّتِي عَلِقَتْ بَيْنَ جُدْرَانِ الزَّمَنِ",segs:[{ar:"وَهَمَسَاتِ الْخُشُوعِ",uz:"va xushu’ shivirlarini"},{ar:"الَّتِي عَلِقَتْ بَيْنَ جُدْرَانِ الزَّمَنِ",uz:"zamon devorlari orasida qolib ketgan"}],full_uz:"Va zamon devorlari orasida qolib ketgan xushu’ shivirlarini.",note:"هَمَسَةٌ — shivir, pichirlash."},
{num:414,time:"00:38:18,379 --> 00:38:26,139",arabic:"بُنِيَ الْمَسْجِدُ الْأَزْرَقُ فِي أَوَائِلِ الْقَرْنِ السَّابِعَ عَشَرَ",segs:[{ar:"بُنِيَ الْمَسْجِدُ الْأَزْرَقُ",uz:"Ko‘k masjid qurilgan"},{ar:"فِي أَوَائِلِ الْقَرْنِ السَّابِعَ عَشَرَ",uz:"o‘n yettinchi asr boshlarida"}],full_uz:"Ko‘k masjid o‘n yettinchi asr boshlarida qurilgan.",note:null},
{num:415,time:"00:38:26,139 --> 00:38:30,819",arabic:"لِيَقِفَ شَامِخًا فِي وَجْهِ جَارِهِ آيَا صُوفِيَا",segs:[{ar:"لِيَقِفَ شَامِخًا",uz:"salobat bilan turishi uchun"},{ar:"فِي وَجْهِ جَارِهِ",uz:"qo‘shnisining qarshisida"},{ar:"آيَا صُوفِيَا",uz:"Ayasofya"}],full_uz:"Qo‘shnisi Ayasofya qarshisida salobat bilan turishi uchun.",note:null},
{num:416,time:"00:38:30,819 --> 00:38:35,579",arabic:"وَكَأَنَّهُمَا حِوَارٌ صَامِتٌ بَيْنَ الْإِيمَانِ وَالْفَنِّ",segs:[{ar:"وَكَأَنَّهُمَا حِوَارٌ صَامِتٌ",uz:"go‘yo ular jimjit bir suhbat"},{ar:"بَيْنَ الْإِيمَانِ وَالْفَنِّ",uz:"iymon va san’at o‘rtasidagi"}],full_uz:"Go‘yo ular iymon va san’at o‘rtasidagi jimjit bir suhbatdek.",note:"حِوَارٌ — suhbat, muloqot."},
{num:417,time:"00:38:35,579 --> 00:38:40,799",arabic:"يَصْنَعَانِ مَعًا أَحَدَ أَبْهَى مَشَاهِدِ الْأُفُقِ فِي إِسْطَنْبُولَ",segs:[{ar:"يَصْنَعَانِ مَعًا",uz:"ikkalasi birga yaratadi"},{ar:"أَحَدَ أَبْهَى مَشَاهِدِ الْأُفُقِ",uz:"ufqning eng go‘zal manzaralaridan birini"},{ar:"فِي إِسْطَنْبُولَ",uz:"Istanbulda"}],full_uz:"Ular birga Istanbuldagi ufqning eng go‘zal manzaralaridan birini yaratadi.",note:"أَبْهَى — eng go‘zal, eng yorqin."},
{num:418,time:"00:38:40,799 --> 00:38:48,340",arabic:"خَارِجَ الْأَسْوَارِ تَدِبُّ الْحَيَاةُ فِي السَّاحَاتِ",segs:[{ar:"خَارِجَ الْأَسْوَارِ",uz:"devorlar tashqarisida"},{ar:"تَدِبُّ الْحَيَاةُ فِي السَّاحَاتِ",uz:"maydonlarda hayot jonlanadi"}],full_uz:"Devorlar tashqarisida maydonlarda hayot jonlanadi.",note:"تَدِبُّ — jonlanmoq, harakat boshlanmoq."},
{num:419,time:"00:38:48,340 --> 00:38:52,860",arabic:"وَصَوْتُ الْأَذَانِ يَعْلُو فَوْقَ شَوَارِعِ الْمَدِينَةِ الْقَدِيمَةِ",segs:[{ar:"وَصَوْتُ الْأَذَانِ يَعْلُو",uz:"azon ovozi ko‘tariladi"},{ar:"فَوْقَ شَوَارِعِ الْمَدِينَةِ الْقَدِيمَةِ",uz:"qadimiy shahar ko‘chalari uzra"}],full_uz:"Azon ovozi qadimiy shahar ko‘chalari uzra yangraydi.",note:"يَعْلُو — ko‘tarilmoq, baland eshitilmoq."},
{num:420,time:"00:38:52,860 --> 00:38:58,639",arabic:"يَرْبِطُ بَيْنَ الْمَاضِي وَالْحَاضِرِ بِنَغْمَةٍ وَاحِدَةٍ مِنَ الْإِيمَانِ",segs:[{ar:"يَرْبِطُ بَيْنَ الْمَاضِي وَالْحَاضِرِ",uz:"o‘tmish va bugunni bog‘laydi"},{ar:"بِنَغْمَةٍ وَاحِدَةٍ مِنَ الْإِيمَانِ",uz:"iymonning yagona ohangi bilan"}],full_uz:"U iymonning yagona ohangi bilan o‘tmish va bugunni bog‘laydi.",note:"نَغْمَةٌ — ohang."},
{num:421,time:"00:38:58,639 --> 00:39:07,059",arabic:"عَلَى الْحُدُودِ الْفَاصِلَةِ بَيْنَ زَامْبِيَا وَزِمْبَابْوِي",segs:[{ar:"عَلَى الْحُدُودِ الْفَاصِلَةِ",uz:"ajratib turuvchi chegarada"},{ar:"بَيْنَ زَامْبِيَا وَزِمْبَابْوِي",uz:"Zambiya va Zimbabve o‘rtasidagi"}],full_uz:"Zambiya va Zimbabve o‘rtasidagi chegarada.",note:"فَاصِلٌ — ajratuvchi."},
{num:422,time:"00:39:07,059 --> 00:39:13,000",arabic:"يَنْحَدِرُ نَهْرُ زَامْبِيزِي فِي مَشْهَدٍ مِنْ أَعْظَمِ مَشَاهِدِ الْخَلْقِ",segs:[{ar:"يَنْحَدِرُ نَهْرُ زَامْبِيزِي",uz:"Zambezi daryosi quyiladi"},{ar:"فِي مَشْهَدٍ مِنْ أَعْظَمِ مَشَاهِدِ الْخَلْقِ",uz:"yaratilishning eng buyuk manzaralaridan birida"}],full_uz:"Zambezi daryosi yaratilishning eng buyuk manzaralaridan birida quyiladi.",note:"يَنْحَدِرُ — pastga tushmoq, quyilmoq."},
{num:423,time:"00:39:13,000 --> 00:39:15,299",arabic:"إِنَّهَا شَلَّالَاتُ فِيكْتُورِيَا",segs:null,full_uz:"Bu Viktoriya sharsharalaridir.",note:null},
{num:424,time:"00:39:15,299 --> 00:39:20,619",arabic:"وَاحِدَةٌ مِنْ أَعْتَى وَأَبْهَى عَجَائِبِ الطَّبِيعَةِ عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"وَاحِدَةٌ مِنْ أَعْتَى عَجَائِبِ الطَّبِيعَةِ",uz:"tabiatning eng qudratli mo‘jizalaridan biri"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzidagi"}],full_uz:"Yer yuzidagi tabiatning eng qudratli va eng go‘zal mo‘jizalaridan biridir.",note:"أَعْتَى — eng kuchli, eng dahshatli."},
{num:425,time:"00:39:20,619 --> 00:39:27,319",arabic:"يُسَمِّيهَا أَهْلُهَا مُوسِي أُوَا تُونْيَا",segs:[{ar:"يُسَمِّيهَا أَهْلُهَا",uz:"mahalliy aholi uni ataydi"},{ar:"مُوسِي أُوَا تُونْيَا",uz:"Mosi-oa-Tunya"}],full_uz:"Mahalliy aholi uni Mosi-oa-Tunya deb ataydi.",note:"مُوسِي أُوَا تُونْيَا — “momaqaldiroq tutuni” ma’nosidagi mahalliy nom."},
{num:426,time:"00:39:27,320 --> 00:39:29,800",arabic:"أَيْ الدُّخَانُ الَّذِي يَرْعُدُ",segs:[{ar:"أَيْ الدُّخَانُ",uz:"ya’ni tutun"},{ar:"الَّذِي يَرْعُدُ",uz:"momaqaldiroqdek gumburlaydigan"}],full_uz:"Ya’ni momaqaldiroqdek gumburlaydigan tutun.",note:"يَرْعُدُ — momaqaldiroqdek gumburlamoq."},
{num:427,time:"00:39:29,800 --> 00:39:33,120",arabic:"وَهَذَا الِاسْمُ وَحْدَهُ يَرْوِي الْقِصَّةَ",segs:[{ar:"وَهَذَا الِاسْمُ وَحْدَهُ",uz:"va shu nomning o‘zi"},{ar:"يَرْوِي الْقِصَّةَ",uz:"hikoyani so‘zlaydi"}],full_uz:"Shu nomning o‘ziyoq hikoyani so‘zlaydi.",note:null},
{num:428,time:"00:39:33,120 --> 00:39:39,500",arabic:"مِنِ ارْتِفَاعٍ يَزِيدُ عَلَى مِائَةِ مِتْرٍ",segs:[{ar:"مِنِ ارْتِفَاعٍ",uz:"yuzadan balandlikda"},{ar:"يَزِيدُ عَلَى مِائَةِ مِتْرٍ",uz:"yuz metrdan oshadigan"}],full_uz:"Yuz metrdan oshadigan balandlikdan.",note:null},
{num:429,time:"00:39:39,500 --> 00:39:43,420",arabic:"يَهْوِي النَّهْرُ الْهَادِرُ فِي سِتَارٍ أَبْيَضَ عَظِيمٍ",segs:[{ar:"يَهْوِي النَّهْرُ الْهَادِرُ",uz:"gumburlab oqayotgan daryo qulaydi"},{ar:"فِي سِتَارٍ أَبْيَضَ عَظِيمٍ",uz:"ulkan oq pardaga"}],full_uz:"Gumburlab oqayotgan daryo ulkan oq parda bo‘lib qulaydi.",note:"هَادِرٌ — kuchli shovqin bilan oqadigan."},
{num:430,time:"00:39:43,420 --> 00:39:46,420",arabic:"يَمْتَدُّ قَرَابَةَ كِيلُومِتْرَيْنِ",segs:null,full_uz:"Qariyb ikki kilometrga cho‘ziladi.",note:"قَرَابَةُ — qariyb, deyarli."},
{num:431,time:"00:39:46,420 --> 00:39:49,780",arabic:"فَتَتَعَالَى سُحُبُ الرَّذَاذِ إِلَى السَّمَاءِ",segs:[{ar:"فَتَتَعَالَى سُحُبُ الرَّذَاذِ",uz:"shunda mayda suv tomchilari bulutlari ko‘tariladi"},{ar:"إِلَى السَّمَاءِ",uz:"osmonga"}],full_uz:"Shunda mayda suv tomchilari bulutlari osmonga ko‘tariladi.",note:"الرَّذَاذُ — mayda suv tomchilari, sachrama."},
{num:432,time:"00:39:49,780 --> 00:39:52,940",arabic:"وَتَتَلَوَّنُ بِالْأَقْوَاسِ وَالْأَنْوَارِ",segs:[{ar:"وَتَتَلَوَّنُ",uz:"ranglarga kiradi"},{ar:"بِالْأَقْوَاسِ وَالْأَنْوَارِ",uz:"kamalaklar va nurlar bilan"}],full_uz:"Ular kamalaklar va nurlar bilan ranglarga kiradi.",note:"تَتَلَوَّنُ — rangga kirib bormoq, tuslanmoq."},
{num:433,time:"00:39:52,940 --> 00:39:58,119",arabic:"كَأَنَّ الْغَيْمَ قَدْ نَزَلَ إِلَى الْأَرْضِ لِيُسَبِّحَ اللَّهَ فِي هَدِيرِ الْمَاءِ",segs:[{ar:"كَأَنَّ الْغَيْمَ قَدْ نَزَلَ إِلَى الْأَرْضِ",uz:"go‘yo bulut yerga tushgandek"},{ar:"لِيُسَبِّحَ اللَّهَ",uz:"Allohni tasbeh etish uchun"},{ar:"فِي هَدِيرِ الْمَاءِ",uz:"suvning gumburlashida"}],full_uz:"Go‘yo bulut suvning gumburlashida Allohni tasbeh etish uchun yerga tushgandek.",note:"هَدِيرٌ — kuchli gumburlash, guvillash."},
{num:434,time:"00:39:58,119 --> 00:40:09,800",arabic:"وَمِنَ الْأَعْلَى تَبْدُو الشَّلَّالَاتُ خَطًّا مِنَ الْفِضَّةِ يَشُقُّ قَلْبَ الْغَابَةِ الْخَضْرَاءِ",segs:[{ar:"وَمِنَ الْأَعْلَى",uz:"yuqoridan"},{ar:"تَبْدُو الشَّلَّالَاتُ خَطًّا مِنَ الْفِضَّةِ",uz:"sharsharalar kumush chiziqdek ko‘rinadi"},{ar:"يَشُقُّ قَلْبَ الْغَابَةِ الْخَضْرَاءِ",uz:"yashil o‘rmon yuragini yorib o‘tadigan"}],full_uz:"Yuqoridan sharsharalar yashil o‘rmon yuragini yorib o‘tuvchi kumush chiziqdek ko‘rinadi.",note:"يَشُقُّ — yorib o‘tmoq."},
{num:435,time:"00:40:09,800 --> 00:40:15,940",arabic:"مَشْهَدًا يُذَكِّرُكَ أَنَّ الْجَلَالَ وَالْجَمَالَ وَجْهَانِ لِصَنْعَةٍ وَاحِدَةٍ",segs:[{ar:"مَشْهَدًا يُذَكِّرُكَ",uz:"sizga eslatadigan manzara"},{ar:"أَنَّ الْجَلَالَ وَالْجَمَالَ",uz:"ulug‘vorlik va go‘zallik"},{ar:"وَجْهَانِ لِصَنْعَةٍ وَاحِدَةٍ",uz:"bir ijodning ikki yuzidir"}],full_uz:"Ulug‘vorlik va go‘zallik bir ijodning ikki yuzi ekanini eslatadigan manzara.",note:"وَجْهَانِ — ikki yuz, ikki tomon."},
{num:436,time:"00:40:22,940 --> 00:40:30,980",arabic:"نَهْبِطُ إِلَى قَلْبِ الصَّحْرَاءِ الذَّهَبِيَّةِ",segs:[{ar:"نَهْبِطُ",uz:"tushamiz"},{ar:"إِلَى قَلْبِ الصَّحْرَاءِ الذَّهَبِيَّةِ",uz:"oltin sahroning yuragiga"}],full_uz:"Oltin sahroning yuragiga tushamiz.",note:"هَبَطَ — tushmoq, pastga kelmoq."},
{num:437,time:"00:40:30,980 --> 00:40:34,960",arabic:"حَيْثُ تَقِفُ أَقْدَمُ الْمُعْجِزَاتِ عَلَى وَجْهِ الْأَرْضِ",segs:[{ar:"حَيْثُ تَقِفُ أَقْدَمُ الْمُعْجِزَاتِ",uz:"u yerda eng qadimiy mo‘jizalar turadi"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"}],full_uz:"U yerda yer yuzidagi eng qadimiy mo‘jizalar turadi.",note:"أَقْدَمُ — eng qadimiy."},
{num:438,time:"00:40:34,960 --> 00:40:37,619",arabic:"شَامِخَةً فِي صَمْتٍ مَهِيبٍ",segs:null,full_uz:"Haybatli sukunatda salobat bilan turib.",note:"شَامِخٌ — baland, salobatli."},
{num:439,time:"00:40:37,619 --> 00:40:40,380",arabic:"إِنَّهَا أَهْرَامَاتُ الْجِيزَةِ",segs:null,full_uz:"Bu Giza ehromlaridir.",note:null},
{num:440,time:"00:40:40,380 --> 00:40:43,980",arabic:"عَلَى حَافَّةِ صَحْرَاءِ مِصْرَ الْكُبْرَى",segs:null,full_uz:"Misrning Buyuk sahrosi chekkasida.",note:null},
{num:441,time:"00:40:43,980 --> 00:40:48,079",arabic:"آخِرُ مَا تَبَقَّى مِنْ عَجَائِبِ الْعَالَمِ الْقَدِيمِ",segs:[{ar:"آخِرُ مَا تَبَقَّى",uz:"saqlanib qolgan so‘nggi"},{ar:"مِنْ عَجَائِبِ الْعَالَمِ الْقَدِيمِ",uz:"qadimgi dunyo mo‘jizalaridan"}],full_uz:"Qadimgi dunyo mo‘jizalaridan saqlanib qolgan yagona narsa.",note:"تَبَقَّى — saqlanib qolmoq."},
{num:442,time:"00:40:48,079 --> 00:40:54,500",arabic:"شُيِّدَتْ مُنْذُ أَكْثَرَ مِنْ أَرْبَعَةِ آلَافٍ وَخَمْسِمِائَةِ عَامٍ",segs:[{ar:"شُيِّدَتْ",uz:"qurilgan"},{ar:"مُنْذُ أَكْثَرَ مِنْ أَرْبَعَةِ آلَافٍ وَخَمْسِمِائَةِ عَامٍ",uz:"to‘rt ming besh yuz yildan ortiq vaqt oldin"}],full_uz:"Ular to‘rt ming besh yuz yildan ortiq vaqt oldin qurilgan.",note:"شَيَّدَ — bunyod etmoq, mahkam qurmoq."},
{num:443,time:"00:40:54,500 --> 00:40:58,039",arabic:"لِتَكُونَ مَقَابِرَ لِلْمُلُوكِ الْفَرَاعِنَةِ",segs:[{ar:"لِتَكُونَ مَقَابِرَ",uz:"maqbaralar bo‘lishi uchun"},{ar:"لِلْمُلُوكِ الْفَرَاعِنَةِ",uz:"fir’avn podshohlari uchun"}],full_uz:"Fir’avn podshohlari uchun maqbaralar bo‘lishi uchun.",note:"مَقْبَرَةٌ — maqbara, qabr."},
{num:444,time:"00:40:58,039 --> 00:41:01,559",arabic:"وَطَرِيقًا لِأَرْوَاحِهِمْ نَحْوَ الْحَيَاةِ الْآخِرَةِ",segs:[{ar:"وَطَرِيقًا لِأَرْوَاحِهِمْ",uz:"va ularning ruhlari uchun yo‘l"},{ar:"نَحْوَ الْحَيَاةِ الْآخِرَةِ",uz:"oxirat hayoti tomon"}],full_uz:"Va ruhlari uchun oxirat hayoti tomon yo‘l sifatida.",note:null},
{num:445,time:"00:41:01,559 --> 00:41:09,400",arabic:"أَضْخَمُهَا هَرَمُ خُوفُوَ الْعَظِيمُ",segs:[{ar:"أَضْخَمُهَا",uz:"ularning eng kattasi"},{ar:"هَرَمُ خُوفُوَ الْعَظِيمُ",uz:"Buyuk Xufu piramidasi"}],full_uz:"Ularning eng kattasi — Buyuk Xufu piramidasidir.",note:"أَضْخَمُ — eng katta, eng ulkan."},
{num:446,time:"00:41:09,400 --> 00:41:13,900",arabic:"يَرْتَفِعُ قَرَابَةَ مِائَةٍ وَخَمْسِينَ مِتْرًا",segs:null,full_uz:"Qariyb yuz ellik metr balandlikka ko‘tariladi.",note:"قَرَابَةَ — qariyb, deyarli."},
{num:447,time:"00:41:13,900 --> 00:41:19,599",arabic:"بُنِيَ بِدِقَّةٍ مُذْهِلَةٍ مِنْ أَكْثَرَ مِنْ مِلْيُونَيْ حَجَرٍ مِنَ الْحَجَرِ الْجِيرِيِّ",segs:[{ar:"بُنِيَ بِدِقَّةٍ مُذْهِلَةٍ",uz:"hayratlanarli aniqlik bilan qurilgan"},{ar:"مِنْ أَكْثَرَ مِنْ مِلْيُونَيْ حَجَرٍ",uz:"ikki milliondan ortiq toshdan"},{ar:"مِنَ الْحَجَرِ الْجِيرِيِّ",uz:"ohaktoshdan"}],full_uz:"U ikki milliondan ortiq ohaktoshdan hayratlanarli aniqlik bilan qurilgan.",note:"الْحَجَرُ الْجِيرِيُّ — ohaktosh."},
{num:448,time:"00:41:19,599 --> 00:41:23,400",arabic:"فِي هَنْدَسَةٍ تُثِيرُ الدَّهْشَةَ حَتَّى الْيَوْمَ",segs:[{ar:"فِي هَنْدَسَةٍ",uz:"me’moriy tuzilishi bilan"},{ar:"تُثِيرُ الدَّهْشَةَ حَتَّى الْيَوْمَ",uz:"bugungi kungacha hayrat uyg‘otadigan"}],full_uz:"Bugungi kungacha hayrat uyg‘otadigan me’moriy tuzilishda.",note:"تُثِيرُ الدَّهْشَةَ — hayrat uyg‘otmoq."},
{num:449,time:"00:41:23,400 --> 00:41:34,280",arabic:"وَعَلَى مُقْرُبَةٍ مِنْهَا يَقِفُ أَبُو الْهَوْلِ بِجَسَدِ أَسَدٍ وَوَجْهِ مَلِكٍ",segs:[{ar:"وَعَلَى مُقْرُبَةٍ مِنْهَا",uz:"uning yaqinida"},{ar:"يَقِفُ أَبُو الْهَوْلِ",uz:"Abu al-Havl turadi"},{ar:"بِجَسَدِ أَسَدٍ وَوَجْهِ مَلِكٍ",uz:"sher tanasi va podsho yuziga ega"}],full_uz:"Uning yaqinida sher tanasi va podsho yuziga ega Abu al-Havl turadi.",note:"مُقْرُبَةٌ — yaqin joy."},
{num:450,time:"00:41:34,280 --> 00:41:37,400",arabic:"يَحْرُسُ الرِّمَالَ مُنْذُ آلَافِ السِّنِينَ",segs:[{ar:"يَحْرُسُ الرِّمَالَ",uz:"qumlarni qo‘riqlaydi"},{ar:"مُنْذُ آلَافِ السِّنِينَ",uz:"minglab yillardan beri"}],full_uz:"U minglab yillardan beri qumlarni qo‘riqlab turibdi.",note:"حَرَسَ — qo‘riqlamoq."},
{num:451,time:"00:41:37,400 --> 00:41:42,480",arabic:"صَامِتًا كَأَنَّهُ شَاهِدٌ عَلَى مُرُورِ الزَّمَانِ بِأَسْرِهِ",segs:[{ar:"صَامِتًا",uz:"jim holda"},{ar:"كَأَنَّهُ شَاهِدٌ",uz:"go‘yo guvohdek"},{ar:"عَلَى مُرُورِ الزَّمَانِ بِأَسْرِهِ",uz:"butun zamon o‘tishiga"}],full_uz:"Jim holda, go‘yo butun zamonning o‘tishiga guvohdek.",note:"بِأَسْرِهِ — butunlay, to‘lig‘icha."},
{num:452,time:"00:41:43,900 --> 00:41:50,740",arabic:"فِي حَضْرَةِ الْأَهْرَامَاتِ تَشْعُرُ أَنَّ الْحِجَارَةَ تَنْطِقُ",segs:[{ar:"فِي حَضْرَةِ الْأَهْرَامَاتِ",uz:"ehromlar huzurida"},{ar:"تَشْعُرُ أَنَّ الْحِجَارَةَ تَنْطِقُ",uz:"toshlar gapirayotgandek his qilasiz"}],full_uz:"Ehromlar huzurida toshlar gapirayotgandek his qilasiz.",note:"حَضْرَةٌ — huzur, oldi."},
{num:453,time:"00:41:50,740 --> 00:41:55,380",arabic:"تَحْكِي عَنْ حَضَارَةٍ عَظِيمَةٍ أَدْرَكَتْ فَنَاءَ الْجَسَدِ",segs:[{ar:"تَحْكِي عَنْ حَضَارَةٍ عَظِيمَةٍ",uz:"buyuk sivilizatsiya haqida hikoya qiladi"},{ar:"أَدْرَكَتْ فَنَاءَ الْجَسَدِ",uz:"tananing fanoga ketishini anglagan"}],full_uz:"Ular tana foniy ekanini anglagan buyuk sivilizatsiya haqida hikoya qiladi.",note:"فَنَاءٌ — yo‘q bo‘lish, fanolik."},
{num:454,time:"00:41:55,380 --> 00:41:58,139",arabic:"لَكِنَّهَا سَعَتْ لِتَخْلِيدِ الرُّوحِ",segs:[{ar:"لَكِنَّهَا سَعَتْ",uz:"ammo u intildi"},{ar:"لِتَخْلِيدِ الرُّوحِ",uz:"ruhni abadiylashtirishga"}],full_uz:"Ammo u ruhni abadiylashtirishga intildi.",note:"خَلَّدَ — abadiylashtirmoq."},
{num:455,time:"00:41:58,139 --> 00:42:01,460",arabic:"وَهُنَاكَ تَحْتَ شَمْسِ الصَّحْرَاءِ",segs:null,full_uz:"Va u yerda, sahro quyoshi ostida.",note:null},
{num:456,time:"00:42:01,460 --> 00:42:06,240",arabic:"يَهْمِسُ الصَّمْتُ بِأَنَّ الْخُلُودَ لَا يُمْنَحُ إِلَّا لِمَنْ خَلَقَهُ",segs:[{ar:"يَهْمِسُ الصَّمْتُ",uz:"sukunat shivirlaydi"},{ar:"بِأَنَّ الْخُلُودَ",uz:"abadiylik"},{ar:"لَا يُمْنَحُ إِلَّا لِمَنْ خَلَقَهُ",uz:"uni yaratganga berilishini"}],full_uz:"Sukunat abadiylik faqat uni Yaratganga tegishli ekanini shivirlaydi.",note:"الْخُلُودُ — abadiylik, boqiylik."},
{num:457,time:"00:42:06,240 --> 00:42:11,960",arabic:"نُبْحِرُ إِلَى الْأَدْرِيَاتِي",segs:null,full_uz:"Adriatika tomon suzamiz.",note:null},
{num:458,time:"00:42:11,960 --> 00:42:13,480",arabic:"إِلَى دُوبْرُوفْنِيكَ",segs:null,full_uz:"Dubrovnikka.",note:null},
{num:459,time:"00:42:13,480 --> 00:42:15,880",arabic:"لُؤْلُؤَةُ الْبَحْرِ الْمُتَوَسِّطِ",segs:null,full_uz:"O‘rta Yer dengizining durdonasi.",note:"لُؤْلُؤَةٌ — dur, durdona."},
{num:460,time:"00:42:15,880 --> 00:42:20,400",arabic:"حَيْثُ يَلْتَقِي التَّارِيخُ بِالْجَمَالِ عِنْدَ حَافَّةِ الْمَوْجِ",segs:[{ar:"حَيْثُ يَلْتَقِي التَّارِيخُ بِالْجَمَالِ",uz:"tarix go‘zallik bilan uchrashadigan joyda"},{ar:"عِنْدَ حَافَّةِ الْمَوْجِ",uz:"to‘lqin chekkasida"}],full_uz:"Tarix go‘zallik bilan to‘lqin chekkasida uchrashadigan joyda.",note:null},
{num:461,time:"00:42:20,400 --> 00:42:29,240",arabic:"مَدِينَةٌ قَدِيمَةٌ مُحَصَّنَةٌ بِأَسْوَارٍ عَظِيمَةٍ",segs:[{ar:"مَدِينَةٌ قَدِيمَةٌ",uz:"qadimiy shahar"},{ar:"مُحَصَّنَةٌ بِأَسْوَارٍ عَظِيمَةٍ",uz:"ulkan devorlar bilan mustahkamlangan"}],full_uz:"Ulkan devorlar bilan mustahkamlangan qadimiy shahar.",note:"مُحَصَّنٌ — mustahkamlangan, qo‘rg‘on qilingan."},
{num:462,time:"00:42:29,240 --> 00:42:33,199",arabic:"تَتَوَهَّجُ أَسْقُفُهَا الْحَمْرَاءُ تَحْتَ شَمْسِ الْبَحْرِ",segs:[{ar:"تَتَوَهَّجُ أَسْقُفُهَا الْحَمْرَاءُ",uz:"uning qizil tomlari yarqiraydi"},{ar:"تَحْتَ شَمْسِ الْبَحْرِ",uz:"dengiz quyoshi ostida"}],full_uz:"Uning qizil tomlari dengiz quyoshi ostida yarqiraydi.",note:null},
{num:463,time:"00:42:33,199 --> 00:42:38,079",arabic:"وَشَوَارِعُهَا الرُّخَامِيَّةُ تَرْوِي حِكَايَاتِ قُرُونٍ مَضَتْ",segs:[{ar:"وَشَوَارِعُهَا الرُّخَامِيَّةُ",uz:"va uning marmar ko‘chalari"},{ar:"تَرْوِي حِكَايَاتِ قُرُونٍ مَضَتْ",uz:"o‘tib ketgan asrlar hikoyalarini so‘zlaydi"}],full_uz:"Uning marmar ko‘chalari o‘tib ketgan asrlar hikoyalarini so‘zlaydi.",note:null},
{num:464,time:"00:42:38,079 --> 00:42:45,759",arabic:"وَأَنْتَ تَسِيرُ بَيْنَ أَزِقَّتِهَا الْحَجَرِيَّةِ",segs:null,full_uz:"Siz uning tosh ko‘chalari orasida yurganingizda.",note:"أَزِقَّةٌ — tor ko‘chalar."},
{num:465,time:"00:42:45,759 --> 00:42:50,079",arabic:"تَسْمَعُ صَدَى الْخُطُوَاتِ يَمْتَزِجُ بِرَائِحَةِ الْمِلْحِ",segs:[{ar:"تَسْمَعُ صَدَى الْخُطُوَاتِ",uz:"qadamlar aks-sadosini eshitasiz"},{ar:"يَمْتَزِجُ بِرَائِحَةِ الْمِلْحِ",uz:"tuz hidiga qorishadigan"}],full_uz:"Qadamlar aks-sadosining tuz hidi bilan qorishganini eshitasiz.",note:"صَدَى — aks-sado."},
{num:466,time:"00:42:50,079 --> 00:42:53,819",arabic:"كَأَنَّ الْبَحْرَ نَفْسَهُ يَتَنَفَّسُ بَيْنَ الْجُدْرَانِ",segs:[{ar:"كَأَنَّ الْبَحْرَ نَفْسَهُ",uz:"go‘yo dengizning o‘zi"},{ar:"يَتَنَفَّسُ بَيْنَ الْجُدْرَانِ",uz:"devorlar orasida nafas olayotgandek"}],full_uz:"Go‘yo dengizning o‘zi devorlar orasida nafas olayotgandek.",note:null},
{num:467,time:"00:42:53,819 --> 00:43:01,880",arabic:"مِنْ قَصْرِ الْحَاكِمِ إِلَى الْمَقَاهِي الْمُطِلَّةِ عَلَى الْمِينَاءِ",segs:[{ar:"مِنْ قَصْرِ الْحَاكِمِ",uz:"hokim saroyidan"},{ar:"إِلَى الْمَقَاهِي الْمُطِلَّةِ عَلَى الْمِينَاءِ",uz:"bandargohga qaragan kafelargacha"}],full_uz:"Hokim saroyidan bandargohga qaragan kafelargacha.",note:"مُطِلٌّ عَلَى — qarab turgan, ko‘rinishi tushadigan."},
{num:468,time:"00:43:01,880 --> 00:43:05,480",arabic:"كُلُّ زَاوِيَةٍ هُنَا تَحْكِي قِصَّةً",segs:[{ar:"كُلُّ زَاوِيَةٍ هُنَا",uz:"bu yerdagi har bir burchak"},{ar:"تَحْكِي قِصَّةً",uz:"bir hikoya so‘zlaydi"}],full_uz:"Bu yerdagi har bir burchak bir hikoya so‘zlaydi.",note:null},
{num:469,time:"00:43:05,480 --> 00:43:09,679",arabic:"وَكُلُّ نَافِذَةٍ تُطِلُّ عَلَى بَحْرٍ بِلَا نِهَايَةٍ",segs:[{ar:"وَكُلُّ نَافِذَةٍ",uz:"va har bir deraza"},{ar:"تُطِلُّ عَلَى بَحْرٍ بِلَا نِهَايَةٍ",uz:"cheksiz dengizga qaraydi"}],full_uz:"Va har bir deraza cheksiz dengizga qaraydi.",note:null},
{num:470,time:"00:43:09,679 --> 00:43:16,900",arabic:"اصْعَدْ فَوْقَ الْأَسْوَارِ الْقَدِيمَةِ",segs:[{ar:"اصْعَدْ",uz:"ko‘tariling"},{ar:"فَوْقَ الْأَسْوَارِ الْقَدِيمَةِ",uz:"qadimiy devorlar ustiga"}],full_uz:"Qadimiy devorlar ustiga ko‘tariling.",note:"صَعِدَ — ko‘tarilmoq."},
{num:471,time:"00:43:16,900 --> 00:43:22,199",arabic:"وَانْظُرْ إِلَى زُرْقَةِ الْأَدْرِيَاتِ وَهِيَ تَمْتَدُّ حَتَّى الْأُفُقِ",segs:[{ar:"وَانْظُرْ إِلَى زُرْقَةِ الْأَدْرِيَاتِ",uz:"Adriatika moviyligiga qarang"},{ar:"وَهِيَ تَمْتَدُّ حَتَّى الْأُفُقِ",uz:"u ufqqacha cho‘zilib yotgan"}],full_uz:"Adriatikaning ufqqacha cho‘zilgan moviyligiga qarang.",note:"زُرْقَةٌ — moviylik."},
{num:472,time:"00:43:22,199 --> 00:43:25,960",arabic:"فَتَشْعُرُ أَنَّكَ تَقِفُ عَلَى حُدُودِ الْحُلْمِ",segs:[{ar:"فَتَشْعُرُ أَنَّكَ تَقِفُ",uz:"shunda o‘zingiz turganingizni his qilasiz"},{ar:"عَلَى حُدُودِ الْحُلْمِ",uz:"tush chegarasida"}],full_uz:"Shunda o‘zingizni go‘yo tush chegarasida turgandek his qilasiz.",note:null},
{num:473,time:"00:43:25,960 --> 00:43:31,860",arabic:"حَيْثُ الْبَحْرُ يَحْرُسُ الْمَدِينَةَ كَأُمٍّ تَحْتَضِنُ أَبْنَاءَهَا",segs:[{ar:"حَيْثُ الْبَحْرُ يَحْرُسُ الْمَدِينَةَ",uz:"u yerda dengiz shaharni qo‘riqlaydi"},{ar:"كَأُمٍّ تَحْتَضِنُ أَبْنَاءَهَا",uz:"farzandlarini bag‘riga olgan ona kabi"}],full_uz:"U yerda dengiz farzandlarini bag‘riga olgan ona kabi shaharni qo‘riqlaydi.",note:null},
{num:474,time:"00:43:35,480 --> 00:43:42,119",arabic:"فِي اللَّيْلِ حِينَ تُضَاءُ الشَّوَارِعُ بِالْفَوَانِيسِ",segs:[{ar:"فِي اللَّيْلِ",uz:"kechasi"},{ar:"حِينَ تُضَاءُ الشَّوَارِعُ بِالْفَوَانِيسِ",uz:"ko‘chalar chiroqlar bilan yoritilganda"}],full_uz:"Kechasi ko‘chalar chiroqlar bilan yoritilganda.",note:"فَانُوسٌ — fonus, chiroq."},
{num:475,time:"00:43:42,119 --> 00:43:46,460",arabic:"تَتَحَوَّلُ دُوبْرُوفْنِيكُ إِلَى قَصِيدَةٍ مِنْ ضَوْءٍ وَحَنِينٍ",segs:[{ar:"تَتَحَوَّلُ دُوبْرُوفْنِيكُ",uz:"Dubrovnik aylanadi"},{ar:"إِلَى قَصِيدَةٍ مِنْ ضَوْءٍ وَحَنِينٍ",uz:"nur va sog‘inchdan iborat she’rga"}],full_uz:"Dubrovnik nur va sog‘inchdan iborat she’rga aylanadi.",note:"حَنِينٌ — sog‘inch, intilish."},
{num:476,time:"00:43:46,460 --> 00:43:49,300",arabic:"كَأَنَّهَا زَمَنٌ لَمْ يَمْضِ",segs:null,full_uz:"Go‘yo o‘tib ketmagan bir zamondek.",note:"مَضَى — o‘tib ketmoq."},
{num:477,time:"00:43:49,300 --> 00:43:51,760",arabic:"بَلْ مَا زَالَ يَرْوِي نَفْسَهُ بِهُدُوءٍ",segs:[{ar:"بَلْ مَا زَالَ",uz:"balki hamon"},{ar:"يَرْوِي نَفْسَهُ بِهُدُوءٍ",uz:"o‘zini sokinlik bilan hikoya qiladi"}],full_uz:"Balki hamon o‘zini sokinlik bilan hikoya qilib turadi.",note:null},
{num:478,time:"00:44:05,480 --> 00:44:20,940",arabic:"وَمِنْ زُرْقَةِ الْبَحْرِ إِلَى بَيَاضِ الْجِبَالِ",segs:null,full_uz:"Dengizning moviyligidan tog‘larning oqligigacha.",note:null},
{num:479,time:"00:44:20,940 --> 00:44:25,139",arabic:"نَصِلُ إِلَى أَعْجُوبَةٍ طَبِيعِيَّةٍ لَا مَثِيلَ لَهَا",segs:[{ar:"نَصِلُ إِلَى أَعْجُوبَةٍ طَبِيعِيَّةٍ",uz:"tabiiy mo‘jizaga yetib boramiz"},{ar:"لَا مَثِيلَ لَهَا",uz:"unga o‘xshashi yo‘q"}],full_uz:"O‘xshashi yo‘q tabiiy mo‘jizaga yetib boramiz.",note:"أَعْجُوبَةٌ — mo‘jiza, ajabtovur hodisa."},
{num:480,time:"00:44:25,139 --> 00:44:26,900",arabic:"بَامُوكَالِي",segs:null,full_uz:"Pamukkale.",note:null},
{num:481,time:"00:44:26,900 --> 00:44:28,460",arabic:"بَامُوكَالِي",segs:null,full_uz:"Pamukkale.",note:null},
{num:482,time:"00:44:28,460 --> 00:44:33,019",arabic:"وَالَّتِي يَعْنِي اسْمُهَا قَلْعَةَ الْقُطْنِ بِاللُّغَةِ التُّرْكِيَّةِ",segs:[{ar:"وَالَّتِي يَعْنِي اسْمُهَا",uz:"uning nomi anglatadi"},{ar:"قَلْعَةَ الْقُطْنِ",uz:"“paxta qal’asi”ni"},{ar:"بِاللُّغَةِ التُّرْكِيَّةِ",uz:"turk tilida"}],full_uz:"Uning nomi turk tilida “paxta qal’asi” degan ma’noni anglatadi.",note:"قَلْعَةُ الْقُطْنِ — paxta qal’asi."},
{num:483,time:"00:44:33,019 --> 00:44:42,159",arabic:"تَخَيَّلْ جَبَلًا مُغَطًّى بِشَلَّالَاتٍ بَيْضَاءَ مُتَدَرِّجَةٍ",segs:[{ar:"تَخَيَّلْ جَبَلًا",uz:"bir tog‘ni tasavvur qiling"},{ar:"مُغَطًّى بِشَلَّالَاتٍ بَيْضَاءَ مُتَدَرِّجَةٍ",uz:"pog‘onama-pog‘ona oq sharsharalar bilan qoplangan"}],full_uz:"Pog‘onama-pog‘ona oq sharsharalar bilan qoplangan bir tog‘ni tasavvur qiling.",note:"مُتَدَرِّجٌ — pog‘onama-pog‘ona, bosqichma-bosqich."},
{num:484,time:"00:44:42,159 --> 00:44:47,300",arabic:"تَكَوَّنَتْ عَبْرَ آلَافِ السِّنِينَ مِنْ يَنَابِيعَ غَنِيَّةٍ بِالْمَعَادِنِ",segs:[{ar:"تَكَوَّنَتْ عَبْرَ آلَافِ السِّنِينَ",uz:"minglab yillar davomida hosil bo‘lgan"},{ar:"مِنْ يَنَابِيعَ غَنِيَّةٍ بِالْمَعَادِنِ",uz:"minerallarga boy buloqlardan"}],full_uz:"Ular minglab yillar davomida minerallarga boy buloqlardan hosil bo‘lgan.",note:"غَنِيٌّ بِـ — ...ga boy."},
{num:485,time:"00:44:47,300 --> 00:44:52,739",arabic:"حَتَّى بَدَا كَأَنَّهُ شَلَّالٌ مُتَجَمِّدٌ مِنَ الثَّلْجِ وَالسَّحَابِ",segs:[{ar:"حَتَّى بَدَا",uz:"hatto shunday ko‘rindiki"},{ar:"كَأَنَّهُ شَلَّالٌ مُتَجَمِّدٌ",uz:"go‘yo muzlab qolgan sharsharadek"},{ar:"مِنَ الثَّلْجِ وَالسَّحَابِ",uz:"qor va bulutdan"}],full_uz:"Hat to u qor va bulutdan hosil bo‘lgan muzlab qolgan sharsharadek ko‘rinadi.",note:"مُتَجَمِّدٌ — muzlagan."},
{num:486,time:"00:44:52,739 --> 00:44:58,079",arabic:"لَكِنَّهُ دَافِئُ الْمَلْمَسِ كَأَنَّ الْأَرْضَ تَتَنَفَّسُ الْحَيَاةَ",segs:[{ar:"لَكِنَّهُ دَافِئُ الْمَلْمَسِ",uz:"ammo u teginishda iliq"},{ar:"كَأَنَّ الْأَرْضَ تَتَنَفَّسُ الْحَيَاةَ",uz:"go‘yo yer hayot bilan nafas olayotgandek"}],full_uz:"Ammo u teginishda iliq, go‘yo yer hayot bilan nafas olayotgandek.",note:"الْمَلْمَسُ — teginish, sirt hissi."},
{num:487,time:"00:44:58,079 --> 00:45:06,840",arabic:"تَتَدَلَّى الْبِرَكُ الْفِيرُوزِيَّةُ فَوْقَ الْمُدَرَّجَاتِ الْجِيرِيَّةِ",segs:[{ar:"تَتَدَلَّى الْبِرَكُ الْفِيرُوزِيَّةُ",uz:"feruza rangli hovuzlar osilib turadi"},{ar:"فَوْقَ الْمُدَرَّجَاتِ الْجِيرِيَّةِ",uz:"ohaktosh terrasalari ustida"}],full_uz:"Feruza rangli hovuzlar ohaktosh terrasalari ustida joylashgan.",note:"بِرْكَةٌ — hovuz, suv havzasi."},
{num:488,time:"00:45:06,840 --> 00:45:10,860",arabic:"تَنْحَدِرُ الْمِيَاهُ بِهُدُوءٍ وَانْسِيَابٍ مَهِيبٍ",segs:[{ar:"تَنْحَدِرُ الْمِيَاهُ",uz:"suvlar pastga oqadi"},{ar:"بِهُدُوءٍ وَانْسِيَابٍ مَهِيبٍ",uz:"sokin va salobatli ravishda"}],full_uz:"Suvlar sokin va salobatli tarzda pastga oqadi.",note:"انْسِيَابٌ — ravon oqish, sirg‘alib oqish."},
{num:489,time:"00:45:10,860 --> 00:45:14,799",arabic:"لِتَخْلُقَ مَشْهَدًا يَفُوقُ الْخَيَالَ",segs:[{ar:"لِتَخْلُقَ مَشْهَدًا",uz:"bir manzara yaratib"},{ar:"يَفُوقُ الْخَيَالَ",uz:"tasavvurdan ham ustun keladigan"}],full_uz:"Tasavvurdan ham ustun bo‘lgan bir manzara yaratib.",note:"يَفُوقُ — oshib ketmoq, ustun kelmoq."},
{num:490,time:"00:45:14,799 --> 00:45:19,119",arabic:"كَأَنَّكَ تَمْشِي دَاخِلَ حُلْمٍ مِنَ الضَّوْءِ وَالْمَاءِ",segs:[{ar:"كَأَنَّكَ تَمْشِي دَاخِلَ حُلْمٍ",uz:"go‘yo tush ichida yurgandek"},{ar:"مِنَ الضَّوْءِ وَالْمَاءِ",uz:"nur va suvdan iborat"}],full_uz:"Go‘yo nur va suvdan iborat tush ichida yurgandek.",note:null},
{num:491,time:"00:45:19,119 --> 00:45:30,199",arabic:"وَمُنْذُ الْعُصُورِ الْقَدِيمَةِ جَاءَ النَّاسُ لِيَسْتَحِمُّوا فِي مِيَاهِهَا الْحَارَّةِ",segs:[{ar:"وَمُنْذُ الْعُصُورِ الْقَدِيمَةِ",uz:"qadim zamonlardan beri"},{ar:"جَاءَ النَّاسُ",uz:"odamlar kelishgan"},{ar:"لِيَسْتَحِمُّوا فِي مِيَاهِهَا الْحَارَّةِ",uz:"uning issiq suvlarida cho‘milish uchun"}],full_uz:"Qadim zamonlardan beri odamlar uning issiq suvlarida cho‘milish uchun kelishgan.",note:"اسْتَحَمَّ — cho‘milmoq."},
{num:492,time:"00:45:30,199 --> 00:45:33,839",arabic:"مُؤْمِنِينَ بِقُدْرَتِهَا عَلَى الشِّفَاءِ وَالتَّجْدِيدِ",segs:[{ar:"مُؤْمِنِينَ بِقُدْرَتِهَا",uz:"uning qobiliyatiga ishongan holda"},{ar:"عَلَى الشِّفَاءِ وَالتَّجْدِيدِ",uz:"shifolash va yangilashga"}],full_uz:"Uning shifolash va yangilash qobiliyatiga ishongan holda.",note:"التَّجْدِيدُ — yangilash, tiklash."},
{num:493,time:"00:45:37,799 --> 00:45:44,920",arabic:"وَعَلَى قِمَّةِ هَذَا الْجَبَلِ الْأَبْيَضِ تَنْتَصِبُ آثَارُ هِيرَابُولِيسَ الْقَدِيمَةُ",segs:[{ar:"وَعَلَى قِمَّةِ هَذَا الْجَبَلِ الْأَبْيَضِ",uz:"bu oq tog‘ cho‘qqisida"},{ar:"تَنْتَصِبُ آثَارُ هِيرَابُولِيسَ الْقَدِيمَةُ",uz:"qadimgi Hierapolis xarobalari qad rostlab turadi"}],full_uz:"Bu oq tog‘ cho‘qqisida qadimgi Hierapolis xarobalari qad rostlab turadi.",note:"تَنْتَصِبُ — tik turmoq, qad rostlamoq."},
{num:494,time:"00:45:44,920 --> 00:45:50,360",arabic:"بِمَسْرَحِهَا الرُّومَانِيِّ وَأَعْمِدَتِهَا الَّتِي صَمَدَتْ أَمَامَ الزَّمَنِ",segs:[{ar:"بِمَسْرَحِهَا الرُّومَانِيِّ",uz:"uning Rim teatri bilan"},{ar:"وَأَعْمِدَتِهَا",uz:"va ustunlari"},{ar:"الَّتِي صَمَدَتْ أَمَامَ الزَّمَنِ",uz:"zamon qarshisida bardosh bergan"}],full_uz:"Uning Rim teatri va zamon qarshisida bardosh bergan ustunlari bor.",note:"صَمَدَ — bardosh bermoq, saqlanib qolmoq."},
{num:495,time:"00:45:50,360 --> 00:45:56,039",arabic:"تَرْوِي قِصَّةَ الْإِنْسَانِ حِينَ الْتَقَى بِالْحَجَرِ وَالْمَاءِ وَالدَّهْشَةِ",segs:[{ar:"تَرْوِي قِصَّةَ الْإِنْسَانِ",uz:"inson haqida hikoya qiladi"},{ar:"حِينَ الْتَقَى بِالْحَجَرِ وَالْمَاءِ وَالدَّهْشَةِ",uz:"tosh, suv va hayrat bilan uchrashganida"}],full_uz:"Tosh, suv va hayrat bilan uchrashgan inson haqida hikoya qiladi.",note:null},
{num:496,time:"00:45:56,039 --> 00:46:05,500",arabic:"دَلِيلٌ عَلَى أَنَّ هَذَا الْمَكَانَ أَسَرَ قُلُوبَ الْبَشَرِ مُنْذُ آلَافِ السِّنِينَ",segs:[{ar:"دَلِيلٌ عَلَى أَنَّ هَذَا الْمَكَانَ",uz:"bu joyning ... ekaniga dalil"},{ar:"أَسَرَ قُلُوبَ الْبَشَرِ",uz:"insonlar qalbini rom etgani"},{ar:"مُنْذُ آلَافِ السِّنِينَ",uz:"minglab yillardan beri"}],full_uz:"Bu joy minglab yillardan beri insonlar qalbini rom etib kelganiga dalildir.",note:"أَسَرَ — rom etmoq, o‘ziga maftun qilmoq."},
{num:497,time:"00:46:05,500 --> 00:46:11,079",arabic:"وَمَعَ غُرُوبِ الشَّمْسِ يَتَوَهَّجُ الْحَجَرُ الْأَبْيَضُ بِلَوْنٍ ذَهَبِيٍّ",segs:[{ar:"وَمَعَ غُرُوبِ الشَّمْسِ",uz:"quyosh botishi bilan"},{ar:"يَتَوَهَّجُ الْحَجَرُ الْأَبْيَضُ",uz:"oq tosh yarqiraydi"},{ar:"بِلَوْنٍ ذَهَبِيٍّ",uz:"oltin rangda"}],full_uz:"Quyosh botishi bilan oq tosh oltin rangda yarqiraydi.",note:"تَوَهَّجَ — yarqiramoq, lovullamoq."},
{num:498,time:"00:46:11,079 --> 00:46:15,799",arabic:"وَتَتَلَوَّنُ الْبِرَكُ بِدَرَجَاتٍ مِنَ الْوَرْدِيِّ وَالْفِيرُوزِيِّ",segs:[{ar:"وَتَتَلَوَّنُ الْبِرَكُ",uz:"hovuzlar tuslanadi"},{ar:"بِدَرَجَاتٍ مِنَ الْوَرْدِيِّ وَالْفِيرُوزِيِّ",uz:"pushti va feruza ranglarning turli tuslariga"}],full_uz:"Hovuzlar pushti va feruza ranglarning turli tuslariga kiradi.",note:"دَرَجَةٌ — daraja, tus."},
{num:499,time:"00:46:15,799 --> 00:46:20,059",arabic:"كَأَنَّ الْأَرْضَ نَفْسَهَا تَعْزِفُ لَحْنَ الْوَدَاعِ",segs:[{ar:"كَأَنَّ الْأَرْضَ نَفْسَهَا",uz:"go‘yo yerning o‘zi"},{ar:"تَعْزِفُ لَحْنَ الْوَدَاعِ",uz:"vidolashuv ohangini ijro etayotgandek"}],full_uz:"Go‘yo yerning o‘zi vidolashuv ohangini ijro etayotgandek.",note:"لَحْنٌ — ohang, kuy."},
{num:500,time:"00:46:20,059 --> 00:46:31,880",arabic:"بَامُوكَالِي قَلْعَةٌ لَيْسَتْ مُجَرَّدَ أَعْجُوبَةٍ مِنْ صُنْعِ الطَّبِيعَةِ",segs:[{ar:"بَامُوكَالِي قَلْعَةٌ",uz:"Pamukkale qal’a"},{ar:"لَيْسَتْ مُجَرَّدَ أَعْجُوبَةٍ",uz:"shunchaki mo‘jiza emas"},{ar:"مِنْ صُنْعِ الطَّبِيعَةِ",uz:"tabiat yaratgan"}],full_uz:"Pamukkale tabiat yaratgan shunchaki mo‘jiza emas, qal’adir.",note:null},
{num:501,time:"00:46:31,880 --> 00:46:33,739",arabic:"بَلْ تُحْفَةٌ حَيَّةٌ",segs:null,full_uz:"Balki tirik bir durdonadir.",note:"تُحْفَةٌ — durdona, noyob asar."},
{num:502,time:"00:46:33,739 --> 00:46:37,000",arabic:"رَسَمَهَا الزَّمَنُ بِالْمَاءِ وَالْحَجَرِ",segs:[{ar:"رَسَمَهَا الزَّمَنُ",uz:"uni zamon chizgan"},{ar:"بِالْمَاءِ وَالْحَجَرِ",uz:"suv va tosh bilan"}],full_uz:"Uni zamon suv va tosh bilan chizgan.",note:null},
{num:503,time:"00:46:37,000 --> 00:46:42,400",arabic:"وَصَاغَهَا الْخَالِقُ بِيَدِهِ فِي لَوْحَةٍ مِنَ السَّكِينَةِ وَالدَّهْشَةِ",segs:[{ar:"وَصَاغَهَا الْخَالِقُ بِيَدِهِ",uz:"Yaratuvchi uni O‘z qo‘li bilan shakllantirgan"},{ar:"فِي لَوْحَةٍ مِنَ السَّكِينَةِ وَالدَّهْشَةِ",uz:"sokinlik va hayratdan iborat bir manzaraga"}],full_uz:"Yaratuvchi uni O‘z qo‘li bilan sokinlik va hayratdan iborat bir manzaraga shakllantirgan.",note:"صَاغَ — shakl bermoq, yaratmoq."},
{num:504,time:"00:46:42,400 --> 00:46:53,199",arabic:"نَغُوصُ فِي قَلْبِ الْأَدْغَالِ الْكَمْبُودِيَّةِ",segs:[{ar:"نَغُوصُ",uz:"sho‘ng‘iymiz"},{ar:"فِي قَلْبِ الْأَدْغَالِ الْكَمْبُودِيَّةِ",uz:"Kambodja changalzorlarining bag‘riga"}],full_uz:"Kambodja changalzorlarining bag‘riga sho‘ng‘iymiz.",note:"أَدْغَالٌ — zich o‘rmon, changalzor."},
{num:505,time:"00:46:53,199 --> 00:46:58,239",arabic:"حَيْثُ تَنْهَضُ مِنْ بَيْنِ الْأَشْجَارِ أَعْمِدَةٌ مِنْ صَخْرٍ مُقَدَّسٍ",segs:[{ar:"حَيْثُ تَنْهَضُ مِنْ بَيْنِ الْأَشْجَارِ",uz:"u yerda daraxtlar orasidan ko‘tariladi"},{ar:"أَعْمِدَةٌ مِنْ صَخْرٍ مُقَدَّسٍ",uz:"muqaddas toshdan ustunlar"}],full_uz:"U yerda daraxtlar orasidan muqaddas toshdan ustunlar ko‘tarilib turadi.",note:"أَعْمِدَةٌ — ustunlar."},
{num:506,time:"00:46:58,239 --> 00:47:04,239",arabic:"تَحْمِلُ عَلَى كَتِفَيْهَا ذَاكِرَةَ حَضَارَةٍ عَظِيمَةٍ",segs:[{ar:"تَحْمِلُ عَلَى كَتِفَيْهَا",uz:"o‘z yelkalarida ko‘tarib turadi"},{ar:"ذَاكِرَةَ حَضَارَةٍ عَظِيمَةٍ",uz:"buyuk sivilizatsiya xotirasini"}],full_uz:"Ular o‘z yelkalarida buyuk sivilizatsiya xotirasini ko‘tarib turadi.",note:"كَتِفٌ — yelka."},
{num:507,time:"00:47:04,239 --> 00:47:06,799",arabic:"إِنَّهُ أَنْكُورُ وَاتْ",segs:null,full_uz:"Bu Angkor Wat.",note:null},
{num:508,time:"00:47:06,799 --> 00:47:15,699",arabic:"بُنِيَ فِي الْقَرْنِ الثَّانِيَ عَشَرَ عَلَى يَدِ الْمَلِكِ سُورْيَا فَارْمَانَ الثَّانِي",segs:[{ar:"بُنِيَ فِي الْقَرْنِ الثَّانِيَ عَشَرَ",uz:"o‘n ikkinchi asrda qurilgan"},{ar:"عَلَى يَدِ الْمَلِكِ سُورْيَا فَارْمَانَ الثَّانِي",uz:"qirol Surya Varman II tomonidan"}],full_uz:"U o‘n ikkinchi asrda qirol Surya Varman II tomonidan qurilgan.",note:null},
{num:509,time:"00:47:15,699 --> 00:47:21,279",arabic:"وَكَانَ مَعْبَدًا ضَخْمًا نُقِشَ فِي الْحَجَرِ كَأَنَّهُ كَوْنٌ صَغِيرٌ",segs:[{ar:"وَكَانَ مَعْبَدًا ضَخْمًا",uz:"va ulkan ibodatxona edi"},{ar:"نُقِشَ فِي الْحَجَرِ",uz:"toshga o‘yilgan"},{ar:"كَأَنَّهُ كَوْنٌ صَغِيرٌ",uz:"go‘yo kichik bir koinot"}],full_uz:"U toshga o‘yilgan, go‘yo kichik bir koinotdek ulkan ibodatxona edi.",note:"نُقِشَ — o‘yib yozildi, naqshlandi."},
{num:510,time:"00:47:21,279 --> 00:47:28,759",arabic:"ثُمَّ تَحَوَّلَ مَعَ الزَّمَنِ إِلَى مَزَارٍ تَتَرَدَّدُ فِيهِ أَدْعِيَةُ الْإِنْسَانِ عَبْرَ الْعُصُورِ",segs:[{ar:"ثُمَّ تَحَوَّلَ مَعَ الزَّمَنِ",uz:"so‘ng vaqt o‘tishi bilan aylandi"},{ar:"إِلَى مَزَارٍ",uz:"ziyoratgohga"},{ar:"تَتَرَدَّدُ فِيهِ أَدْعِيَةُ الْإِنْسَانِ",uz:"unda insonlarning duolari yangraydigan"},{ar:"عَبْرَ الْعُصُورِ",uz:"asrlar davomida"}],full_uz:"So‘ng vaqt o‘tishi bilan asrlar davomida insonlarning duolari yangraydigan ziyoratgohga aylandi.",note:"مَزَارٌ — ziyoratgoh, muqaddas qadamjo."},
{num:511,time:"00:47:28,760 --> 00:47:37,740",arabic:"خَمْسَةُ أَبْرَاجٍ شَامِخَةٍ تَرْمُزُ إِلَى قِمَمِ الْجِبَالِ",segs:[{ar:"خَمْسَةُ أَبْرَاجٍ شَامِخَةٍ",uz:"beshta baland minora"},{ar:"تَرْمُزُ إِلَى قِمَمِ الْجِبَالِ",uz:"tog‘ cho‘qqilarini ifodalaydi"}],full_uz:"Beshta baland minora tog‘ cho‘qqilarini ifodalaydi.",note:"شَامِخٌ — baland, salobatli. رَمَزَ إِلَى — ramziy ifodalamoq."},
{num:512,time:"00:47:37,740 --> 00:47:41,840",arabic:"تَمْتَدُّ حَوْلَهَا أَرْوِقَةٌ لَا تَنْتَهِي",segs:[{ar:"تَمْتَدُّ حَوْلَهَا أَرْوِقَةٌ",uz:"uning atrofida ravoqlar cho‘zilib ketadi"},{ar:"لَا تَنْتَهِي",uz:"tugamaydigan"}],full_uz:"Uning atrofida tugamaydigan ravoqlar cho‘zilib ketadi.",note:"رِوَاقٌ — ravoq, ayvon."},
{num:513,time:"00:47:41,840 --> 00:47:49,720",arabic:"وَجُدْرَانٌ تَحْمِلُ نُقُوشًا تَحْكِي عَنْ حُرُوبٍ وَصَلَوَاتٍ وَرَاقِصَاتٍ مِنْ ضَوْءٍ وَغُبَارٍ",segs:[{ar:"وَجُدْرَانٌ تَحْمِلُ نُقُوشًا",uz:"va naqshlar tushirilgan devorlar"},{ar:"تَحْكِي عَنْ حُرُوبٍ وَصَلَوَاتٍ",uz:"urushlar va ibodatlar haqida hikoya qiladigan"},{ar:"وَرَاقِصَاتٍ مِنْ ضَوْءٍ وَغُبَارٍ",uz:"nur va changdan raqs tushuvchi qizlar haqida"}],full_uz:"Va urushlar, ibodatlar hamda nur va chang ichida raqs tushuvchi qizlar haqida hikoya qiladigan naqshlar tushirilgan devorlar bor.",note:"رَاقِصَةٌ — raqqosa."},
{num:514,time:"00:47:49,719 --> 00:47:59,559",arabic:"وَحِينَ تَشْرُقُ الشَّمْسُ تَصْبُغُ جُدْرَانَهُ بِأَلْوَانِ الذَّهَبِ وَالْعَنْبَرِ",segs:[{ar:"وَحِينَ تَشْرُقُ الشَّمْسُ",uz:"quyosh chiqqanda"},{ar:"تَصْبُغُ جُدْرَانَهُ",uz:"uning devorlarini bo‘yaydi"},{ar:"بِأَلْوَانِ الذَّهَبِ وَالْعَنْبَرِ",uz:"oltin va qahrabo ranglariga"}],full_uz:"Quyosh chiqqanda uning devorlarini oltin va qahrabo ranglariga bo‘yaydi.",note:"عَنْبَرٌ — qahrabo, amber."},
{num:515,time:"00:47:59,559 --> 00:48:04,980",arabic:"فَتَشْعُرُ أَنَّ الْمَكَانَ حَيٌّ يَتَنَفَّسُ بَيْنَ الْحِجَارَةِ",segs:[{ar:"فَتَشْعُرُ أَنَّ الْمَكَانَ حَيٌّ",uz:"shunda bu joy tirik ekanini his qilasiz"},{ar:"يَتَنَفَّسُ بَيْنَ الْحِجَارَةِ",uz:"toshlar orasida nafas olayotgan"}],full_uz:"Shunda bu joy toshlar orasida nafas olayotgan tirik bir joydek tuyuladi.",note:null},
{num:516,time:"00:48:04,980 --> 00:48:09,859",arabic:"يُسَبِّحُ بِحَمْدِ خَالِقِهِ الَّذِي أَذِنَ لِهَذَا الْجَمَالِ أَنْ يَبْقَى",segs:[{ar:"يُسَبِّحُ بِحَمْدِ خَالِقِهِ",uz:"o‘z Yaratuvchisini hamd bilan tasbeh etadi"},{ar:"الَّذِي أَذِنَ لِهَذَا الْجَمَالِ أَنْ يَبْقَى",uz:"bu go‘zallikning qolishiga ijozat bergan"}],full_uz:"U bu go‘zallikning qolishiga ijozat bergan Yaratuvchisini hamd bilan tasbeh etadi.",note:null},
{num:517,time:"00:48:09,859 --> 00:48:17,099",arabic:"كَانَ أَنْكُورُ وَاتْ يَوْمًا ضَائِعًا فِي أَحْضَانِ الْغَابَةِ",segs:[{ar:"كَانَ أَنْكُورُ وَاتْ يَوْمًا",uz:"Angkor Wat bir vaqtlar"},{ar:"ضَائِعًا فِي أَحْضَانِ الْغَابَةِ",uz:"o‘rmon bag‘rida yo‘qolgan edi"}],full_uz:"Angkor Wat bir vaqtlar o‘rmon bag‘rida yo‘qolib yotgan edi.",note:"أَحْضَانٌ — bag‘irlar, quchoqlar."},
{num:518,time:"00:48:17,099 --> 00:48:25,599",arabic:"ثُمَّ عَادَ لِيُذَكِّرَ الْعَالَمَ بِأَنَّ الْإِخْلَاصَ فِي الْعَمَلِ وَالنِّيَّةِ يَمْنَحُ لِلْأَثَرِ حَيَاةً لَا تَزُولُ",segs:[{ar:"ثُمَّ عَادَ لِيُذَكِّرَ الْعَالَمَ",uz:"so‘ng dunyoga eslatish uchun qaytdi"},{ar:"بِأَنَّ الْإِخْلَاصَ فِي الْعَمَلِ وَالنِّيَّةِ",uz:"mehnat va niyatdagi ixlos"},{ar:"يَمْنَحُ لِلْأَثَرِ حَيَاةً لَا تَزُولُ",uz:"asarга yo‘qolmaydigan hayot berishini"}],full_uz:"So‘ng mehnat va niyatdagi ixlos asarga yo‘qolmaydigan hayot berishini dunyoga eslatish uchun qaytdi.",note:"الْإِخْلَاصُ — ixlos, samimiylik."},
{num:519,time:"00:48:25,599 --> 00:48:40,279",arabic:"نَصِلُ إِلَى مَدِينَةٍ وُلِدَتْ مِنَ الْمَاءِ، إِلَى الْحُلْمِ الْعَائِمِ فَوْقَ الْأَدْرِيَاتِيِّ، الْبُنْدُقِيَّةِ، فِينِيسْ",segs:[{ar:"نَصِلُ إِلَى مَدِينَةٍ وُلِدَتْ مِنَ الْمَاءِ",uz:"suvdan tug‘ilgan shaharga yetib boramiz"},{ar:"إِلَى الْحُلْمِ الْعَائِمِ فَوْقَ الْأَدْرِيَاتِيِّ",uz:"Adriatika ustida suzib turgan tushga"},{ar:"الْبُنْدُقِيَّةِ، فِينِيسْ",uz:"Venetsiya, Venis"}],full_uz:"Suvdan tug‘ilgan shaharga — Adriatika ustida suzib turgan tush, Venetsiya, Venisga yetib boramiz.",note:"الْحُلْمُ الْعَائِمُ — suzib turgan tush."},
{num:520,time:"00:48:40,280 --> 00:48:46,280",arabic:"مَدِينَةٌ لَا تُشْبِهُ سِوَاهَا",segs:[{ar:"مَدِينَةٌ",uz:"shahar"},{ar:"لَا تُشْبِهُ سِوَاهَا",uz:"boshqasiga o‘xshamaydigan"}],full_uz:"Boshqa hech bir shaharga o‘xshamaydigan shahar.",note:"سِوَى — ...dan boshqa."},
{num:521,time:"00:48:46,280 --> 00:48:50,060",arabic:"بُنِيَتْ عَلَى أَكْثَرَ مِنْ مِائَةِ جَزِيرَةٍ صَغِيرَةٍ",segs:null,full_uz:"U yuzdan ortiq kichik orollar ustida qurilgan.",note:null},
{num:522,time:"00:48:50,060 --> 00:48:54,980",arabic:"تَتَشَابَكُ بَيْنَهَا الْقَنَوَاتُ كَعُرُوقٍ مِنْ ضَوْءٍ وَسُكُونٍ",segs:[{ar:"تَتَشَابَكُ بَيْنَهَا الْقَنَوَاتُ",uz:"ular orasida kanallar bir-biriga tutashadi"},{ar:"كَعُرُوقٍ مِنْ ضَوْءٍ وَسُكُونٍ",uz:"nur va sukunatdan tomirlar kabi"}],full_uz:"Ular orasidagi kanallar go‘yo nur va sukunatdan iborat tomirlardek bir-biriga tutashadi.",note:"قَنَاةٌ — kanal."},
{num:523,time:"00:48:54,980 --> 00:49:01,340",arabic:"هُنَا لَا شَوَارِعَ بَلْ أَنْهَارٌ",segs:[{ar:"هُنَا لَا شَوَارِعَ",uz:"bu yerda ko‘chalar yo‘q"},{ar:"بَلْ أَنْهَارٌ",uz:"balki daryolar bor"}],full_uz:"Bu yerda ko‘chalar yo‘q, balki daryolar bor.",note:null},
{num:524,time:"00:49:01,340 --> 00:49:07,820",arabic:"وَلَا سَيَّارَاتٌ بَلْ قَوَارِبُ تَتَهَادَى كَأَنَّهَا نَغْمٌ يَعْزِفُهُ الْمَاءُ",segs:[{ar:"وَلَا سَيَّارَاتٌ",uz:"mashinalar ham yo‘q"},{ar:"بَلْ قَوَارِبُ تَتَهَادَى",uz:"balki qayiqchalar mayin tebranadi"},{ar:"كَأَنَّهَا نَغْمٌ يَعْزِفُهُ الْمَاءُ",uz:"go‘yo suv ijro etadigan ohangdek"}],full_uz:"Mashinlar ham yo‘q, balki qayiqchalar go‘yo suv ijro etadigan ohangdek mayin tebranadi.",note:"تَتَهَادَى — mayin tebranmoq, asta suzmoq."},
{num:525,time:"00:49:10,280 --> 00:49:17,600",arabic:"الْقَدِيمَةُ وَانْعِكَاسُهَا فِي الْمَاءِ يَرْسُمُ لَوْحَاتٍ حَيَّةً تَتَحَرَّكُ مَعَ الْمَوْجِ",segs:[{ar:"الْقَدِيمَةُ وَانْعِكَاسُهَا فِي الْمَاءِ",uz:"qadimiy ... va uning suvdagi aksi"},{ar:"يَرْسُمُ لَوْحَاتٍ حَيَّةً",uz:"tirik manzaralarni chizadi"},{ar:"تَتَحَرَّكُ مَعَ الْمَوْجِ",uz:"to‘lqin bilan harakatlanadigan"}],full_uz:"Qadimiy binolar va ularning suvdagi aksi to‘lqin bilan harakatlanadigan tirik manzaralarni chizadi.",note:null},
{num:526,time:"00:49:17,600 --> 00:49:31,460",arabic:"الْأَجْرَاسُ تَدُقُّ مِنْ بَعِيدٍ وَالضَّحِكَاتُ تَتَرَدَّدُ عَبْرَ السَّاحَاتِ وَفِي سَاحَةِ سَانْ مَارْكُو",segs:[{ar:"الْأَجْرَاسُ تَدُقُّ مِنْ بَعِيدٍ",uz:"qo‘ng‘iroqlar uzoqdan jiringlaydi"},{ar:"وَالضَّحِكَاتُ تَتَرَدَّدُ عَبْرَ السَّاحَاتِ",uz:"va kulgilar maydonlarda aks-sado beradi"},{ar:"وَفِي سَاحَةِ سَانْ مَارْكُو",uz:"va San-Marko maydonida"}],full_uz:"Qo‘ng‘iroqlar uzoqdan jiringlaydi, kulgilar maydonlarda va San-Marko maydonida aks-sado beradi.",note:"تَتَرَدَّدُ — aks-sado bermoq, takrorlanib eshitilmoq."},
{num:527,time:"00:49:31,460 --> 00:49:39,240",arabic:"يَقِفُ الْجَمَالُ فِي أَبْهَى صُوَرِهِ تَحْتَ قُبَّةِ بَازِيلِيكَا سَانْ مَارْكُو وَبِجَوَارِ بُرْجٍ",segs:[{ar:"يَقِفُ الْجَمَالُ فِي أَبْهَى صُوَرِهِ",uz:"go‘zallik eng go‘zal ko‘rinishida turadi"},{ar:"تَحْتَ قُبَّةِ بَازِيلِيكَا سَانْ مَارْكُو",uz:"San-Marko bazilikasi gumbazi ostida"},{ar:"وَبِجَوَارِ بُرْجٍ",uz:"va bir minora yonida"}],full_uz:"Go‘zallik San-Marko bazilikasi gumbazi ostida va bir minora yonida o‘zining eng go‘zal ko‘rinishida turadi.",note:"بَازِيلِيكَا — bazilika."},
{num:528,time:"00:49:39,239 --> 00:49:44,219",arabic:"الَّذِي يُطِلُّ عَلَى الْمَدِينَةِ كَحَارِسٍ مِنْ زَمَنٍ آخَرَ",segs:[{ar:"الَّذِي يُطِلُّ عَلَى الْمَدِينَةِ",uz:"u shaharga qarab turadi"},{ar:"كَحَارِسٍ مِنْ زَمَنٍ آخَرَ",uz:"boshqa zamondan kelgan qo‘riqchidek"}],full_uz:"U shaharga go‘yo boshqa zamondan kelgan qo‘riqchidek qarab turadi.",note:"حَارِسٌ — qo‘riqchi."},
{num:529,time:"00:49:44,219 --> 00:49:53,500",arabic:"وَعِنْدَمَا تَغْرُبُ الشَّمْسُ تَتَحَوَّلُ الْبُنْدُقِيَّةُ إِلَى ذَهَبٍ سَائِلٍ",segs:[{ar:"وَعِنْدَمَا تَغْرُبُ الشَّمْسُ",uz:"quyosh botganda"},{ar:"تَتَحَوَّلُ الْبُنْدُقِيَّةُ",uz:"Venetsiya aylanadi"},{ar:"إِلَى ذَهَبٍ سَائِلٍ",uz:"erigan oltinga"}],full_uz:"Quyosh botganda Venetsiya erigan oltinga aylanadi.",note:"سَائِلٌ — suyuq, oqib turuvchi."},
{num:530,time:"00:49:53,500 --> 00:49:59,239",arabic:"وَتَبْدُو كُلُّ زَاوِيَةٍ فِيهَا كَأَنَّهَا تَهْمِسُ بِحِكَايَةِ حُبٍّ قَدِيمَةٍ",segs:[{ar:"وَتَبْدُو كُلُّ زَاوِيَةٍ فِيهَا",uz:"va undagi har bir burchak ko‘rinadi"},{ar:"كَأَنَّهَا تَهْمِسُ بِحِكَايَةِ حُبٍّ قَدِيمَةٍ",uz:"go‘yo qadimiy muhabbat hikoyasini shivirlayotgandek"}],full_uz:"Undagi har bir burchak go‘yo qadimiy muhabbat hikoyasini shivirlayotgandek ko‘rinadi.",note:null},
{num:531,time:"00:29,239 --> 00:50:29,219",arabic:"",segs:null,full_uz:"",note:null},
{num:532,time:"00:50:29,239 --> 00:50:44,259",arabic:"نَتَّجِهُ إِلَى قَلْبِ الْأَنَاضُولِ",segs:[{ar:"نَتَّجِهُ إِلَى",uz:"yo‘l olamiz"},{ar:"قَلْبِ الْأَنَاضُولِ",uz:"Anadolu yuragiga"}],full_uz:"Anadolu yuragiga yo‘l olamiz.",note:null},
{num:533,time:"00:50:44,259 --> 00:50:47,719",arabic:"حَيْثُ تَنْتَصِبُ التِّلَالُ الْعَجِيبَةُ",segs:[{ar:"حَيْثُ تَنْتَصِبُ",uz:"u yerda qad rostlaydi"},{ar:"التِّلَالُ الْعَجِيبَةُ",uz:"ajoyib tepaliklar"}],full_uz:"U yerda ajoyib tepaliklar qad rostlab turadi.",note:"تَنْتَصِبُ — tik turmoq, qad rostlamoq."},
{num:534,time:"00:50:47,719 --> 00:50:50,879",arabic:"كَأَنَّهَا مَنْحُوتَةٌ مِنْ عَالَمٍ آخَرَ",segs:[{ar:"كَأَنَّهَا مَنْحُوتَةٌ",uz:"go‘yo o‘yib yaratilgandek"},{ar:"مِنْ عَالَمٍ آخَرَ",uz:"boshqa bir olamdan"}],full_uz:"Go‘yo boshqa bir olamdan o‘yib yaratilgandek.",note:"مَنْحُوتٌ — o‘yilgan, o‘yib yaratilgan."},
{num:535,time:"00:50:50,879 --> 00:50:53,679",arabic:"إِنَّهَا كَابَادُوكْيَا",segs:null,full_uz:"Bu Kapadokiya.",note:null},
{num:536,time:"00:50:53,679 --> 00:50:55,139",arabic:"كَابَادُوسِيَا",segs:null,full_uz:"Kapadusiya.",note:null},
{num:537,time:"00:50:55,139 --> 00:50:57,399",arabic:"أَرْضُ الْعَجَائِبِ الصَّخْرِيَّةِ",segs:null,full_uz:"Qoyali mo‘jizalar diyori.",note:null},
{num:538,time:"00:50:57,400 --> 00:50:59,760",arabic:"وَالْمَنَازِلُ الْمَنْحُوتَةُ",segs:null,full_uz:"Va o‘yib qurilgan uylar.",note:"مَنْحُوتٌ — o‘yilgan, o‘yib yaratilgan."},
{num:539,time:"00:50:59,760 --> 00:51:04,079",arabic:"وَالسَّمَاءُ الَّتِي تَمْلَؤُهَا الْمَنَاطِيدُ عِنْدَ الْفَجْرِ",segs:[{ar:"وَالسَّمَاءُ الَّتِي تَمْلَؤُهَا الْمَنَاطِيدُ",uz:"va osmonni sharlar to‘ldiradi"},{ar:"عِنْدَ الْفَجْرِ",uz:"tong otganda"}],full_uz:"Tong otganda sharlar to‘ldiradigan osmon.",note:"مَنْطَادٌ — havo shari."},
{num:540,time:"00:51:04,079 --> 00:51:08,680",arabic:"مُنْذُ مَلَايِينِ السِّنِينَ",segs:null,full_uz:"Millionlab yillardan beri.",note:null},
{num:541,time:"00:51:08,680 --> 00:51:12,720",arabic:"غَطَّتِ الْبَرَاكِينُ هَذِهِ الْأَرْضَ بِالرَّمَادِ وَالْحِمَمِ",segs:[{ar:"غَطَّتِ الْبَرَاكِينُ هَذِهِ الْأَرْضَ",uz:"vulqonlar bu yerlarni qoplagan"},{ar:"بِالرَّمَادِ وَالْحِمَمِ",uz:"kul va lava bilan"}],full_uz:"Millionlab yillar oldin vulqonlar bu yerlarni kul va lava bilan qoplagan.",note:"حُمَمٌ — lava."},
{num:542,time:"00:51:12,720 --> 00:51:15,360",arabic:"ثُمَّ شَكَّلَهَا الْمَطَرُ وَالرِّيحُ",segs:[{ar:"ثُمَّ شَكَّلَهَا",uz:"so‘ng uni shakllantirdi"},{ar:"الْمَطَرُ وَالرِّيحُ",uz:"yomg‘ir va shamol"}],full_uz:"So‘ng yomg‘ir va shamol uni shakllantirdi.",note:"شَكَّلَ — shakllantirmoq."},
{num:543,time:"00:51:15,360 --> 00:51:19,680",arabic:"حَتَّى صَارَتْ أَعْمِدَةً حَجَرِيَّةً تُشْبِهُ الْمَآذِنَ",segs:[{ar:"حَتَّى صَارَتْ أَعْمِدَةً حَجَرِيَّةً",uz:"oxir-oqibat tosh ustunlarga aylandi"},{ar:"تُشْبِهُ الْمَآذِنَ",uz:"minoralarni eslatadigan"}],full_uz:"Oxir-oqibat minoralarni eslatadigan tosh ustunlarga aylandi.",note:"عَمُودٌ حَجَرِيٌّ — tosh ustun."},
{num:544,time:"00:51:19,680 --> 00:51:22,460",arabic:"وَفِي هَذَا التَّكْوِينِ الْمُذْهِلِ",segs:null,full_uz:"Va bu hayratlanarli tuzilishda.",note:"تَكْوِينٌ — tuzilish, shakllanish."},
{num:545,time:"00:51:22,460 --> 00:51:26,680",arabic:"تَتَجَلَّى قُدْرَةُ اللَّهِ عَلَى أَنْ يَجْعَلَ مِنَ النَّارِ حَيَاةً",segs:[{ar:"تَتَجَلَّى قُدْرَةُ اللَّهِ",uz:"Allohning qudrati namoyon bo‘ladi"},{ar:"عَلَى أَنْ يَجْعَلَ مِنَ النَّارِ حَيَاةً",uz:"olovdan hayot yaratishga"}],full_uz:"Allohning olovdan hayot yaratish qudrati namoyon bo‘ladi.",note:null},
{num:546,time:"00:51:27,400 --> 00:51:29,260",arabic:"وَمِنَ الرَّمَادِ جَمَالًا",segs:null,full_uz:"Va kuldan go‘zallik yaratishga.",note:null},
{num:547,time:"00:51:29,260 --> 00:51:37,360",arabic:"وَلِقُرُونٍ طَوِيلَةٍ حَفَرَ النَّاسُ بُيُوتَهُمْ وَكَنَائِسَهُمْ فِي الصُّخُورِ",segs:[{ar:"وَلِقُرُونٍ طَوِيلَةٍ",uz:"uzoq asrlar davomida"},{ar:"حَفَرَ النَّاسُ بُيُوتَهُمْ وَكَنَائِسَهُمْ",uz:"odamlar uylarini va cherkovlarini o‘yib yaratdilar"},{ar:"فِي الصُّخُورِ",uz:"qoyalarga"}],full_uz:"Uzoq asrlar davomida odamlar uylarini va cherkovlarini qoyalarga o‘yib yaratdilar.",note:"حَفَرَ — qazimoq, o‘yib yaratmoq."},
{num:548,time:"00:51:37,360 --> 00:51:45,960",arabic:"فَكَانَتْ كَابَا دُوكْيَا شَاهِدَةً عَلَى انْسِجَامِ الْإِنْسَانِ مَعَ الْأَرْضِ الَّتِي خَلَقَهَا اللَّهُ لَهُ مَأْوًى وَسَكَنًا",segs:[{ar:"فَكَانَتْ كَابَا دُوكْيَا شَاهِدَةً",uz:"shunda Kapadokiya guvoh bo‘ldi"},{ar:"عَلَى انْسِجَامِ الْإِنْسَانِ مَعَ الْأَرْضِ",uz:"insonning yer bilan uyg‘unligiga"},{ar:"الَّتِي خَلَقَهَا اللَّهُ لَهُ",uz:"Alloh uni inson uchun yaratgan"},{ar:"مَأْوًى وَسَكَنًا",uz:"boshpana va yashash joyi qilib"}],full_uz:"Shunday qilib, Kapadokiya Alloh inson uchun boshpana va yashash joyi qilib yaratgan yer bilan insonning uyg‘unligiga guvoh bo‘ldi.",note:"مَأْوًى — boshpana, maskan. سَكَنٌ — yashash joyi."},
{num:549,time:"00:51:45,960 --> 00:51:50,920",arabic:"وَحِينَ تَشْرُقُ الشَّمْسُ وَتُحَلِّقُ الْبَالُونَاتُ فِي السَّمَاءِ",segs:[{ar:"وَحِينَ تَشْرُقُ الشَّمْسُ",uz:"quyosh chiqqanda"},{ar:"وَتُحَلِّقُ الْبَالُونَاتُ فِي السَّمَاءِ",uz:"va sharlar osmonda uchganda"}],full_uz:"Quyosh chiqqanda va sharlar osmonda uchganda.",note:"تُحَلِّقُ — uchmoq, osmonda parvoz qilmoq."},
{num:550,time:"00:51:50,920 --> 00:51:55,280",arabic:"يَتَلَوَّنُ الْأُفُقُ بِأَلْوَانٍ تُعِيدُ إِلَى الْقَلْبِ",segs:[{ar:"يَتَلَوَّنُ الْأُفُقُ",uz:"ufq ranglarga kiradi"},{ar:"بِأَلْوَانٍ تُعِيدُ إِلَى الْقَلْبِ",uz:"qalbga qaytaradigan ranglarda"}],full_uz:"Ufq qalbga qaytaradigan ranglarga kiradi.",note:"تَلَوَّنَ — rangga kirmoq, tuslanmoq."},
{num:551,time:"00:51:55,280 --> 00:51:56,920",arabic:"دَهْشَةَ الْبِدَايَةِ",segs:null,full_uz:"Boshlanish hayratini.",note:"دَهْشَةٌ — hayrat."},
{num:552,time:"00:51:56,920 --> 00:51:59,400",arabic:"كَأَنَّ الْكَوْنَ كُلَّهُ يَقُولُ",segs:[{ar:"كَأَنَّ الْكَوْنَ كُلَّهُ",uz:"go‘yo butun koinot"},{ar:"يَقُولُ",uz:"aytayotgandek"}],full_uz:"Go‘yo butun koinot aytayotgandek.",note:null},
{num:553,time:"00:51:59,400 --> 00:52:02,700",arabic:"تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ",segs:[{ar:"تَبَارَكَ اللَّهُ",uz:"Alloh muborakdir"},{ar:"أَحْسَنُ الْخَالِقِينَ",uz:"yaratuvchilarning eng yaxshisi"}],full_uz:"Alloh muborakdir, U yaratuvchilarning eng yaxshisidir.",note:"تَبَارَكَ — muborak va ulug‘ bo‘lmoq."},
{num:554,time:"00:52:02,700 --> 00:52:12,119",arabic:"لَكِنْ مَا يَجْعَلُ بَادُوكْيَا لَا تُنْسَى",segs:[{ar:"لَكِنْ مَا يَجْعَلُ بَادُوكْيَا",uz:"ammo Badukiyani ... qiladigan narsa"},{ar:"لَا تُنْسَى",uz:"unutilmas"}],full_uz:"Ammo Badukiyani unutilmas qiladigan narsa.",note:null},
{num:555,time:"00:52:12,119 --> 00:52:14,800",arabic:"لَيْسَ شَكْلَهَا الْغَرِيبَ فَحَسْبُ",segs:[{ar:"لَيْسَ شَكْلَهَا الْغَرِيبَ",uz:"uning g‘alati ko‘rinishi emas"},{ar:"فَحَسْبُ",uz:"xolos"}],full_uz:"Faqat uning g‘alati ko‘rinishi emas.",note:"فَحَسْبُ — xolos, faqat."},
{num:556,time:"00:52:14,800 --> 00:52:16,920",arabic:"بَلْ ذَلِكَ الشُّعُورُ بِالدَّهْشَةِ",segs:[{ar:"بَلْ ذَلِكَ الشُّعُورُ",uz:"balki o‘sha tuyg‘u"},{ar:"بِالدَّهْشَةِ",uz:"hayrat tuyg‘usi"}],full_uz:"Balki o‘sha hayrat tuyg‘usidir.",note:null},
{num:557,time:"00:52:17,680 --> 00:52:20,380",arabic:"الَّذِي يَمْلَأُ رُوحَكَ حِينَ تَشْرُقُ الشَّمْسُ",segs:[{ar:"الَّذِي يَمْلَأُ رُوحَكَ",uz:"ruhingizni to‘ldiradigan"},{ar:"حِينَ تَشْرُقُ الشَّمْسُ",uz:"quyosh chiqqanda"}],full_uz:"Quyosh chiqqanda ruhingizni to‘ldiradigan hayrat tuyg‘usi.",note:null},
{num:558,time:"00:52:20,380 --> 00:52:23,639",arabic:"فَتَتَلَوَّنُ السَّمَاءُ بِالذَّهَبِيِّ وَالْوَرْدِيِّ",segs:[{ar:"فَتَتَلَوَّنُ السَّمَاءُ",uz:"shunda osmon tuslanadi"},{ar:"بِالذَّهَبِيِّ وَالْوَرْدِيِّ",uz:"oltin va pushti rangga"}],full_uz:"Shunda osmon oltin va pushti rangga kiradi.",note:null},
{num:559,time:"00:52:23,639 --> 00:52:27,139",arabic:"وَتَرْتَفِعُ مِئَاتُ الْمَنَاطِيدِ فَوْقَ الْوِدْيَانِ",segs:[{ar:"وَتَرْتَفِعُ مِئَاتُ الْمَنَاطِيدِ",uz:"yuzlab sharlar ko‘tariladi"},{ar:"فَوْقَ الْوِدْيَانِ",uz:"vodiylar ustiga"}],full_uz:"Yuzlab sharlar vodiylar ustiga ko‘tariladi.",note:null},
{num:560,time:"00:52:27,139 --> 00:52:32,679",arabic:"كَأَنَّ الْأَرْضَ وَالسَّمَاءَ تَتَّحِدَانِ فِي لَوْحَةٍ مِنْ نُورٍ وَصَمْتٍ وَخُشُوعٍ",segs:[{ar:"كَأَنَّ الْأَرْضَ وَالسَّمَاءَ تَتَّحِدَانِ",uz:"go‘yo yer va osmon birlashgandek"},{ar:"فِي لَوْحَةٍ",uz:"bir manzarada"},{ar:"مِنْ نُورٍ وَصَمْتٍ وَخُشُوعٍ",uz:"nur, sukunat va xushu’dan iborat"}],full_uz:"Go‘yo yer va osmon nur, sukunat va xushu’dan iborat bir manzarada birlashgandek.",note:"تَتَّحِدُ — birlashmoq."},
{num:561,time:"00:52:32,679 --> 00:52:46,299",arabic:"وَعَالِيًا فَوْقَ الدَّائِرَةِ الْقُطْبِيَّةِ الشَّمَالِيَّةِ",segs:null,full_uz:"Shimoliy qutb doirasidan balandda.",note:"الدَّائِرَةُ الْقُطْبِيَّةُ — qutb doirasi."},
{num:562,time:"00:52:46,299 --> 00:52:50,079",arabic:"تَبْدَأُ السَّمَاءُ عَرْضًا مِنْ أَنْقَى الْعَجَائِبِ",segs:[{ar:"تَبْدَأُ السَّمَاءُ عَرْضًا",uz:"osmon bir tomosha boshlaydi"},{ar:"مِنْ أَنْقَى الْعَجَائِبِ",uz:"eng sof mo‘jizalardan"}],full_uz:"Osmon eng sof mo‘jizalardan bir tomoshani boshlaydi.",note:"عَرْضٌ — tomosha, namoyish."},
{num:563,time:"00:52:50,079 --> 00:52:53,019",arabic:"إِنَّهُ الشَّفَقُ الْقُطْبِيُّ",segs:null,full_uz:"Bu qutbiy yog‘dudir.",note:"الشَّفَقُ الْقُطْبِيُّ — qutbiy yog‘du, aurora."},
{num:564,time:"00:52:53,019 --> 00:52:57,800",arabic:"أُورُورَا بُورِيَالِيسُ أَوْ كَمَا يُسَمِّيهِ الْبَعْضُ",segs:[{ar:"أُورُورَا بُورِيَالِيسُ",uz:"Aurora Borealis"},{ar:"أَوْ كَمَا يُسَمِّيهِ الْبَعْضُ",uz:"yoki ba’zilar uni ataganidek"}],full_uz:"Aurora Borealis yoki ba’zilar ataganidek.",note:null},
{num:565,time:"00:52:57,800 --> 00:53:00,039",arabic:"أَنْوَارُ الشَّمَالِ",segs:null,full_uz:"Shimol yog‘dulari.",note:null},
{num:566,time:"00:53:00,039 --> 00:53:06,599",arabic:"تَشْتَعِلُ السَّمَاءُ بِأَلْوَانٍ رَاقِصَةٍ",segs:[{ar:"تَشْتَعِلُ السَّمَاءُ",uz:"osmon yonib ketgandek porlaydi"},{ar:"بِأَلْوَانٍ رَاقِصَةٍ",uz:"raqs tushuvchi ranglar bilan"}],full_uz:"Osmon raqs tushuvchi ranglar bilan yonib ketgandek porlaydi.",note:"تَشْتَعِلُ — yonmoq, lovullamoq."},
{num:567,time:"00:53:06,599 --> 00:53:10,259",arabic:"أَخْضَرُ، أَزْرَقُ، بَنَفْسَجِيٌّ، وَرَدِيٌّ",segs:null,full_uz:"Yashil, ko‘k, binafsha va pushti.",note:null},
{num:568,time:"00:53:10,259 --> 00:53:13,579",arabic:"كَأَنَّ الْفَجْرَ انْبَعَثَ لَيْلًا",segs:null,full_uz:"Go‘yo tong kechasi paydo bo‘lgandek.",note:"انْبَعَثَ — paydo bo‘lmoq, ko‘tarilmoq."},
{num:569,time:"00:53:13,579 --> 00:53:15,559",arabic:"لِيُمَجِّدَ الْخَالِقَ فِي صَمْتٍ",segs:[{ar:"لِيُمَجِّدَ الْخَالِقَ",uz:"Yaratuvchini ulug‘lash uchun"},{ar:"فِي صَمْتٍ",uz:"sukunatda"}],full_uz:"Yaratuvchini sukunatda ulug‘lash uchun.",note:"مَجَّدَ — ulug‘lamoq, madh etmoq."},
{num:570,time:"00:53:15,559 --> 00:53:22,519",arabic:"الرِّيحُ الْبَارِدَةُ تَهْمِسُ",segs:[{ar:"الرِّيحُ الْبَارِدَةُ",uz:"sovuq shamol"},{ar:"تَهْمِسُ",uz:"shivirlab turadi"}],full_uz:"Sovuq shamol shivirlab turadi.",note:"هَمَسَ — shivirlab gapirmoq."},
{num:571,time:"00:53:22,519 --> 00:53:28,259",arabic:"وَالْأُفُقُ يَتَلَوَّنُ كَأَنَّ النُّجُومَ أَفْرَغَتْ سِحْرَهَا عَلَى الثَّلْجِ",segs:[{ar:"وَالْأُفُقُ يَتَلَوَّنُ",uz:"ufq ranglarga kiradi"},{ar:"كَأَنَّ النُّجُومَ أَفْرَغَتْ سِحْرَهَا",uz:"go‘yo yulduzlar o‘z sehrini to‘kib yuborgandek"},{ar:"عَلَى الثَّلْجِ",uz:"qor ustiga"}],full_uz:"Ufq ranglarga kiradi, go‘yo yulduzlar o‘z sehrini qor ustiga to‘kib yuborgandek.",note:"أَفْرَغَ — bo‘shatmoq, to‘kmoq."},
{num:572,time:"00:53:28,259 --> 00:53:33,880",arabic:"وَفِي تِلْكَ اللَّحْظَةِ تُدْرِكُ أَنَّ الْجَمَالَ لَيْسَ ظَاهِرَةً فِي السَّمَاءِ",segs:[{ar:"وَفِي تِلْكَ اللَّحْظَةِ",uz:"o‘sha lahzada"},{ar:"تُدْرِكُ أَنَّ الْجَمَالَ",uz:"go‘zallikni anglaysiz"},{ar:"لَيْسَ ظَاهِرَةً فِي السَّمَاءِ",uz:"osmondagi shunchaki hodisa emasligini"}],full_uz:"O‘sha lahzada go‘zallik osmondagi shunchaki hodisa emasligini anglaysiz.",note:"ظَاهِرَةٌ — hodisa, fenomen."},
{num:573,time:"00:53:33,880 --> 00:53:38,739",arabic:"بَلْ آيَةٌ تُتْلَى لِمَنْ يَنْظُرُ بِعَيْنِ الْقَلْبِ",segs:[{ar:"بَلْ آيَةٌ تُتْلَى",uz:"balki o‘qiladigan bir oyat"},{ar:"لِمَنْ يَنْظُرُ بِعَيْنِ الْقَلْبِ",uz:"qalb ko‘zi bilan qaragan kishi uchun"}],full_uz:"Balki qalb ko‘zi bilan qaragan kishi uchun o‘qiladigan bir oyatdir.",note:"تُتْلَى — tilovat qilinmoq, o‘qilmoq."},
{num:574,time:"00:53:38,739 --> 00:53:47,380",arabic:"أَمْوَاجٌ مِنَ الضَّوْءِ الْأَخْضَرِ وَالْوَرْدِيِّ وَالْبَنَفْسَجِيِّ",segs:[{ar:"أَمْوَاجٌ مِنَ الضَّوْءِ",uz:"nur to‘lqinlari"},{ar:"الْأَخْضَرِ وَالْوَرْدِيِّ وَالْبَنَفْسَجِيِّ",uz:"yashil, pushti va binafsha"}],full_uz:"Yashil, pushti va binafsha rangli nur to‘lqinlari.",note:null},
{num:575,time:"00:53:47,380 --> 00:53:49,539",arabic:"تَتَرَاقَصُ فِي ظُلْمَةِ اللَّيْلِ",segs:null,full_uz:"Tun qorong‘usida raqsga tushadi.",note:"تَرَاقَصَ — raqsga tushmoq, o‘ynab turmoq."},
{num:576,time:"00:53:49,539 --> 00:53:55,519",arabic:"تَرْسُمُ عَلَى صَفْحَةِ السَّمَاءِ لَوْحَاتٍ لَا تُشْبِهُ شَيْئًا مِنْ هَذَا الْعَالَمِ",segs:[{ar:"تَرْسُمُ عَلَى صَفْحَةِ السَّمَاءِ",uz:"osmon sahifasiga chizadi"},{ar:"لَوْحَاتٍ",uz:"manzaralarni"},{ar:"لَا تُشْبِهُ شَيْئًا مِنْ هَذَا الْعَالَمِ",uz:"bu dunyodagi hech narsaga o‘xshamaydigan"}],full_uz:"Osmon sahifasiga bu dunyodagi hech narsaga o‘xshamaydigan manzaralarni chizadi.",note:"صَفْحَةٌ — sahifa, yuzasi."},
{num:577,time:"00:53:55,519 --> 00:54:01,539",arabic:"يَقُولُ الْعِلْمُ إِنَّ هَذَا الْمَشْهَدَ",segs:[{ar:"يَقُولُ الْعِلْمُ",uz:"ilm aytadiki"},{ar:"إِنَّ هَذَا الْمَشْهَدَ",uz:"bu manzara"}],full_uz:"Ilm bu manzara haqida shunday deydi.",note:null},
{num:578,time:"00:54:01,539 --> 00:54:05,500",arabic:"يُولَدُ حِينَ تَصْطَدِمُ الْجُسَيْمَاتُ الْقَادِمَةُ مِنَ الشَّمْسِ",segs:[{ar:"يُولَدُ حِينَ",uz:"... paydo bo‘ladi"},{ar:"تَصْطَدِمُ الْجُسَيْمَاتُ الْقَادِمَةُ مِنَ الشَّمْسِ",uz:"quyoshdan kelayotgan zarrachalar to‘qnashganda"}],full_uz:"Quyoshdan kelayotgan zarrachalar to‘qnashganda paydo bo‘ladi.",note:"جُسَيْمٌ — zarracha, kichik zarra."},
{num:579,time:"00:54:05,500 --> 00:54:07,779",arabic:"بِالْغِلَافِ الْجَوِّيِّ لِلْأَرْضِ",segs:null,full_uz:"Yer atmosferasi bilan.",note:"الْغِلَافُ الْجَوِّيُّ — atmosfera."},
{num:580,time:"00:54:07,779 --> 00:54:11,159",arabic:"لَكِنْ حِينَ تَرَاهُ بِعَيْنَيْكَ",segs:[{ar:"لَكِنْ حِينَ تَرَاهُ",uz:"ammo uni ko‘rganingizda"},{ar:"بِعَيْنَيْكَ",uz:"o‘z ko‘zlaringiz bilan"}],full_uz:"Ammo uni o‘z ko‘zlaringiz bilan ko‘rganingizda.",note:null},
{num:581,time:"00:54:11,159 --> 00:54:14,539",arabic:"تُدْرِكُ أَنَّ الْعِلْمَ هُنَا لَا يُفَسِّرُ",segs:[{ar:"تُدْرِكُ أَنَّ الْعِلْمَ هُنَا",uz:"bu yerda ilm ... ekanini anglaysiz"},{ar:"لَا يُفَسِّرُ",uz:"tushuntirib bermaydi"}],full_uz:"Bu yerda ilm tushuntirib bermasligini anglaysiz.",note:"فَسَّرَ — tushuntirmoq, izohlamoq."},
{num:582,time:"00:54:14,539 --> 00:54:16,539",arabic:"بَلْ يَهْمِسُ بِالْمُعْجِزَةِ",segs:[{ar:"بَلْ يَهْمِسُ",uz:"balki shivirlaydi"},{ar:"بِالْمُعْجِزَةِ",uz:"mo‘jiza haqida"}],full_uz:"Balki mo‘jiza haqida shivirlaydi.",note:"الْمُعْجِزَةُ — mo‘jiza."},
{num:583,time:"00:54:19,539 --> 00:54:33,099",arabic:"السَّمَاءُ تَتَلَأْلَأُ، الْهَوَاءُ سَاكِنٌ، وَفِي لَحَظَاتٍ نَادِرَةٍ تَشْعُرُ أَنَّ الْكَوْنَ كُلَّهُ حَيَّةٌ، يَتَحَرَّكُ أَمَامَكَ فِي سَجْدَةٍ مِنْ نُورٍ",segs:[{ar:"السَّمَاءُ تَتَلَأْلَأُ",uz:"osmon yaltiraydi"},{ar:"الْهَوَاءُ سَاكِنٌ",uz:"havo sokin"},{ar:"وَفِي لَحَظَاتٍ نَادِرَةٍ",uz:"va noyob lahzalarda"},{ar:"تَشْعُرُ أَنَّ الْكَوْنَ كُلَّهُ حَيَّةٌ",uz:"butun koinot tirikdek his qilasiz"},{ar:"يَتَحَرَّكُ أَمَامَكَ",uz:"ko‘z oldingizda harakatlanadi"},{ar:"فِي سَجْدَةٍ مِنْ نُورٍ",uz:"nurdan sajdada"}],full_uz:"Osmon yaltiraydi, havo sokin, noyob lahzalarda esa butun koinot tirikdek, ko‘z oldingizda nurdan sajda qilgandek harakatlanayotganini his qilasiz.",note:null},
{num:584,time:"00:54:33,099 --> 00:54:45,339",arabic:"يُمْكِنُكَ رُؤْيَةُ هَذِهِ الْأَنْوَارِ فِي النُّرْوِيجِ وَآيْسْلَنْدَا وَفِنْلَنْدَا وَكَنَدَا وَأَلَاسْكَا",segs:[{ar:"يُمْكِنُكَ رُؤْيَةُ هَذِهِ الْأَنْوَارِ",uz:"bu yog‘dularni ko‘rishingiz mumkin"},{ar:"فِي النُّرْوِيجِ وَآيْسْلَنْدَا",uz:"Norvegiya va Islandiyada"},{ar:"وَفِنْلَنْدَا وَكَنَدَا وَأَلَاسْكَا",uz:"Finlyandiya, Kanada va Alyaskada"}],full_uz:"Bu yog‘dularni Norvegiya, Islandiya, Finlyandiya, Kanada va Alyaskada ko‘rishingiz mumkin.",note:null},
{num:585,time:"00:54:45,339 --> 00:54:51,759",arabic:"حَيْثُ تَنْعَكِسُ الْأَضْوَاءُ عَلَى الْبُحَيْرَاتِ الْمُتَجَمِّدَةِ وَالْجِبَالِ الْمَكْسُوَّةِ بِالثَّلْجِ",segs:[{ar:"حَيْثُ تَنْعَكِسُ الْأَضْوَاءُ",uz:"u yerda yog‘dular aks etadi"},{ar:"عَلَى الْبُحَيْرَاتِ الْمُتَجَمِّدَةِ",uz:"muzlagan ko‘llarda"},{ar:"وَالْجِبَالِ الْمَكْسُوَّةِ بِالثَّلْجِ",uz:"va qor bilan qoplangan tog‘larda"}],full_uz:"U yerda yog‘dular muzlagan ko‘llar va qor bilan qoplangan tog‘larda aks etadi.",note:"الْمَكْسُوُّ — qoplangan."},
{num:586,time:"00:54:51,759 --> 00:54:56,819",arabic:"فَتَتَحَوَّلُ الْأَرْضُ إِلَى عَالَمٍ مِنْ حُلْمٍ وَلَوْنٍ وَصَمْتٍ",segs:[{ar:"فَتَتَحَوَّلُ الْأَرْضُ",uz:"shunda yer aylanadi"},{ar:"إِلَى عَالَمٍ مِنْ حُلْمٍ وَلَوْنٍ وَصَمْتٍ",uz:"tush, rang va sukunatdan iborat olamga"}],full_uz:"Shunda yer tush, rang va sukunatdan iborat bir olamga aylanadi.",note:null},
{num:587,time:"00:55:03,099 --> 00:55:09,559",arabic:"نَرْحَلُ شَرْقًا إِلَى قَلْبِ الْيَابَانِ",segs:[{ar:"نَرْحَلُ شَرْقًا",uz:"sharqqa yo‘l olamiz"},{ar:"إِلَى قَلْبِ الْيَابَانِ",uz:"Yaponiyaning yuragiga"}],full_uz:"Sharqqa, Yaponiyaning yuragiga yo‘l olamiz.",note:null},
{num:588,time:"00:55:09,559 --> 00:55:12,880",arabic:"حَيْثُ تَتَلَاقَى الْعَرَاقَةُ بِالسَّكِينَةِ",segs:[{ar:"حَيْثُ تَتَلَاقَى الْعَرَاقَةُ",uz:"u yerda qadimiylik uchrashadi"},{ar:"بِالسَّكِينَةِ",uz:"sokinlik bilan"}],full_uz:"U yerda qadimiylik sokinlik bilan uchrashadi.",note:"الْعَرَاقَةُ — qadimiylik, tarixiy chuqurlik."},
{num:589,time:"00:55:12,880 --> 00:55:15,519",arabic:"وَيَتَنَاغَمُ الْجَمَالُ مَعَ التَّأَمُّلِ",segs:[{ar:"وَيَتَنَاغَمُ الْجَمَالُ",uz:"va go‘zallik hamohanglashadi"},{ar:"مَعَ التَّأَمُّلِ",uz:"tafakkur bilan"}],full_uz:"Va go‘zallik tafakkur bilan hamohanglashadi.",note:"تَنَاغَمَ — hamohang bo‘lmoq, uyg‘unlashmoq."},
{num:590,time:"00:55:15,519 --> 00:55:17,480",arabic:"إِنَّهَا كِيُوتُو",segs:null,full_uz:"Bu Kioto.",note:null},
{num:591,time:"00:55:17,480 --> 00:55:21,539",arabic:"مَدِينَةُ الْمَعَابِدِ وَالْحَدَائِقِ وَالرُّوحِ الْهَادِئَةِ",segs:[{ar:"مَدِينَةُ الْمَعَابِدِ وَالْحَدَائِقِ",uz:"ibodatxonalar va bog‘lar shahri"},{ar:"وَالرُّوحِ الْهَادِئَةِ",uz:"va sokin ruh shahri"}],full_uz:"Ibodatxonalar, bog‘lar va sokin ruh shahri.",note:null},
{num:592,time:"00:55:21,539 --> 00:55:27,679",arabic:"كَانَتْ يَوْمًا عَاصِمَةً لِلْإِمْبِرَاطُورِيَّةِ",segs:[{ar:"كَانَتْ يَوْمًا",uz:"bir vaqtlar edi"},{ar:"عَاصِمَةً لِلْإِمْبِرَاطُورِيَّةِ",uz:"imperiyaning poytaxti"}],full_uz:"Bir vaqtlar imperiyaning poytaxti bo‘lgan.",note:null},
{num:593,time:"00:55:27,679 --> 00:55:33,519",arabic:"وَالْيَوْمَ تَحْتَضِنُ أَكْثَرَ مِنْ أَلْفٍ وَسِتِّمِائَةِ مَعْبَدٍ وَمَزَارٍ",segs:[{ar:"وَالْيَوْمَ تَحْتَضِنُ",uz:"bugun esa bag‘rida saqlaydi"},{ar:"أَكْثَرَ مِنْ أَلْفٍ وَسِتِّمِائَةِ مَعْبَدٍ وَمَزَارٍ",uz:"ming olti yuzdan ortiq ibodatxona va ziyoratgohni"}],full_uz:"Bugun esa bag‘rida ming olti yuzdan ortiq ibodatxona va ziyoratgohni saqlaydi.",note:"مَزَارٌ — ziyoratgoh."},
{num:594,time:"00:55:33,519 --> 00:55:39,639",arabic:"كُلٌّ مِنْهَا لَوْحَةٌ فَنِّيَّةٌ مِنْ خَشَبٍ وَحَجَرٍ وَضَوْءٍ",segs:[{ar:"كُلٌّ مِنْهَا",uz:"ularning har biri"},{ar:"لَوْحَةٌ فَنِّيَّةٌ",uz:"san’at asari"},{ar:"مِنْ خَشَبٍ وَحَجَرٍ وَضَوْءٍ",uz:"yog‘och, tosh va nurdan"}],full_uz:"Ularning har biri yog‘och, tosh va nurdan yaratilgan bir san’at asaridir.",note:null},
{num:595,time:"00:55:39,639 --> 00:55:47,940",arabic:"فِي مَعَابِدِ كِينْكَاكُوجِي الذَّهَبِيِّ وَكِيُومِيزُودِيرَا وَنَانْزَنْجِي",segs:[{ar:"فِي مَعَابِدِ كِينْكَاكُوجِي الذَّهَبِيِّ",uz:"oltin Kinkaku-ji ibodatxonasida"},{ar:"وَكِيُومِيزُودِيرَا وَنَانْزَنْجِي",uz:"va Kiyomizu-dera hamda Nanzen-ji ibodatxonalarida"}],full_uz:"Oltin Kinkaku-ji, Kiyomizu-dera va Nanzen-ji ibodatxonalarida.",note:null},
{num:596,time:"00:55:47,940 --> 00:55:51,399",arabic:"تَنْسَابُ الْجَمَالِيَّاتُ فِي صَمْتٍ مُطْمَئِنٍّ",segs:[{ar:"تَنْسَابُ الْجَمَالِيَّاتُ",uz:"go‘zalliklar oqib taraladi"},{ar:"فِي صَمْتٍ مُطْمَئِنٍّ",uz:"xotirjam sukunatda"}],full_uz:"Go‘zalliklar xotirjam sukunatda oqib taraladi.",note:"الْجَمَالِيَّاتُ — estetik go‘zalliklar."},
{num:597,time:"00:55:51,399 --> 00:55:54,119",arabic:"حِجَارَةٌ مُغَطَّاةٌ بِالطُّحْلُبِ",segs:null,full_uz:"Mox bilan qoplangan toshlar.",note:"الطُّحْلُبُ — mox."},
{num:598,time:"00:55:54,119 --> 00:55:58,839",arabic:"وَجُسُورٌ خَشَبِيَّةٌ تَعْبُرُ بِرَكًا سَاكِنَةً",segs:[{ar:"وَجُسُورٌ خَشَبِيَّةٌ",uz:"va yog‘och ko‘priklar"},{ar:"تَعْبُرُ بِرَكًا سَاكِنَةً",uz:"sokin hovuzlardan o‘tadi"}],full_uz:"Va yog‘och ko‘priklar sokin hovuzlardan o‘tadi.",note:null},
{num:599,time:"00:55:58,839 --> 00:56:03,239",arabic:"كَأَنَّكَ تَسِيرُ فِي حُلْمٍ مَغْمُورٍ بِسَلَامٍ قَدِيمٍ",segs:[{ar:"كَأَنَّكَ تَسِيرُ فِي حُلْمٍ",uz:"go‘yo tush ichida yurgandek"},{ar:"مَغْمُورٍ بِسَلَامٍ قَدِيمٍ",uz:"qadimiy tinchlikka cho‘milgan"}],full_uz:"Go‘yo qadimiy tinchlikka cho‘mgan tush ichida yurgandek.",note:"مَغْمُورٌ — cho‘mgan, to‘lib ketgan."},
{num:600,time:"00:56:03,239 --> 00:56:09,839",arabic:"وَفِي الرَّبِيعِ تَتَسَاقَطُ أَزْهَارُ الْكَرَزِ كَالْمَطَرِ الْوَرْدِيِّ",segs:[{ar:"وَفِي الرَّبِيعِ",uz:"bahorda"},{ar:"تَتَسَاقَطُ أَزْهَارُ الْكَرَزِ",uz:"olcha gullari to‘kiladi"},{ar:"كَالْمَطَرِ الْوَرْدِيِّ",uz:"pushti yomg‘ir kabi"}],full_uz:"Bahorda olcha gullari pushti yomg‘ir kabi to‘kiladi.",note:null},
{num:601,time:"00:56:09,839 --> 00:56:13,920",arabic:"وَفِي الْخَرِيفِ تَتَّقِدُ الْأَوْرَاقُ بِلَوْنِ النَّارِ",segs:[{ar:"وَفِي الْخَرِيفِ",uz:"kuzda"},{ar:"تَتَّقِدُ الْأَوْرَاقُ",uz:"barglar lovullaydi"},{ar:"بِلَوْنِ النَّارِ",uz:"olov rangida"}],full_uz:"Kuzda barglar olov rangida lovullaydi.",note:"تَتَّقِدُ — lovullamoq, yonib turmoq."},
{num:602,time:"00:56:13,920 --> 00:56:17,900",arabic:"لَكِنَّ سِحْرَ كِيُوتُو لَيْسَ فِي أَلْوَانِهَا فَقَطْ",segs:[{ar:"لَكِنَّ سِحْرَ كِيُوتُو",uz:"ammo Kiotoning jozibasi"},{ar:"لَيْسَ فِي أَلْوَانِهَا فَقَطْ",uz:"faqat uning ranglarida emas"}],full_uz:"Ammo Kiotoning jozibasi faqat uning ranglarida emas.",note:"سِحْرٌ — joziba, sehr."},
{num:603,time:"00:56:17,900 --> 00:56:20,880",arabic:"بَلْ فِي إِحْسَاسِهَا الْعَمِيقِ بِالسَّكِينَةِ",segs:[{ar:"بَلْ فِي إِحْسَاسِهَا الْعَمِيقِ",uz:"balki uning chuqur hissida"},{ar:"بِالسَّكِينَةِ",uz:"sokinlik haqidagi"}],full_uz:"Balki uning chuqur sokinlik hissidadir.",note:null},
{num:604,time:"00:56:20,880 --> 00:56:25,260",arabic:"فِي خَشْخَشَةِ الْخَيْزُرَانِ وَرَنِينِ الْأَجْرَاسِ الْبَعِيدِ",segs:[{ar:"فِي خَشْخَشَةِ الْخَيْزُرَانِ",uz:"bambukning shitirlashida"},{ar:"وَرَنِينِ الْأَجْرَاسِ الْبَعِيدِ",uz:"va uzoqdagi qo‘ng‘iroqlar jarangida"}],full_uz:"Bambukning shitirlashi va uzoqdagi qo‘ng‘iroqlar jarangida.",note:"خَشْخَشَةٌ — shitirlash."},
{num:605,time:"00:56:25,260 --> 00:56:28,880",arabic:"وَعِطْرِ الْبَخُورِ الَّذِي يَمْلَأُ الرُّوحَ طُمَأْنِينَةً",segs:[{ar:"وَعِطْرِ الْبَخُورِ",uz:"va xushbo‘y tutatqi iforida"},{ar:"الَّذِي يَمْلَأُ الرُّوحَ طُمَأْنِينَةً",uz:"ruhni xotirjamlikka to‘ldiradigan"}],full_uz:"Va ruhni xotirjamlikka to‘ldiradigan tutatqi iforida.",note:"الْبَخُورُ — tutatqi, xushbo‘y tutun."},
{num:606,time:"00:56:29,460 --> 00:56:37,039",arabic:"عَلَى امْتِدَادِ سُهُولٍ ضَبَابِيَّةٍ فِي قَلْبِ مِيَانْمَار",segs:[{ar:"عَلَى امْتِدَادِ سُهُولٍ ضَبَابِيَّةٍ",uz:"tumanli tekisliklar bo‘ylab"},{ar:"فِي قَلْبِ مِيَانْمَار",uz:"Myanma yuragida"}],full_uz:"Myanma yuragidagi tumanli tekisliklar bo‘ylab.",note:null},
{num:607,time:"00:56:37,039 --> 00:56:41,140",arabic:"تَنْهَضُ آلَافُ الْمَعَابِدِ الْقَدِيمَةِ مِنَ الْأَرْضِ",segs:[{ar:"تَنْهَضُ آلَافُ الْمَعَابِدِ الْقَدِيمَةِ",uz:"minglab qadimiy ibodatxonalar qad rostlaydi"},{ar:"مِنَ الْأَرْضِ",uz:"yerdan"}],full_uz:"Minglab qadimiy ibodatxonalar yerdan qad rostlab turadi.",note:"تَنْهَضُ — qad rostlamoq, ko‘tarilmoq."},
{num:608,time:"00:56:41,140 --> 00:56:44,840",arabic:"كَأَنَّهَا هَمَسَاتٌ مِنْ زَمَنٍ بَعِيدٍ",segs:[{ar:"كَأَنَّهَا هَمَسَاتٌ",uz:"go‘yo shivirlar"},{ar:"مِنْ زَمَنٍ بَعِيدٍ",uz:"uzoq zamondan qolgan"}],full_uz:"Go‘yo uzoq zamondan qolgan shivirlardek.",note:"هَمْسَةٌ — shivir."},
{num:609,time:"00:56:44,840 --> 00:56:50,140",arabic:"إِنَّهَا بَاغَانُ الْحُلْمُ الْحَجَرِيُّ الَّذِي لَا يَشِيخُ",segs:[{ar:"إِنَّهَا بَاغَانُ",uz:"bu Bagan"},{ar:"الْحُلْمُ الْحَجَرِيُّ",uz:"toshdan yaralgan tush"},{ar:"الَّذِي لَا يَشِيخُ",uz:"qarimaydigan"}],full_uz:"Bu qarimaydigan tosh tush — Bagan.",note:"يَشِيخُ — qariyamoq."},
{num:610,time:"00:56:50,880 --> 00:56:58,420",arabic:"بُنِيَتْ بَيْنَ الْقَرْنِ التَّاسِعِ وَالثَّالِثَ عَشَرَ",segs:[{ar:"بُنِيَتْ",uz:"qurilgan"},{ar:"بَيْنَ الْقَرْنِ التَّاسِعِ وَالثَّالِثَ عَشَرَ",uz:"to‘qqizinchi va o‘n uchinchi asrlar oralig‘ida"}],full_uz:"U to‘qqizinchi va o‘n uchinchi asrlar oralig‘ida qurilgan.",note:null},
{num:611,time:"00:56:58,420 --> 00:57:02,660",arabic:"حِينَ كَانَتْ هَذِهِ الْأَرْضُ قَلْبَ مَمْلَكَةٍ عَظِيمَةٍ",segs:[{ar:"حِينَ كَانَتْ هَذِهِ الْأَرْضُ",uz:"o‘sha paytda bu yer"},{ar:"قَلْبَ مَمْلَكَةٍ عَظِيمَةٍ",uz:"buyuk qirollikning yuragi edi"}],full_uz:"O‘sha paytda bu yer buyuk qirollikning yuragi edi.",note:null},
{num:612,time:"00:57:02,660 --> 00:57:05,559",arabic:"حَيْثُ امْتَزَجَ الْإِيمَانُ بِالْفَنِّ",segs:null,full_uz:"U yerda iymon san’at bilan qorishgan.",note:"امْتَزَجَ — qorishmoq."},
{num:613,time:"00:57:05,559 --> 00:57:07,880",arabic:"فَصَارَ الْحَجَرُ صَلَاةً",segs:null,full_uz:"Shunda tosh ibodatga aylandi.",note:null},
{num:614,time:"00:57:07,880 --> 00:57:11,380",arabic:"وَالنَّقْشُ تَسْبِيحًا صَامِتًا",segs:null,full_uz:"Naqsh esa jimjit tasbehga aylandi.",note:"النَّقْشُ — naqsh, o‘yma bezak."},
{num:615,time:"00:57:11,380 --> 00:57:21,119",arabic:"عِنْدَ الْفَجْرِ يَنْسَابُ الضَّوْءُ الذَّهَبِيُّ عَلَى آلَافِ الْقِبَابِ",segs:[{ar:"عِنْدَ الْفَجْرِ",uz:"tong otganda"},{ar:"يَنْسَابُ الضَّوْءُ الذَّهَبِيُّ",uz:"oltin nur oqib tushadi"},{ar:"عَلَى آلَافِ الْقِبَابِ",uz:"minglab gumbazlar ustiga"}],full_uz:"Tong otganda oltin nur minglab gumbazlar ustiga oqib tushadi.",note:"يَنْسَابُ — ravon oqmoq, sirg‘alib tushmoq."},
{num:616,time:"00:57:21,119 --> 00:57:25,559",arabic:"فَتَخْتَرِقُ الْأَبْرَاجُ الضَّبَابَ كَأَنَّهَا تَدْعُو السَّمَاءَ",segs:[{ar:"فَتَخْتَرِقُ الْأَبْرَاجُ الضَّبَابَ",uz:"minoralar tumanni yorib o‘tadi"},{ar:"كَأَنَّهَا تَدْعُو السَّمَاءَ",uz:"go‘yo osmonni chorlayotgandek"}],full_uz:"Shunda minoralar go‘yo osmonni chorlayotgandek tumanni yorib o‘tadi.",note:"اخْتَرَقَ — yorib o‘tmoq."},
{num:617,time:"00:57:25,559 --> 00:57:30,519",arabic:"وَمِنَ الْأَعْلَى فِي سُكُونِ مِنْطَادٍ يُحَلِّقُ فَوْقَ الْوَادِي",segs:[{ar:"وَمِنَ الْأَعْلَى",uz:"yuqoridan"},{ar:"فِي سُكُونِ مِنْطَادٍ",uz:"sokin parvozdagi shardan"},{ar:"يُحَلِّقُ فَوْقَ الْوَادِي",uz:"vodiy ustida uchayotgan"}],full_uz:"Vodiy ustida uchayotgan shar ichidagi sokin parvozdan yuqoriga qaraganda.",note:"مِنْطَادٌ — havo shari."},
{num:618,time:"00:57:30,519 --> 00:57:34,079",arabic:"تَبْدُو بَاغَانُ كَبَحْرٍ مِنَ الْمَعَابِدِ",segs:[{ar:"تَبْدُو بَاغَانُ",uz:"Bagan ko‘rinadi"},{ar:"كَبَحْرٍ مِنَ الْمَعَابِدِ",uz:"ibodatxonalar dengizidek"}],full_uz:"Bagan ibodatxonalar dengizidek ko‘rinadi.",note:null},
{num:619,time:"00:57:34,079 --> 00:57:38,019",arabic:"يَلْمَعُ تَحْتَ شَمْسٍ آسِيَوِيَّةٍ خَجُولَةٍ",segs:[{ar:"يَلْمَعُ",uz:"yarqiraydi"},{ar:"تَحْتَ شَمْسٍ آسِيَوِيَّةٍ خَجُولَةٍ",uz:"uyatchan Osiyo quyoshi ostida"}],full_uz:"U uyatchan Osiyo quyoshi ostida yarqiraydi.",note:"خَجُولٌ — uyatchan, xijolatli."},
{num:620,time:"00:57:38,019 --> 00:57:45,619",arabic:"كُلُّ مَعْبَدٍ هُنَا يَحْمِلُ حِكَايَةً",segs:[{ar:"كُلُّ مَعْبَدٍ هُنَا",uz:"bu yerdagi har bir ibodatxona"},{ar:"يَحْمِلُ حِكَايَةً",uz:"bir hikoyani olib yuradi"}],full_uz:"Bu yerdagi har bir ibodatxona bir hikoyani olib yuradi.",note:null},
{num:621,time:"00:57:45,619 --> 00:57:52,280",arabic:"مِنْ مَعْبَدِ أَنَانْدَا الْفَخْمِ بِتَنَاسُقِهِ الْعَجِيبِ وَتَمَاثِيلِهِ الْمُتَلَأْلِئَةِ",segs:[{ar:"مِنْ مَعْبَدِ أَنَانْدَا الْفَخْمِ",uz:"hashamatli Ananda ibodatxonasidan"},{ar:"بِتَنَاسُقِهِ الْعَجِيبِ",uz:"uning ajoyib mutanosibligi bilan"},{ar:"وَتَمَاثِيلِهِ الْمُتَلَأْلِئَةِ",uz:"va yarqiragan haykallari bilan"}],full_uz:"Ajoyib mutanosibligi va yarqiragan haykallariga ega hashamatli Ananda ibodatxonasidan.",note:"تَنَاسُقٌ — mutanosiblik, uyg‘unlik."},
{num:622,time:"00:57:52,280 --> 00:57:58,780",arabic:"إِلَى الْمَعَابِدِ الصَّغِيرَةِ الَّتِي تُخَبِّئُ جِدَارِيَّاتٍ رَأَتِ الْقُرُونَ تَمْضِي",segs:[{ar:"إِلَى الْمَعَابِدِ الصَّغِيرَةِ",uz:"kichik ibodatxonalargacha"},{ar:"الَّتِي تُخَبِّئُ جِدَارِيَّاتٍ",uz:"devoriy rasmlarni yashiradigan"},{ar:"رَأَتِ الْقُرُونَ تَمْضِي",uz:"asrlar o‘tganini ko‘rgan"}],full_uz:"Asrlarning o‘tib ketganini ko‘rgan devoriy rasmlarni yashiradigan kichik ibodatxonalargacha.",note:"جِدَارِيَّةٌ — devoriy rasm."},
{num:623,time:"00:57:58,780 --> 00:58:00,340",arabic:"وَابْتَسَمَتْ بِصَبْرٍ",segs:null,full_uz:"Va ular sabr bilan tabassum qildi.",note:null},
{num:624,time:"00:58:00,340 --> 00:58:14,000",arabic:"مَعًا تَصْنَعُ هَذِهِ الْمَعَابِدُ مَشْهَدًا يَمْتَزِجُ فِيهِ الْحَجَرُ بِالْإِيمَانِ وَالزَّمَنُ بِالْأَبَدِيَّةِ",segs:[{ar:"مَعًا تَصْنَعُ هَذِهِ الْمَعَابِدُ مَشْهَدًا",uz:"birgalikda bu ibodatxonalar manzara yaratadi"},{ar:"يَمْتَزِجُ فِيهِ الْحَجَرُ بِالْإِيمَانِ",uz:"unda tosh iymon bilan qorishadi"},{ar:"وَالزَّمَنُ بِالْأَبَدِيَّةِ",uz:"va zamon abadiylik bilan"}],full_uz:"Bu ibodatxonalar birgalikda tosh iymon bilan, zamon esa abadiylik bilan qorishadigan bir manzara yaratadi.",note:"الْأَبَدِيَّةُ — abadiylik."},
{num:625,time:"00:58:14,000 --> 00:58:22,559",arabic:"كَأَنَّهَا شَهَادَةٌ عَلَى أَنَّ الرُّوحَ تَبْحَثُ دَائِمًا عَنْ خَالِقِهَا مَهْمَا تَغَيَّرَتِ الْحَضَارَاتُ",segs:[{ar:"كَأَنَّهَا شَهَادَةٌ",uz:"go‘yo bir guvohlik"},{ar:"عَلَى أَنَّ الرُّوحَ تَبْحَثُ دَائِمًا عَنْ خَالِقِهَا",uz:"ruh doimo o‘z Yaratuvchisini izlashi haqida"},{ar:"مَهْمَا تَغَيَّرَتِ الْحَضَارَاتُ",uz:"sivilizatsiyalar qanchalik o‘zgarmasin"}],full_uz:"Go‘yo sivilizatsiyalar qanchalik o‘zgarmasin, ruh doimo o‘z Yaratuvchisini izlashi haqidagi guvohlikdek.",note:"مَهْمَا — qanchalik ... bo‘lmasin."},
{num:626,time:"00:58:22,559 --> 00:58:34,079",arabic:"وَهَكَذَا تَنْتَهِي رِحْلَتُنَا بَيْنَ عَجَائِبِ هَذَا الْكَوْكَبِ",segs:[{ar:"وَهَكَذَا تَنْتَهِي رِحْلَتُنَا",uz:"shu tariqa sayohatimiz yakunlanadi"},{ar:"بَيْنَ عَجَائِبِ هَذَا الْكَوْكَبِ",uz:"bu sayyoraning mo‘jizalari orasida"}],full_uz:"Shu tariqa bu sayyoraning mo‘jizalari orasidagi sayohatimiz yakunlanadi.",note:null},
{num:627,time:"00:58:34,079 --> 00:58:37,679",arabic:"مِنْ قِمَمِ الْجِبَالِ إِلَى أَعْمَاقِ الْبِحَارِ",segs:null,full_uz:"Tog‘ cho‘qqilaridan dengizlar qa’rigacha.",note:null},
{num:628,time:"00:58:37,679 --> 00:58:44,239",arabic:"مِنْ مَعَابِدَ نَحَتَهَا الْإِنْسَانُ إِلَى آيَاتٍ صَاغَهَا الرَّحْمَنُ بِقُدْرَتِهِ",segs:[{ar:"مِنْ مَعَابِدَ نَحَتَهَا الْإِنْسَانُ",uz:"inson o‘ygan ibodatxonalardan"},{ar:"إِلَى آيَاتٍ صَاغَهَا الرَّحْمَنُ بِقُدْرَتِهِ",uz:"Rahmon O‘z qudrati bilan yaratgan oyatlargacha"}],full_uz:"Inson o‘ygan ibodatxonalardan Rahmon O‘z qudrati bilan yaratgan oyatlargacha.",note:"صَاغَ — shakl bermoq, yaratmoq."},
{num:629,time:"00:58:44,239 --> 00:58:54,679",arabic:"كُلُّ مَكَانٍ مَرَرْنَا بِهِ كَانَ رِسَالَةً",segs:[{ar:"كُلُّ مَكَانٍ مَرَرْنَا بِهِ",uz:"biz o‘tgan har bir joy"},{ar:"كَانَ رِسَالَةً",uz:"bir xabar edi"}],full_uz:"Biz o‘tgan har bir joy bir xabar edi.",note:null},
{num:630,time:"00:58:54,679 --> 00:58:58,119",arabic:"تَذْكِيرًا بِأَنَّ الْجَمَالَ لَيْسَ صُدْفَةً",segs:[{ar:"تَذْكِيرًا بِأَنَّ الْجَمَالَ",uz:"go‘zallik ... ekanini eslatuvchi"},{ar:"لَيْسَ صُدْفَةً",uz:"tasodif emasligini"}],full_uz:"Go‘zallik tasodif emasligini eslatuvchi.",note:null},
{num:631,time:"00:58:58,119 --> 00:59:01,299",arabic:"بَلْ أَثَرٌ مِنْ آثَارِ الْخَالِقِ فِي الْكَوْنِ",segs:[{ar:"بَلْ أَثَرٌ مِنْ آثَارِ الْخَالِقِ",uz:"balki Yaratuvchining asarlaridan bir iz"},{ar:"فِي الْكَوْنِ",uz:"koinotdagi"}],full_uz:"Balki koinotdagi Yaratuvchining asarlaridan bir iz.",note:"أَثَرٌ — iz, asar."},
{num:632,time:"00:59:01,299 --> 00:59:03,519",arabic:"يُدْهِشُنَا لِنَتَفَكَّرَ",segs:[{ar:"يُدْهِشُنَا",uz:"bizni hayratga soladi"},{ar:"لِنَتَفَكَّرَ",uz:"tafakkur qilishimiz uchun"}],full_uz:"Bizni tafakkur qilishimiz uchun hayratga soladi.",note:"تَفَكَّرَ — tafakkur qilmoq, chuqur o‘ylamoq."},
{num:633,time:"00:59:03,519 --> 00:59:05,879",arabic:"لَا لِنُعَظِّمَ الطَّبِيعَةَ",segs:[{ar:"لَا لِنُعَظِّمَ",uz:"ulug‘lash uchun emas"},{ar:"الطَّبِيعَةَ",uz:"tabiatni"}],full_uz:"Tabiatni ulug‘lash uchun emas.",note:"عَظَّمَ — ulug‘lamoq."},
{num:634,time:"00:59:05,879 --> 00:59:08,379",arabic:"بَلْ لِنُسَبِّحَ مَنْ أَبْدَعَهَا",segs:[{ar:"بَلْ لِنُسَبِّحَ",uz:"balki tasbeh aytish uchun"},{ar:"مَنْ أَبْدَعَهَا",uz:"uni ajoyib tarzda yaratgan Zotni"}],full_uz:"Balki uni ajoyib tarzda yaratgan Zotga tasbeh aytish uchun.",note:"أَبْدَعَ — mislsiz tarzda yaratmoq."},
{num:635,time:"00:59:08,379 --> 00:59:12,339",arabic:"فَأَيُّ هَذِهِ الْعَجَائِبِ",segs:null,full_uz:"Bu mo‘jizalarning qaysi biri?",note:null},
{num:636,time:"00:59:12,340 --> 00:59:14,160",arabic:"لَامَسَ قَلْبَكَ أَكْثَرَ",segs:[{ar:"لَامَسَ قَلْبَكَ",uz:"qalbingizga tegdi"},{ar:"أَكْثَرَ",uz:"ko‘proq"}],full_uz:"Qaysi biri qalbingizga ko‘proq tegdi?",note:"لَامَسَ — tegmoq, ta’sir qilmoq."},
{num:637,time:"00:59:14,160 --> 00:59:16,579",arabic:"اُكْتُبْ لَنَا فِي التَّعْلِيقَاتِ",segs:[{ar:"اُكْتُبْ لَنَا",uz:"bizga yozing"},{ar:"فِي التَّعْلِيقَاتِ",uz:"izohlarda"}],full_uz:"Bizga izohlarda yozing.",note:"التَّعْلِيقَاتُ — izohlar, kommentlar."},
{num:638,time:"00:59:16,579 --> 00:59:19,180",arabic:"وَدَعْنَا نَعْرِفْ إِلَى أَيِّ مَكَانٍ",segs:[{ar:"وَدَعْنَا نَعْرِفْ",uz:"bizga bildiring"},{ar:"إِلَى أَيِّ مَكَانٍ",uz:"qaysi joyga"}],full_uz:"Qaysi joyga ekanini bizga bildiring.",note:null},
{num:639,time:"00:59:19,180 --> 00:59:22,500",arabic:"تَحْلُمُ أَنْ تَأْخُذَكَ الرِّحْلَةُ الْقَادِمَةُ",segs:[{ar:"تَحْلُمُ",uz:"orzu qilasiz"},{ar:"أَنْ تَأْخُذَكَ الرِّحْلَةُ الْقَادِمَةُ",uz:"keyingi sayohat sizni olib borishini"}],full_uz:"Keyingi sayohat sizni qaysi joyga olib borishini orzu qilasiz?",note:null},
{num:640,time:"00:59:22,500 --> 00:59:27,780",arabic:"وَلَا تَنْسَ أَنْ تَدْعَمَنَا بِالْإِعْجَابِ وَالِاشْتِرَاكِ",segs:[{ar:"وَلَا تَنْسَ",uz:"unutmang"},{ar:"أَنْ تَدْعَمَنَا",uz:"bizni qo‘llab-quvvatlashni"},{ar:"بِالْإِعْجَابِ وَالِاشْتِرَاكِ",uz:"layk va obuna bilan"}],full_uz:"Bizni layk va obuna bilan qo‘llab-quvvatlashni unutmang.",note:"الِاشْتِرَاكُ — obuna bo‘lish."},
{num:641,time:"00:59:27,780 --> 00:59:30,960",arabic:"لِتُوَاصِلَ مَعَنَا هَذَا السَّفَرَ الْجَمِيلَ",segs:[{ar:"لِتُوَاصِلَ مَعَنَا",uz:"biz bilan davom ettirish uchun"},{ar:"هَذَا السَّفَرَ الْجَمِيلَ",uz:"bu go‘zal sayohatni"}],full_uz:"Bu go‘zal sayohatni biz bilan davom ettirish uchun.",note:null},
{num:642,time:"00:59:30,960 --> 00:59:32,920",arabic:"بَيْنَ آيَاتِ اللَّهِ فِي الْأَرْضِ",segs:null,full_uz:"Yerdagi Allohning oyatlari orasida.",note:null}
];

